window.IV=window.IV||{};IV.univ=IV.univ||{};IV.univ["u047"]={"univ":"서울대학교","reviews":[{"univ":"서울대학교","dept":"경영대학","jeonhyeong":"학생부종합(기회균형)","method":"면접실 대기-면접 고사장 앞 대기-면접-퇴장","notes":"면접대기실 가자마자 들고온 자료를 전부 볼 수 없기 때문에 일찍간다고 좋을게 없음꼬리질문 상당히 많이 하는데 그때는 그냥 자기생각을 자신있게 대답만 하면됨교수님들이 친절하셔서 긴장 안 해도 됨","qa":[{"q":"알바생자르기를 읽고 우리나라 노동구조 어떻게 생각하는지","a":"우선우리나라 노동구조는 수직적인 노동구조로 정규직과 비정규직간 불균형이 심합니다 반면이책에서 나오는 독일같은경우는 수평적조직구조로 비정규직 또한 노동안정성이 어느정도 보장됩니다"},{"q":"비정규직을 정규직으로 바꾸면 기업에게 불이익이 있지 않을까요","a":"인건비 차원에서는 그런 부분도 있으나 기업은 사회적책임까지 고려하여야하기에 우리나라는 이러한 부분이 개선되야 할 것 같다 생각"},{"q":"미국의 노동구조에 대해서는 어떻게 생각하나","a":"그 부분은 조사하지 못했습니다"},{"q":"리쇼어링현상에 대해 탐구하고 알게된점","a":"코로나 팬데믹 러시아 우크라이나전쟁같은 변화로 인해서 최근 기업들이 외국에 있던 자국 생산기지를 본국으로 회기하는 리쇼어링 현상이 활발이 일어나고 있습니다"},{"q":"리쇼어링현상의 문제점은 없는가","a":"인건비나 재료비차원에서 부담이 될 수 있습니다"},{"q":"그럼 학생이 말한거 처럼 기업들이 전부 리쇼어링할시 기업에게 피해가있지 않나","a":"전부 리쇼어링 한다기 보다는 기업은 적당히 손익을 계산하여 상황에 맞게 대처해야 할것 같습니다"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경영대학","jeonhyeong":"학생부종합(일반전형)","method":"제시문 기반 면접서울대학교 일반전형 기출문제는 입학처 홈페이지에 제시되어있음. 제시문이 매해 다르므로 기출 문제를 통하여 출제의 방향성을 잡고 준비해야 할 것으로 판단됨.","notes":"제시문을 보고 답을 못하면 힌트를 주심.대기시간이 짧으면 30분에서 길면 3시간이 넘는데, 가서 개인 자료 볼 수 없어서 다소 지루함.30분 준비시간을 주는데 이동 시간도 포함돼서 28분만 주심.교과 지식이 아닌 제시문을 기반으로 한 전문적이고 심층적인 질문에 대한 대답을 요구함.","qa":[],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(기회균형)","method":"생기부기반면접","notes":"면접관과의 거리가 매우 가깝고 10분이 생각보다 정말 짧게 느껴진다. 분위기는 꽤나 편안한 편이다.","qa":[{"q":"새마을 운동 및 경제 개발 5개년 계획에 대해 설명하고 왜 경제발전에 도움을 줬다고 생각했는지 설명해보세요.","a":"답변 내용이 기억이 나지 않습니다."},{"q":"독서토론 동아리 돈으로 살 수 없는 것은 무엇이라 생각하며 왜 그렇게 생각하나요","a":"돈으로 살 수 없는 것의 기준은 사회에 부정적 영향을 끼치는 것으로 평가. 마약과 성매매를 생각한다. 일각에선 마약은 개인의 인권을 돈 주고 구매하는 것이며, 성매매는 타인의 인격을 구매하는 것으로 두 개가 구분된다. 하지만 장기적으로 볼 때 마약 복용자가 타인에게 권유하고 마약 섭취 후 운전, 살인등의 피해를 입힌다는 점에서 본질적으로 다르지 않다고 생각한다."},{"q":"마약과 성매매는 이미 법적으로 금지된 것 아닌가?","a":"법적으로는 금지되어 있지만 뒷세계에서는 여전히 소비되고 있기에 법적으로 금지되어 있다고 해서 돈으로 사서는 안되는 것을 주장할 수 없는 것은 아니라고 생각한다.(다소 의역, 기억이 잘 안남)"},{"q":"성욕, 식욕을 2대 욕구라 하는데 신체 불구인 장애인들의 경우 성관계가 불가능한 상황인데. 성매매 등의 수단마저 금지한다면 그들의 인격적 욕구를 배척? 하는 것 아닌가?","a":"물론 개별적인 사례에서는 위와 같이 긍정적으로 받아들여질 수도 있다. 하지만 불법으로 지정되어 있다는 것은 보편적으로 사회에 부정적 영향을 끼치는 경우가 더 많기 때문이라고 생각한다. 개별 사례에는 긍정적일 수 있지만 그럼에도 부정적으로 생각되는 경우가 더 많을 것이라 생각한다."},{"q":"가상화폐가 실물 화폐를 대체할 수 없는 이유는 뭐라고 생각하는가?","a":"화폐는 기본적으로 명목화폐이다. 가상화폐는 그 가격의 변동성이 하루에도 수십배가 변동할 정도로 크기 때문에 실물 화폐의 역할을 대체하기에는 무리라고 생각한다."},{"q":"전세의 문제 및 왜 등장?","a":"전세사기 문제는 법의 시차 때문에 발생한다. 전세사기를 예방하기 위한 여러 예방책의 예방 시점에 기간이 있기에 피해를 입으며 특히 여러 뉴스에서 보고 알게된 사실은 처벌 강도가 매우 약하다는 것이다. 수십명에게 사기를 친 사람이 징역 10여년, 벌금 조금 받는 것을 보았다. 우리나라에만 있는 전세제도가 사라지는 것이 가장 긍정적이라고 생각한다."},{"q":"그렇다면 전세가 사라지는데는 오랜 시간이 걸릴텐데 그 때까지 대처방법은 없는가?","a":"정부에서 당장 처벌을 늘리거나 하는 것은 법적인 것으로 오래 걸린다. 따라서 정부에서 처벌의 관점보다는 주거지 관련 정보를 제대로 명시하도록 하는 체계를 만드는 것이 방법이 될 수 있다 생각한다. 개인의 입장에서도 꼼꼼히 확인하는 것이 필요하다."},{"q":"마지막으로 하고 싶은 말","a":"경제학과에 입학하여 여러가지 경제학적 지식을 쌓고 싶다. 또한 경제학적 지식을 쌓고 난 뒤 최근 이분법적인 분위기가 강화된 사회에 타인의 선택 혹은 행위를 분석하고 이해하는 방법을 사회에 공유함으로써 더 건전한 사회를 만드는데 기여하고 싶다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(일반전형)","method":"큰 대기실에서 대기하다 ‘복도’로 이동함. 복도에 간이 책상들 있고, 그곳에 앉아있다 조교님이 시작하라 하면 30분 준비 시작. 이후 복도 바로 옆 방들 중 하나에 들어감. 교수님들 앞에서 15분 발표 시작.수학문제. 실제 위치와 숫자가 다른 3개의 공이 있음.첫째 공은 위치1, 숫자3. 둘째 공은 위치 2, 숫자2. 셋째공은 위치 3, 숫자1임.정해진 상수 h를 위치에 곱하고... 뭐 숫자를 더하고... 복잡한 등비수열 계산.","notes":"서울대학교는 작년에 들은 것과는 달랐음. 연필 대신 볼펜 주고, 그냥 복도에 막 앉히고... 아마 면접환경이 달라도 긴장하지 않는 게 중요함.유일하게 대학 차원에서 먹을 거 나눠줌. 연고대는 앞에서 학생들이 나눠주는데...조가 나눠져있긴 한데 그냥 조마다 한명 씩 보내려고 그런거고, 한 공간에 모아놓음.화장실 진짜 안보내줌. 최대한 빨리 갔다 올 것.","qa":[{"q":"두 번 수행 후 공들의 숫자의 평균은?","a":"한번 수행 후 2, 두 번 수행 후 1/2h^2-3/2h+3"},{"q":"2024번 수행 후 공 1에 적인 숫자는?","a":"못품."},{"q":"세공의 일반항??","a":"기억 안남.사회과학 문제. 제시문 가는 자기실현적 예언에 대해 다루고, 사회적 차별받는 사람들이 자기실현적 예언으로 일탈하고, 다시 차별로 이어짐 제시. 제시문 나는 자기실현적 예언으로 죽음에 이르는 부두죽음, 제시문 다는 물가상승률 예측이 물가를 실제로 예측대로 움직이게 하는 경향이 있다고 설명."},{"q":"나와 다 비교","a":"나는 생물학적, 물리적 차원에서 죽음에 이르른 반면, 다 에서는 사회과학적 차원에서 결과가 일어남. 나는 개인적 차원에서 영향을 받은, 소규모 사건인 반면 다는 사회적 차원에서 영향을 받은, 대규모 사건임."},{"q":"제시문 가에서 사회적 차별받는 사람에 대해 구제방법. 여러 주체들 중 3가지 골라 답변.","a":"정책 입안자, 교육자, 차별 받는 당사자.나머지는 그냥 생각나는 대로 답변, 정책입안자의 경우 자기실현적 예언 또한 사회과학적 현상이므로 해결할 수 있다는 자기실현적 예언에 기반하여 악순환의 고리를 끊어내는 것이 중요하다고 답변."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"경제학부","jeonhyeong":"학생부종합(기회균형전형)","method":"구술면접","notes":"","qa":[{"q":"esg 경영에 대해 관심이 많은 것 같은데, esg에 대해 설명해보세요","a":"esg란, 환경의 e, 사회의 s, 지배구조의 g를 의미하는데, 사회적 가치를 경영에 투입하는 것을 의미합니다. 소비자 주권시대이고, 사람들이 더 이상 필요한 것을 소비하지 않습니다. 사회적으로 가치있고, 의미있는 것을 소비하므로, esg경영은 시대적 흐름이라고 생각합니다."},{"q":"그러면, g에 해당하는 지배구조는 어떻게 변화시킬 수 있나요?","a":"지배구조는, e나 s에 해당하는 사회적 가치를 더욱 잘 수용할 수 있도록 민주적인 의사결정을 강구하거나, 기존의 관료제에서 벗어난 탈관료제 형식, 또는 소비자의 의견을 원활히 받아들일 수 있는 소통의 창구를 형성하는 방식 등이 있을 수 있습니다."},{"q":"논술 시간에 그린벨트에 대해 토론했다고 나와있는데, 본인의 의견을 말해보세요","a":"저는 그린벨트 해제를 지역불균형 완화의 관점에서 긍정했습니다. 수도권 과밀화 현상이 지나치게 발생하고 있고, 균형발전이 어려운 현실에서 대부분의 그린벨트가 농촌과 어촌, 즉 1차 산업 위주의 지방에 편중되어있고, 저는 이러한 그린벨트를 해제하는 것이 지역균형발전을 달성할 수 있는 수단이 될 수 있다고 봤습니다."},{"q":"그러면, 지방에 수요가 중앙보다 좀 적다거나, 그런 현상으로 인해 오히려 지방의 개발이 어려울 수 있을 것 같은데 여기에 대해서는 어떻게 생각해요?","a":"저는 그런 문제는 지역의 문화적, 역사적, 산업적인 특색을 살린 산업 클러스터의 조성으로 해결할 수 있다고 생각합니다."},{"q":"그린벨트 조성이 농촌, 어촌 1차 산업 구조의 지역에 편중되어있다고 하는건 구체적인 자료나 수치를 직접 찾아보고 객관적으로 탐구한거에요?","a":"네 맞습니다"},{"q":"사회 문화 시간에 ‘긴급재난지원급이 한국 경제의 정상화에 기여하였는가?’에 대한 주제로 양적 조사 방식의 탐구를 시행했다는데 여기에 대해 구체적으로 말해보세요.","a":"우선 선행연구를 검토했습니다. 재난지원금 시행 전후의 소비자 심리지수, 가계 수입 전망 등 구체적인 수치를 확인한 결과 소비 심리의 진작과 수요의 확대라는 측면에서 재난지원금이 의미있었다고 판단헀습니다. 그 이후, 우리 학교 학생들을 대상으로 질문지법을 시행해, 재난지원금을 어떠한 용도로 사용했는가를 조사한 결과, 대부분의 학생이 외식 등 자영업에 그 금액을 사용했다고 하여 소비심리의 진작이라는 측면에서 의미있었다고 판단했습니다."},{"q":"자영업자에게 직접 지원금을 지급하는 것과 소비자에게 지급하는 것이 어떤 차이가 있고, 어느 것이 더 효율적인가요?","a":"저는 공급과잉의 측면에서 소비자 지급이 더욱 효율적이라고 생각합니다. 자영업자, 판매업자들은 미리 판매를 위해 준비해둔 상품 및 재료가 있고, 이것들을 충당하지 못한다면 공급량이 남아돌아 공급과잉이 발생합니다. 이러한 측면에서, 소비자에게 지원금을 지급하여 수요를 확대하는 것이 시장경제의 기본원리에 더욱 부합한 것 같습니다."},{"q":"KIKO 사태, knock-in 계약과 knock out 계약, 아직 기억나요?","a":"knock in 계약은 자산의 가격이 특정 수치에 도달하며 유효해지는 옵션이고, knock-out 계약은 자산의 가격이 특정 수치에 도달하면 무효해지는 옵션계약입니다. kiko는, 환율가격이 특정 수치 내에서 변동하면 수출기업에 이익, 그 최대와 최소 범위를 벗어나면 기업이 이익을 보는 구조로 형성되어, 리먼브라더스 사태 이후 환율이 급격하게 치솟자 수출기업이 피해를 본 사건으로 알고 있습니다."},{"q":"기본소득에 대해 탐구했다고 나와있는데, 구체적인 본인의 생각을 말해보세요.","a":"많은 미래학자들이 ai나 인공지능, 기계화의 확대로 인해 탈실업의 미래를 예견하고 있습니다. 저는, 노동 없는 미래 경제에서 기본소득이 기본적인 수요를 확대하거나, 수요량을 충족할 수 있다는 측면에서 경제의 활성화를 위해 지급될 수 있다고 생각합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"국어국문학과","jeonhyeong":"학생부종합(일반전형)","method":"제시문 면접. 어문과는 인문학 지문 하나, 사회과학 지문 하나 해서 총 두 지문을 풂. 제한 시간은 30분, 면접 시간은 15분임. 무슨 지문을 몇 분 안에 풀어야 한다는 규정은 없으나 15분 15분으로 나눠 푸는 연습을 하면 좋음. 제시문 면접을 보는 대표적인 타 학교가 연고대인데, 서울대는 이 학교들과 요구하는 답변 방식이 꽤 다름. 따라서 연고대 제시문 면접이 없다 하면 기출은 서울대만 보는 걸 추천. (시간 남으면 봐도 됨)연고대는 원하는 ‘답’이 존재하고 그걸 찾아서 제시하는 능력을 중시하는 듯. 반면 서울대는 답을 정해 놓지 않고, 여러 갈래 길을 주고 응시자의 견해를 궁금해 함. 빠른 시간 안에 본인만의 논리를 세워야 하고, 배경지식을 끌어올 수 있어야 함. 8시까지 입실이었고, 숙소에서 6시 반에 택시 잡아서 나갔는데 도착하니까 이미 거의 다 와 있었음. 입구에서 차로 들어가면 많이 막히는데 또 걸어가려면 한참이라 일찍 출발해야 함. 면접대기실에서 가방 제출하고 나면 자기 순서까지 아무것도 못 함. 책도 못 읽음. 본인은 끝 번호라 2시간 넘게 엎드려서 잤음.인문학 제시문 복기(가): 번역은 번역 텍스트를 모국어처럼 느낄 수 있게 착시 현상을 일으켜야 한다(나): 번역은 외국 여행을 하는 것처럼 이질성을 살려야 한다(다): 번역은 단지 의미 전달에 그치지 않고 번역하는 언어에 존재하는 이질적 요소를 모국어로 확장시킬 수 있어야 한다","notes":"","qa":[{"q":"(가), (나), (다) 번역에 대한 입장 비교, 본인의 독서 활동에 비추어 어떤 입장이 타당한지 설명","a":"(가)랑 (다)를 묶어서 모국어와 번역하는 언어의 연결을 중시하는 관점, (나)는 모국어와 번역하는 언어의 차이를 중시하는 관점으로 나눔. (가)랑 (다) 구체적으로 설명하고 공통점 다시 한 번 설명. (나) 구체적으로 설명. (가)랑 (다) 묶어서 얘기해 놓고 차이점은 크게 언급을 안 해서 꼬리 질문으로 물어보셨음. (가와 다는 완전히 같은 입장인 건가요?) 아니라고 하고 차이점 설명 드림. (가)와 (다)가 타당하다. 외국 문학을 읽을 때 그 나라의 문화나 정서가 우리와 많이 다르면 공감과 몰입이 어렵기 때문에 모국어와의 연결이 필요하다고 주장. 국문과라 독서 내용은 양귀자 박완서 김유정 이런 쪽만 준비해 가서 외국 서적 사례를 들라길래 당황함. 구체적인 책 이름을 대고, (가)와 (다) 중에 하나를 골라서 다른 두 입장과 차이점 짚어 주면 더 좋았을 것 같음."},{"q":"(박스 내용: 번역 활동과 역사 해석 활동은 유사하다) 구체적 사례를 들어 (가), (나), (다)가 어떻게 역사를 바라볼지 설명","a":"역사 해석과 결부시켜서 각각 설명. (가)는 마치 오늘날 일어나는 일인 것처럼 해석, (나)는 과거를 과거로 해석, (다)는 과거 사실만을 전달하는 게 아니라 오늘날로 확장해 해석, 이런 식으로 답변함. 준비할 땐 가나다 전부 각각 사례를 들어야 하나 고민하다가 너무 오래 걸릴 것 같아서 관둠. 아니나 다를까 꼬리 질문으로 사례 들어줄 수 있냐고 물어보셨음. 잠시만 고민해봐도 되냐 여쭤보고 518 민주화운동 예시 들어서 가나다에 적용시킴. 사회과학 제시문 복기(가): 자기 충족적 예언 설명(나): ‘부두 죽음’ 설명(다): ‘물가 안정 목표제’ 설명"},{"q":"(가) 바탕으로 (나)와 (다) 비교","a":"공통점으로는 자기 충족적 예언이 적용된 사례고 사람들의 믿음이 실제 행위로 이어졌다. 차이점으로는 (나)는 동기가 두려움과 공포라면 (다)는 중앙은행에 대한 신뢰다. (나)는 부정적 사례, (다)는 긍정적 사례."},{"q":"(나)의 ㄱ(자기 충족적 예언이 공동체의 믿음으로 이어져 차별과 배제를 낳는 문제)을 해결하기 위해 할 수 있는 노력 설명(예시 집단 중 세 집단 골라서 설명)","a":"교육자: 차별과 배제를 함부로 하지 않도록 교육, 차별과 배제를 받는다 하더라도 자신이 실제로 반사회적 인간이 아닐 수 있다고 교육(자기 충족적 예언에 대한 교육)정책 입안자: 차별과 배제를 사후적으로 조치, 사전적으로 예방할 수 있는 정책 마련연구자: 교육자와 정책 입안자에게 연구자료 제시, 신뢰성 확보시간 남으면 생기부나 지원동기 질문하는 경우도 있다고 들었는데, 올해 문제는 전체적으로 시간이 오래 걸려서 질문 거의 안 하신 듯.기 타국문과는 개인 필기구 못 쓰게 하셨고 검은색 볼펜 빌려주심. (과마다 다름)유의사항준비실에 시계 없음. 수능 시계 차고 가서 그거 보면서 함. 15분 지나면 옆에서 먼저 풀던 분이 면접실로 이동하셔서 대충 알 수는 있음."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합(기회균형전형)","method":"2명의 교수님과 대면 면접. 생기부 기반 질문","notes":"독사 이빨을 모방한 여드름패치가 서울대에서 논문을 냈었다고 하시며 약간의 압박 질문이 들어옴. 대학에서 논문을 낸 것이 있으면 어느정도 읽어보는 것이 필요한 것 같다는 생각이 들었음.","qa":[{"q":"가우스 가속기가 무엇인가요?","a":"자석으로 쇠구슬을 가속시키는 하나의 장치, 전기력과 운동량 보존법칙 등으로 롤러코스터를 재현함."},{"q":"자연을 모방한 신소재에는 무엇이 있는가?","a":"독사의 이빨을 모방한 패치,-> 어떤 원리인가? 이빨이 휘어있기에 가장 적은 힘을 주고 가장 깊이 박히게 할 수 있는 구조이다"},{"q":"반장으로써 필요한 자질?","a":"공동체를 위해 희생과 헌신을 할 수 있는 능력. 고3때 반장을 하면서 학업이 중요했음에도 반을 위해 봉사하며 이러한 자질에 대해서 생각해봄."},{"q":"왜 수학적 모델링에 대한 탐구를 해보았는지?","a":"저의 목표인 유체에 대한 깊은 연구로 유체를 제어하고, 향후 연료전지 등과 연관한 탐구를 위해 유체에 대한 제어를 하는것이 필수. 이를 위해 수학적 모델링에 대해 공부해보면서 유체에 대한 제어의 기본적 이해를 돕기 위해 해보았음."},{"q":"연료전지와 유체의 제어가 무슨 연관?","a":"다양한 신재생에너지들의 효율을 높일 수 있고, 한가지 예시로 수소연료전지를 들자면 전지 내 수소분자, 산소분자나 전자의 흐름에 영향을 주며 전지의 효율성을 높일 수 있다고 생각함."},{"q":"학습을 하며 제일 어려웠던 기억은?","a":"나비에 스트로크 방정식을 탐구해보았던 기억. 유체의 흐름을 삼차원에서 파악해야하며 유체의 중력, 압력, 점성력을 x y z축에서 계산하며 이해의 어려움이 있었음. 하지만 기초 유체역학 책의 일부분을 발췌하여 이해하며 우력 등의 힘을 통해 과정을 단순화시키며 내용을 이해해봄."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"농경제사회학부","jeonhyeong":"학생부종합(지역균형전형)","method":"면접관2인, 생기부기반면접, 10분내외","notes":"생기부 다 알고있기, 지원동기와 학업계획, 자기소개, 마지막말은 다 외워서 가기,면접 대기하면서 아무것도 못봄, 핫팩도 내야하고 물도 거기서 주는 거 먹어야함, 생각보다 되게 편한 분위기 속에 면접 진행함","qa":[{"q":"지속가능발전 프로젝트에 대해 탐구했던데, 이에 대해 설명해주세요","a":"유엔에서 발표한 sdgs17을 보고 지속가능발전프로젝트에 대해 탐구했습니다.--"},{"q":"빈곤에 대해 관심이 생긴 이유","a":"제 꿈은 빈곤을 해결하는 경제연구원입니다. 왜 세계의 절반은 굶주리는가, 빈곤의 연대기, 생각의 지도라는 책을 읽으면서 빈곤의 근본적인 원인은 식량문제라는 사실을 알게 되었고, 식량문제를 해결하고싶다."},{"q":"농경제사회학부에 지원하게 된 동기와 학업계획","a":"빈곤을 해결하는 경제연구원이 되고싶습니다. 빈곤의 근본적인 원인은 식량문제이고, 식량문제는 농업과도 직결되는 문제이기 때문에, 농업자원경제학을 전공하여 자원을 효율적으로 연구하는 법을 공부하고 싶습니다. 농업자원경제학을 대학원까지 가서 공부하여 국제식량농업기구에 진출하여 빈곤을 해결하는 경제연구원으로 성장하고 싶습니다."},{"q":"학생부회장, 회장 역할을 하면서 가장 기억에 남는 일","a":"운동장 사용과 관련된 학년간 갈등을 해결했습니다. 각 학년의 입장을 들어보고 가장 적합한 해결안을 도출한 뒤에 꾸준한 모니터링을 통해 해결안을 수정해나가는 과정을 거치면서 모든 학생이 만족할만한 결론을 내렸습니다."},{"q":"마지막으로 하고 싶은 말","a":"저는 단순히 학업성적이 뛰어난 학생이기보다는 꾸준했던 학생이었다고 자부할 수 있습니다. 왜 세계의 절반은 굶주리는가, 빈곤의 종말, 빈곤의 연대기, 생각의 지도와 같은 책들을 읽으면서 빈곤과 경제에 대한 관심을 꾸준히 키워나갔고 빈곤을 해결하는 경제연구원이라는 꿈을 키워나갔습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"산림과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"학생부 기반 면접, 3배수, 면접관 2명, 10분 내외","notes":"접 당일에는 생각보다 차가 많아 붐빔.)두 분이 계셨는데 들어가니 교수님은 얼굴을 아는 분이었음. 홈페이지에서 교수님들 얼굴을 한 번 숙지하고 가는게 꽤 도움이 될 수 있음.뒤에서 두 번째 순서였는데 기다리는 동안 아무것도 할 수 없음. ( 약 1시간 정도 기다림.)생각보다 면접관님들이 밝은 표정을 해주셨기 때문에 긴장이 덜 됨.약 1분 정도 남았을 때 밖에서 노크를 해서 알려줌.","qa":[{"q":"저희 과에 지원하신 이유가 무엇인가요?","a":"제가 이 과에 지원한 이유에 ~"},{"q":"만약 저희 과에 오신다면 20년 정도 후에 어떤 일을 하실 것 같으세요?","a":"저는 산림과학부에 오게 된다면~"},{"q":"자율활동에 보니 독서 시간을 설정하고 꾸준히 독서를 하셨다고 되어 있는데 가장 인상 깊게 읽은 책 있다면 소개해줄래요?","a":"제가 가장 인상 깊게 읽은 책은 하이젠베르크의 저서 ‘부분과 전체’입니다. 생기부를 보시면 논술 시간의 활동에 활용하기도 하였는데요. 이 책에서 가장 기억에 남는 내용은 과학자의 책임에 관한 내용입니다. 이 책에서 하이젠베르크는~"},{"q":"화1 세특에 탐구한 내용이 저희 과와 관련이 깊네요. 모달과 같은 레이온 섬유에 대해 탐구하셨다 되어 있는데 어떤 내용인지 설명해주세요.","a":"우선 제가 이 활동을 한 동기에 대해 말씀드리겠습니다. 저는 축합중합, 첨가중합 등에 대해서 공부하며 합성 섬유 나일론에 대해서 자세히 알게 되었고 이런 합성 섬유가 만들어지는 과정에서 여러 화학 약품으로 인한 환경 오염이 일어나게 된다는 것을 알게 되었습니다. 좀 더 친환경적인 소재가 없는 지 알아보던 중 레이온 섬유라는 것에 대해 알게 되어 이에 대해 탐구했습니다. 레이온 섬유라 하면 나일론 같은 합성섬유와는 달리 중합 과정을 거치지는 않고 셀룰로스를 재생시켜 섬유로 다시 활용하는 소재로 알고 있습니다. 생기부에 기재되어 있는대로 레이온 합성섬유 실험도 진행했습니다. (교수님이 흥미를 보이시며 직접한 것인거냐 어려움은 없었냐고 물으심) 네 레이온 섬유 합성 실험이 ~과정인데 크게 복잡한 과정은 없어 어려움은 없었습니다."},{"q":"음 학생이 생각하는 친환경 소재란 무엇인가요?","a":"제가 생각하는 친환경 소재는 만들어지는 과정에서 환경오염이 없는 소재입니다. 하지만 저또한 소재가 만들어지는 과정에서 어쩔 수 없이 여러 화학 약품이 사용되는 것을 알고 있습니다. 그렇기 때문에 제가 생각하는 친환경 소재라고 하면 만들어지는 과정에서 발생하는 여러 환경 오염을 최소화하고 그 후에도 여러 가지 측면에서 환경 오염이 발생할 수 있는 문제들에 대해서 ~"},{"q":"약 30초 정도 남은 것 같은데 어필 시간 드리겠습니다.","a":"저는 제가 감히 서울대에 쓸 수 있을지는 몰랐습니다. 다만 운이 꽤 좋아 서울대에 지원할 수 있는 기회가 주어졌다고 생각합니다. ~~~서울대 면접을 준비하는 학생이라면 서울대 내부에 있는 호암교수회관에 묵는 것이 시간상 유리할 수 있음. (면"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"수의학과","jeonhyeong":"학생부종합(일반전형)","method":"mmi 면접 방식이라서 10분씩 5개 방 질문 받고 답하는 형식나머지 방은 기억 잘 안나서 1,4번방만 적을게요.","notes":"2,3,5번방은 그래프 해석, 공혈견 선택 문제, x-ray 방사선 노출 문제에 관한 것이었고 특별히 여기서 변별하겠다는 의도는 못 느꼈습니다. (쉬웠고 계속 웃어주셨고 편안하게 해주셔서) 이 두방이 제일 힘들었고 꼬리 질문도 많았습니다. 교수님 두분이 들어오셨는데 눈 똑바로 번갈아 가며 마주쳤고 웃으면서, 여유있게 목소리 크게 대답하고 왔습니다.","qa":[{"q":"현재 수의학은 가축들과 관련된 농경사회와 정보사회로 나아갈 때 어느 정도의 범위와 역할인지 설명해줄 수 있을까요?","a":"네, 현재 수의학이 ~한 상황에서 맡고 있는 범위와 역할에 대해 말씀드리겠습니다. 현대 사회에서는 사람들의 활동 범위가 넒어짐에 따라 매일 새로운 병원체들을 만나고 있습니다. 이러한 상황 속에서 저는 수의사들이 빠르게 효율적인 백신을 개발해야 한다고 생각합니다. 만약 그러한 백신을 만들어 내지 못한다면 사람들은 그러한 생명체들을 맞서싸워야 할 적으로 생각할 것입니다. 하지만 그들은 적이 아니고 저희와 함께 살아가야할 생명체들입니다. 더군다나 현재에는 가축 질병과 인수공통감염병이 혼합된 형태로 발전되어 가고 있습니다. 예를 들자면, SFTS, 큐열, AI(였는지 럼피스킨이었는지..) 등과 같은 질병들이 있습니다. 이렇게 나날이 발전되어 가는 병원체들에 대한 적절한 백신을 만들어 내고 해결책을 제시해주는 것이 수의사의 역할이라고 생각합니다."},{"q":"수의학이 언제부터 왜 시작되었는지 어떻게 생각하나요?","a":"수의학이란 동물들과 인간의 복지를 위해 힘쓰는 학문입니다. 수의학은 동물들에 대한 연구를 기반으로 하기때문에, 옛날부터 사람들과 함께해왔던 동물들을 연구할 학문이 필요해서 생겼다고 생각합니다."},{"q":"그럼 인공지능과 수의사와의 관계는 어떻게 될 것 같나요?","a":"인공지능과 수의사는 서로 협력해가며 발전해 나 갈 것 같습니다. 우선 수의사는 임상과 수의사 두 가지로 나뉘는데, 비임상적인 부분에서 먼저 설명 드리겠습니다. 비임상 수의사는 식품 검역, 수의장교, 실험 동물 관리 등 다양한 일을 하지만 그중에서 연구사,, 아니 연구원으로서의 수의사에서 말씀드리겠습니다. 인공지능을 활용한다면 면역 펩티도믹스와 같은 기술을 이용해 신약을 개발할 때 화학물질의 반응을 예측할 수 있을 것입니다. 이를 통해 더 빠르게 약을 개발할 수 있습니다. 또, 가축들의 질병을 모니터링하며 공중보건에도 기여할 것입니다. 그다음 임상적 측면에서 말씀드리겠습니다. 임상수의사는 반려동물 뿐 아니라 다양한 동물들의 질병을 진단하고 또 보다 더 정확한 진단을 하기 위해 인공지능을 사용할 것입니다."},{"q":"수의사에 대해 많이 알고 있는 것 같은데 학교생활 중 수의사가 되기 위해 한 활동을 이야기해보래요?","a":"네, 저는 수의사에게는 의사소통 능력, 지역에 대한 관심등 다양한 덕목이 필요하지만 그 중에서도 끊임없는 도전정신과 동물에 대한 공감 능력이 가장 중요하다고 생각합니다. 우선 저는 연구 정신을 기르기 위해 여러 번 실험을 시행 착오를 겪으며 해냈던 적이 있습니다. 예를들어, 2학년 때 플라스틱과 빨대를 이용하여..."},{"q":"아까 수의사에게 동물에 대한 관심이 중요하다고 하였잖아요. 그거 한 번 이야기해볼까요?","a":"네 저는 동물에 대한 공감을 기르기 위하여, 다양한 서적을 읽고 봉사활동을 진행하였습니다. 제가 인상깊게 읽었던 책은 ‘동물과의 대화’입니다. 이 책의 주인공인 템플 그랜딘은 자폐성 장애를 가지고 있습니다. 그녀는 동물들의 시선에서 동물들을 위한 여러 가지 시설을 제작하였습니다. 이 책을 계기로 저는 동물들의 입장에서 먼저 생각해보는 계기가 되었다고 할 수 있습니다."},{"q":"네,, 더 듣고 싶은데 시간이 없어서 생기부 질문 하나만 할게용. (용하셨던 거 같은데...), 꿀벌을 한때 좋아하셨나봐요. 꿀벌에 대한 질병이나 탐구해보았던 것을 이야기해보세요?","a":"꿀벌을 좋아합니다. 꿀벌은 다양한 질병에 걸림에도 불구하고 그에 대한 많은 백신이 개발되어 있지 않습니다. 저는 그래서 농가측에서 사용할 수 있는 진단키트와 바로아 응애를 막을 수 있는 rnai백신을 탐구해보았습니다."},{"q":"돌연변이가 생명체에게 어떤 영향을 미칠 수 있는지 설명해주세요.","a":"(아니 읽지도 않았는데...음..)유전자 돌연변이가 일어난다면 ASF 즉 아프리카돼지열병과 같은 변종 바이러스에 취약한 개체가 생길 수도 있습니다. 돌연변이에 적응한 또다른 바이러스가 발생하기 때문입니다."},{"q":"유전자 변이가 단백질 형성에 어떤 영향을 끼치는지 설명할 수 있을까요?","a":"우선 유전자가 단백질을 형성하기 위해서는 DNA의 전사 번역 과정을 거칩니다. 만약 유전자가 변형된 DNA에서 번형된 RNA가 생성되고 그로 인해 단백질이 이상하게 생선된다면.. 음.. 그러한 과정을 거친 것입니다."},{"q":"유전자 변형 기술을 이용한 성공사례가 있을까요?","a":"네 제가 꿀벌의 바로아 응애를 차단하기 위해 꿀벌의 장내세균의 유전자를 변형하여 생장에 필요한 단백질 생산을 막은 rnai간섭 백신에 대해 조사해본 경험이 있습니다. 꿀벌 장내 세균의 유전자 돌연변이를 이용하여 진드기의 성장을 막은 예시가 있습니다."},{"q":"그럼 유전자 돌연변이가 생긴 것을 어떻게 확인할 수 있을까요?","a":"그건 전기영동이나 염기서열 분석등을 통해 확인할 수 있습니다. 제가 3학년 때 PTC 미맹 제한효소 실험을 하였습니다. PTC 미맹이 걸린 사람은 C->G로 바뀌는 돌연변이가 일어납니다. 정상 사람의 염기서열을 분석할 수 있는 제한효소를 넣어준다면 그 부위가 잘립니다. 당연히 그럼 비정상적 사람은 잘리지 않습니다 이렇게 결론적으로 유전자의 크기나 개수 등이 달라져 색소(이때 색소가 생각 안 나서 진짜 당황....) 전기영동으로 확인할 수 있습니다."},{"q":"그럼 유전자 편집 기술을 설명해줄 수 있나요?","a":"유전자 편집 기술은 cas-9단백질이 상요됩니다. 이 단백질은 rna효소와 함께 작용합니다. 어떤 ; 유전자를 인식하는 rna효소가 그 유전자를 인식한다면, cas-9단백질의 그 끝을 자르는 역할을 합니다."},{"q":"아까 장내세균을 이용한 유전자 변형을 말하셨잖아요. 그럼 체내에 있는 물질을 가공할 수는 없을까요..?","a":"음..(고민하고.. 생각났다는 듯이) 있습니다! 병원체에 감염된 세포의 테로머레이스를 분해하는 것입니다. 텔로미어는 세포가 분열할 때 정확성을 높이기 위하여 일정 부분 소비됩니다. 이를 재생시켜주는 효소가 텔로머레이스입니다. 병원체에 감염된 세포의 계속된 감염을 막기 위해 그 세포의 텔로머레이스를 분해시켜주는 효소를..... (종침)"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"식물생산과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"10분, 면접관 두분이서 2대1면접. 생기부 기반","notes":"분위기 편안함. 처음에 분위기 푸는 질문 많이 하셨음.잘 들어주시지만 꼬리질문이 날카로움.","qa":[{"q":"물리학1을 늦게 수강했는데 식물생산과학부와 뚜렷한 연관은 없어보인다. 수강 이유는?","a":"물리학1은 기초적인 과학이라고 생각하여 과학 지식을 쌓기 위해 들었습니다. 학교의 선택과목 수강 관련 안내가 원활하지 않아 물리학1을 수강하지 못하였고 이후 기초 내용으로써 화학 등의 과목과 밀접히 연관되어 있다는 점에서 물리학1이 필요하다 판단했습니다. 학교에 직접 요청하여 물리학1 수업이 개설되었고, 늦게나마 들을 수 있었습니다."},{"q":"생기부를 보면 의약학 계열에 관심이 많은데 식물생산과학부와 어떻게 연관지을 수 있을지?","a":"저는 약용식물에 관련한 연구를 하고 싶습니다. 항암제, 아스피린을 포함한 많은 약들이 식물을 연구하여 발견되었습니다. 최근에도 식물들의 몰랐던 약용 효과들이 계속해서 발견되는 상황입니다. 약용식물 연구를 통해 식물의 새로운 활용성, 약용효과의 강화 등을 통해 사람들에게 도움이 되고 싶으며 식물 연구 발전에 기여하고 싶습니다. 따라서 식물, 특히 약용생물학을 배울 수 있는 식물생산과학부에 지원하였습니다."},{"q":"생명과학 탐구 동아리에서 가장 기억에 남는 활동은? 활동하며 있었던 어려움은?","a":"동식물 세포 관찰실험이 가장 기억에 남습니다. 현미경을 처음 직접 다루게 되어 재밌게 활동했던 것 같습니다. 그렇지만 동아리원들이 적극적으로 참여하지 않는 어려움이 있었습니다. 아무래도 동아리 활동이 직접적인 학업 성적에 들어가지 않아 자습을 원하는 친구들도 많았습니다. 저는 저부터 즐겁게 열심히 참여하였고 나중에는 동아리원 대부분이 자연스레 적극적으로 실험 활동에 참여하게 되었습니다."},{"q":"학생에게 ‘팔방미인’이라는 표현이 쓰였는데 왜 그런 표현이 사용되었다고 생각하는지?","a":"제 담임 선생님은 체육 선생님이셨습니다. 제가 체육 시간에 농구, 축구, 배드민턴 등의 다양한 운동에 열정적으로 참여하고 반장과 부반장을 맡아 반을 이끌며 친구들과도 잘 소통하는 등 학교 생활 전반에 걸쳐 매 순간 최선을 다했다고 생각합니다. 선생님께서 저의 그러한 부분을 좋게 봐주셔서 ‘팔방미인’ 같은 표현을 써 주셨다고 생각합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"심리학과","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 10분 간 진행","notes":"면접 들어가기 전에,, 서울대학교 사회과학대에서 잡곡바를 나눠주길래 먹고 면접을 봤는데 끝나고 보니 이에 뭐가 껴있더라고용 ㅠㅠ 꼭 면접 보기 전에 거울 보고 다 확인하고 들어가세용 엉엉슨. 끝나고 너무 슬펐음.. 그리고 야자라는 말도 야간자율학습으로 바꿔서 이야기했어야 했는데 까먹고 놓침. 긴장은 엄청하고 말도 잘 못함 ,, 준비한 거 반의 반도 안 나온 듯 넘 슬펏다~~","qa":[{"q":"30초 동안 지원동기 설명해보세요.","a":"초등학교 저학년 때부터 눈에는 빨간 색으로 보이는 사과가 실제로 파란색이라면 어떨까? 하는 식으로 인지에 대해 궁금해했었고 그러한 궁금증들이 이어져 심리학에 대한 관심이 되었습니다. 심리학과에 진학하여 이런 어린 시절의 궁금증들을 탐구하고 싶습니다."},{"q":"가장 인상 깊었던 활동?","a":"BCI 기술의 윤리적 문제에 대해서 탐구하고 자료가 더 이상 나오지 않아 아닐 세스의 ‘내가 된다는 것’을 읽었습니다. 예측기제로서의 뇌라는 저자의 관점이 뇌의 작용기제에 대한 저의 생각을 아예 바꾸었고, 인지가 어떻게 작동하는 지에 대한 저의 이해가 깊어지는 계기였습니다."},{"q":"DQN 강화학습과 스키너의 조작적 조건화를 비교한 내용 설명해주세요.","a":"2학년때 심리학 공동 교육 과정을 이수하며 스키너의 조작적 조건화를 배웠는데, 비둘기에게 돌기를 가르치는 내용이었습니다. 반응에 대해 보상을 하며 강화한다는 아이디어가 이전에 본 DQN 강화학습 과정과 유사하다는 생각이 들었습니다. 과정을 일대일로 비교하며 살펴보니 실제로도 매개변수를 조정하고 그에 대해 보상을 주는 과정이 유사했습니다. 이 탐구를 수행하며 인공지능의 기초 개념인 퍼셉트론도 심리학자가 고안했다는 사실을 알게 되었습니다. 심리학의 응용 분야가 제 생각보다 훨씬 더 넓을 수 있다는 깨달음을 얻은 활동이었습니다."},{"q":"살펴보니 수학, 과학, 인공지능 등 이과 학문에 관심이 많네요. 맞나요?","a":"네 맞습니다. 가장 기억에 남는 이과적인 활동은 우울증 자가 진단 프로그램을 코딩해본 경험인 것 같습니다. 정보 시간에 배운 개념들을 종합하여 스스로 프로그래밍을 해보고자 시도했고, 공인된 기준을 사용하기 위해 정신의학과에서 실제로 사용하는 dsm5판을 가지고 우울증 진단 기준을 세웠습니다. 조현병, 조울증 등 유사한 질환과도 구분하기 위해 관련 문항들도 고심해서 비전공자도 알기 쉬운 용어로 풀어 기제했던 기억이 납니다."},{"q":"이것저것 트라이를 많이 해보신 것 같은데, 실패한 경험은 없나요?","a":"전교회장으로서 학생들의 건의사항을 선생님들께 전달하고자 월례 간담회를 개최하고 심야 야자를 추진하였습니다. 월례 간담회에서 좋은 반응을 얻어 바로 심야 야자를 추진하고자 학생들에게 성급하게 긍정적인 답변을 받았다고 전달한 결과 학생들이 감독하시는 선생님이 계시지 않은 상태로 남아있는 상황이 발생하였습니다. 커뮤니케이션 과정에서의 오류가 있었다고 판단하고 교장 선생님을 비롯한 선생님들과 소통으로 오해를 바로잡고자 노력하고 학생들에게도 사과했던 실패한 경험이 있습니다. 조직 내에서 커뮤니케이션 과정에서 크로스 체크가 얼마나 중요한지 깨닫고 그 이후로는 두 번 이상 확인하고자 했던 것 같습니다."},{"q":"시간이 다 되었네요. 마지막으로 하고 싶은 말 있나요?","a":"이렇게 앞에 계신 두 분의 교수님과 이야기를 나누게 되어 영광입니다. 서울대학교에 진학하여 교수님들께 지도를 받으며 심리학 연구를 수행하는 것이 가장 좋은 길이겠지만, 혹여나 서울대학교에 진학하지 못하더라도 저에게 주어진 환경에서 최선을 다해 공부하고 있을테니 나중에 심리학자 대 심리학자로 다시 만나는 날이 오기를 기대하고 있겠습니다. 이야기 들어주셔서 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품ㆍ동물생명공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"ㆍ서류(생기부)기반 대면면접, 면접관 2 : 지원자 1ㆍ대기실 내에서 가번호 부여 후 가번호 순서대로 면접 진행ㆍ정확히 10분간 면접 진행","notes":"로와 관련 없는 분야일지라도 모든 생기부 활동을 꼼꼼히 분석하고 정리하는 것이 필요하다고 생각된다.대기실 입실 시간(08:20)이 지나면 본인이 보고 있던 자료를 포함한 모든 소지품을 큰 비닐봉투 안에 넣고 제출해야 한다. 면접 시작 시간이 9시이기 때문에 짧게는 40분, 길게는 2-3시간 동안 대기실에서 멍 때리고 있어야 한다.과목별 세특 질문보다는 진로활동, 자율활동에 기재된 내용에 대한 질문을 많이 하시는 듯 하다.면접시간 10분은 칼같이 지켜지고 대략 1분 정도 남았을 때 밖에서 알려주신다. 시간 압박이 있더라도 답변은 차분하고 침착하게 하자.","qa":[{"q":"우리 과에 지원하게 된 동기와 식품공학이라는 학문이 무엇이라고 생각하는지 말해줄래요?","a":"주변에 식품 섭취에 있어 어려움을 겪고 계시는 분들이 많아 이런 어려움을 극복하는 데에 도움이 되고 싶어 식품공학자라는 꿈을 꾸게 되었다고 답변함. 식품공학은 식품 개발, 제조뿐만 아니라 유통, 저장, 보관 등 식품 공정 전반을 관할하고 연구하는 학문이라고 답변함."},{"q":"생기부 보니까 유당불내증에 대해 조사한 것 같은데, 이에 대해 설명해줄래요?","a":"생기부 내용 기반으로 답변함. 락타아제라는 효소가 결핍되었을 경우 유당불내증이 발생할 수 있다고 답변함."},{"q":"아까 답변하면서 락타아제에 대해 설명했는데, 락타아제의 다른 이름이 뭔지 혹시 알고 있나요?","a":"고민하다가 결국 모르겠다고 답변함."},{"q":"지속가능성과 같은 요즘 트렌드를 반영했을 때, 식품 산업이 나아가야 하는 방향은 무엇일까요?","a":""},{"q":"그리고 사실 식품첨가물이라고 하면 소비자들은 부정적인 인상을 갖고 있는 경우가 많은데, 이를 해결하기 위해서는 어떻게 해야 할까요? 여기에 대한 본인 생각을 말해주세요.","a":"지속가능성이라는 트렌드를 보았을 때, 식품 업계는 ‘대체 식품’을 중심으로 발전해나가야 한다고 설명함. 식품첨가물에 대한 소비자들의 부정적인 인상을 타개하기 위해서는 기업 측면에서 식품첨가물에 대한 인식 개선 캠페인이나 광고 등을 진행하여야 한다고 답변함."},{"q":"생기부 보니까 1학년 때 네일아티스트라는 직업을 체험했네요? 어떤 경험이었고 무엇을 배웠는지 얘기해주세요.","a":"전혀 예상하지 못했던 질문이라 생각나는 대로 답변함. 네일 아티스트 체험을 통해 그때 처음으로 네일을 해보았는데 생각보다 무게감이 있었음을 느꼈고, 그 체험과 강연을 들으며 네일 및 뷰티 산업 전반에 대한 흐름을 이해할 수 있었다고 답변함."},{"q":"메틸셀룰로스를 이용한 튀김의 흡유량을 예측했다고 했는데 자세히 설명해줄래요?","a":"생기부 내용을 기반으로 답변함. 다만 실제 예측한 것이 아니라 쌀가루 기반의 튀김 흡유량을 예측해주는 ai프로그램이 있는데, 이것과 메틸셀룰로스를 이용한 튀김을 연계해보면 어떨까라는 구상을 해본 것이라고 답변함."},{"q":"생기부 보니까 모둠장을 많이 맡아본 것 같은데, 우리가 모둠활동하다 보면 참여 안하고 비협조적이고... 그런 팀원이 있잖아요? 이거에 대해 어떻게 생각하는 지 설명해주세요.","a":"그런 팀원들은 자신의 흥미에 맞지 않는, 혹은 자신이 잘 해낼 수 없으리라 생각하는 역할을 부여받았기 때문에 비협조적인 태도를 보이는 것이라고 답변함. 따라서 리더 역할을 맡았을 때, 각 팀원의 장점, 흥미, 적성, 특성 등등을 잘 분석하여 작은 역할이라도 그 각각의 팀원들이 가장 잘 수행해낼 수 있는 역할을 부여하는 방식으로 문제를 해결했다고 답변함."},{"q":"시간이 얼마 안 남았는데, 마지막으로 가장 인상깊었던 책이 있으면 소개해주세요.","a":"최낙언 교수님께서 쓰신 ‘맛의 원리’라는 책이 인상깊었다고 소개함. 정비각과 후비각의 관계에 대해 알게되어 흥미로웠다는 식으로 답변했으나 시간이 얼마 남지 않았다는 압박감에 다소 산만하게 답변함.전반적으로 압박 면접의 분위기는 아니었다. 다만 지원자가 당황할 만한 질문을 몇 개 하시는 듯 하다. 전공, 진"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"약학계열","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접이며, 면접 시간은 10분입니다.지원 동기도 없이 바로 시작했다, 교수님 두 분 중 한 분은 무표정이시고, 한 분은 계속 미소를 짓고 계셨다.","notes":"끝나기 1분 전에 노크해 주고 노크해도 이어서 그냥 말하면 된다. 교수님과의 거리는 가깝지도 멀지도 않은 편이었으며 의자뿐만 아니라 책상도 준다.1차 합격 후 받는 수험번호가 순서는 아니고 당일 대기실에서 면접 번호를 따로 받았다. 유의 사항 안내 후 대기실에서 자료를 보는 것이 불가능하다. 오직 물 마시는 것과 화장실 가는 것만 허용된다. 뒷 번호의 경우 2~3시간 이상 대기해야 할 수도 있다.","qa":[{"q":"2학년 과학과제 연구에 대장균에 대한 녹차 추출물의 MIC 실험을 했던데 내용에 대해 말해 보세요.","a":"천연물에서 항생물질 추출 책 읽고~관심 생겨서 마침 일본어 시간에 녹차가 항균효과 있다고 해서 선택함 특히 자료조사로 다른 사람들의 실험을 찾아볼때 아직 하지 않는 재료라 내가 도전정신을 가지고 함/실험 간단히 설명, 추출을 에탄올과 증류수로 낭눠 했고 증류수는 효과 x, 에탄올은 대조군 카나마이신보다 최소 저해농도가 25<100 높아서 효능이 떨어지긴 하지만 관련 사전 조사(120ug/ml)와 비교해서 충분히 항생제로 쓸 가능성이 있다고 결론지음/예상 못한 시행착오들 얘기함 첫번째로 재료 배송오류, 이때문에 실험 일정이 밀려 2회 진행후 평균을 내야하는데 그러지 못해 아쉬움, 대학와서 보완하고 싶다, 두번째로 억제대가 원형이 아님, 이를 대비해 에탄올만 접종한 대조군 만들고 여기서 억제대 형성 안됐기 때문에 내가 에탄올은 충분히 증발시켰고 아마 항온기 내 위치에 따른 온도나 대장균 도말 시 문제로 보인다고 결론 내렸다고 답함, 이렇게 예상 못한 어려움이 많았지만 이를 해결하고 이유를 추론하는 과정이 많은 도움이 되었고 재밌었기 때문에 이런 시행착오들이 오히려 실험을 더 흥미롭게 만들어준 점이라고 생각한다고 답함."},{"q":"화학 II에 반감기 조사하고 발표하면서~~활동에서 열심히 한 점 위주로 얘기해 보세요.","a":"2학년 때 미적분에 대한 책을 찾아 읽었는데 그 책에 혈중 농도 공식이란 게 있었음. 당시는 왜 이런 식을 쓰는지 몰랐는데 0차, 1차 반응에 대해 조사하며 1차 반응의 속도식을 적분하면 해당 식이 나옴을 직접 유도해 봄. 이처럼 수학과 화학의 접목을 통해 몰랐던 점을 알게 됨. 게다가 교과서에 소개된 반응의 반감기가 일정한 이유가 궁금하여 이를 식으로 유도 후 그래프 그리는 프로그램을 이용해 모든 반응이 그런게 아니라 1차만 그러한 성질을 가짐을 이해함. 이처럼 열정적으로 궁금한 점을 직접 찾고 실행에 옮기고 이를 친구들에게 발표했다고 말함."},{"q":"2학년 수업량 유연화 과정에서 항생제를 탐구하고 MIC 실험을 했는데 이때 쓰인 그람 양성균과 음성균의 차이가 뭔가요?","a":"그람 염색시 그람양성균은 두꺼운 세포벽 때문에 탈색이 잘 되지 않아 여전히 자색을 띰,음성균은 세포벽이 비교적 얇아 탈색이 잘 되어 적색을 띰, 이처럼 세포벽의 구조로 구분이 됨."},{"q":"그럼 양성균과 음성균에 따라 항생제에 어떤 반응을 보이는지 말해 보세요.","a":"그람 양성균은 세포벽이 두껍기 때문에 세포벽을 분해하는(펩티도글리칸이라는 용어를 썼는지 가물가물함) 항생제 계열인 페니실린계에 취약함을 보임, 반면 그람 음성균은 얇은 세포벽 위에 외막이 있어 세포를 보호하므로 페니실린계 같은 항생제는 효과가 적고 양성균보다 내성이 발현되기 쉬움, 따라서 다른 방식의 항생제를 선택해서 사용해야 함."},{"q":"3학년 진로활동에 적힌 인공지능이 신약 개발에 어떻게 쓰이나요?","a":"올해 노벨 화학상이 인공지능 개발자일 정도로 이제 생명, 화학 분야에 인공지능이 접목되고 있음, 단백질 접힘 구조 예측 모델 알파폴드를 설명함, 현재 아미노산끼리 상호작용에서 dna같은 다른 분자와의 상호작용까지 다루도록 발전 가능, 그리고 생체 내에서 수용체와 결합시에 미세한 구조 변화까지 설계가 되면 질병의 메커니즘을 연구 가능, 이를 표적하여 치료법을 개발하거나 약의 반응, 부작용을 예측하여 모델링하는 기반이 됨."},{"q":"인공지능 신약개발의 단점은?","a":"아무래도 인공지능이 오류가 0이라 할 수 없고 이것이 사람들에게 악영향을 미칠수도 있음, 또 아직 생체 내 반응이나 상호작용에서 미흡한 점도 많아서 인체 적용에 한계있음, 하지만 인공지능이 시간과 비용을 절약하는 일종의 도구이고 나는 사람이 결정자이기 때문에 인공지능의 장점은 얻고 단점은 버리는 식으로 개발자들이 스스로 선택하고 과정을 통솔해야한다고 생각함, 그리고 최근 몇 년 크게 성장한 것처럼 앞으로 기술의 부족은 점차 보완될 것이라 단점이 아직 많더라도 인공지능의 역할이 매우 중요한 것은 맞음."},{"q":"3학년 진로활동에 적힌 친환경 약물 개발에 어떤 것이 있는지 말해 보세요.","a":"합성 시 주로 사용되는 유기용매를 대체할 수 있는 초임계액과 이온생 액체를 설명함, 회수가 쉬워 재활용이 잘되면서 효율이 좋은게 장점임, 합성뿐만 아니라 약의 포장시 이중포장 생략, 생분해성 재질 사용 등 사소한 부분도 개선해야 한다고 주장함."},{"q":"생명과학 I에 대식세포 M1과 M2를 구분하는 형광물질의 구분 방법과 형광물질의 중요성을 말해 보세요.","a":"M1, M2의 역할 설명 후 주에너지원이 탄수화물, 지방산으로 나뉘므로 이를 이용하여 탄수화물 기반 화합물을 형광물질로 사용해 구분한다고 말함, 형광 물질은 복잡한 방법 없이 현미경으로 쉽게 관찰해서 세포의 활성화와 위치를 알 수 있어 앞서 한 대답처럼 질병 메커니즘을 밝히고 치료법을 연구하는 것을 도와준다고 말함.이 대답을 하던 중간에 노크 소리가 들렸다."},{"q":"서울대 약대에 지원한 동기가 무엇인가요?","a":"1학년 때 서울대 약대를 소개하는 글을 봤음, 다른 약대와 다르게 약학 연구원을 양성하는게 주 목표라는 것이 멋있다고 생각했음, 나는 약학이란 학문에 큰 관심을 갖고 있어서 약사 자격증을 그저 얻는 것이 아니라 약학 연구원이 되는 것이 꿈임, 대학원까지 진학하여 공부를 하고 싶은 열정도 현재 있음, 따라서 서울대 관련 사이트나 정보 등을 찾아보는 등 이 학교에 꾸준히 관심을 가져옴, 특히 ‘천연물을 기반으로 한 항생물질 발견’ 연구에 관심을 가지고 있어 이에 대한 학교의 연구 성과를 찾아보기도 함(이 말을 할 때 미소 교수님이 더 크게 웃음? 웃음을 참는 듯한 표정? 을 지으셨다..) 따라서 미래의 약학 연구원으로 성장하기 위해 이 학교에서 꼭 공부하고 싶다고 대답함.꼬리 질문이 딱히 없어서 이상하다고 생각했는데 다 쓰고 보니 내가 답변이 긴 편이라 그럴수도 있겠다. 과마다 사람마다 다르겠지만 압박 면접이 아닌 편안한 분위기의 면접이었다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"영어교육과","jeonhyeong":"학생부종합(지역균형전형)","method":"2:1로 진행, 면접관 두 명과 학생 한 명이 면접을 진행함.","notes":"8시 15분까지 입실하고 첫 학생 면접이 한 9시 넘어서 시작되었던 것 같음. 기다리는 데 너무 힘들었음. 대기실에 히터가 많이 나오고 폰도 제출하고 아무 말도 못하고 있으니 잠이 몰려왔음.물을 꼭 챙겨 가서 마실 것. 면접 보는 교실도 히터가 많이 나와서 목이 너무 건조했음. 말 하는데 목이 아플 정도로 건조함!! 물을 꼭 가져갈 것!!","qa":[{"q":"교사 이슈 관련해서, 교사에 관한 인식이 예전과 많이 바뀌었나?","a":"서이초 교사 자살 사건이나, 교권침해 사례 등이 꾸준히 늘어나는 것을 보니 예전 만큼 교사에 대한 인식이 많이 안 좋아진 것 같습니다."},{"q":"역사랑 일반사회를 잘했다고 생기부에 나와있는데, 왜 과목을 바꾸게 되었나요?","a":"중학교 때까지 역사랑 일반사회가 마냥 좋아서 멘토링 활동도 하다 보니 막연히 고등학교 1학년 때까지 역사랑 일반사회 교사를 꿈꿔왔던 것 같습니다. 하지만 고등학교 2학년 때 영어 시간에 멘토-멘티 수행평가에서 멘토로서, 반 친구들과 멘티에게 영어 지문을 어떻게 하면 재밌고 쉽게 알려줄지에 대해 고민하는 과정에서 영어에 대한 즐거움, 지식을 전달하는 데에 대한 즐거움을 느꼈습니다."},{"q":"그럼 결론적으로 교사나 영어교사를 꿈꾸게 된 이유는?","a":"앞서 말했던 수행평가에서 영어에 대한 확신과 2학년 때부터 반장을 해오면서 학급 운영 및 친구들을 챙겨주고, 대가 없이 오는 뿌듯함 등이 저를 교사라는 길로 이끌었던 것 같습니다."},{"q":"영어 동아리를 운영하셨네요? 혹시 영어 동아리 운영하시면서 힘드셨던 점은 없나요?","a":"수능 공부, 내신 공부에 지쳐있는 친구들이 영어 동아리에서까지 영어를 해야 하냐며 그냥 자습을 주면 안되냐는 등 의욕이 없고 많이 힘들어하였습니다. 저는 친구들의 이 지친 마음을 풀어주면서도 영어까지 할 수 있는 활동을 찾다가 영어 필사 활동과 영어 토론 활동을 기획하게 되었습니다."},{"q":"동아리원들이 활동을 잘 수행해냈나요?","a":"네. 영어 필사도 꾸준히 하고 영어 토론 활동에서도 약식 토론이었긴 하지만 적극적으로 참여해주었습니다."},{"q":"‘영어를 잘하면 우리는 행복해질까’ 라는 이 책을 읽고 느낀점으로 우리나라 영어교육이 우리 사회에 끼친 부정적인 영향이 있다고 생기부에 쓰여있습니다. 어떤 부정적인 영향이 있나요?","a":"지나친 영어 사교육, 쓰기와 읽기 중심, 독해 기술에만 집중하고 실생활에서 쓰이는 듣기와 말하기는 교육하지 않는다는 내용으로 말을 했던 것 같음."},{"q":"그러면 듣기와 말하기 교육을 활성화하기 위해서 학생이 생각한 방안이 있나요?","a":"원어민 강사와 말하기 수업이나 줌이나 구글 클래스룸? 같은 플랫폼을 활용하여 외국에 있는 선생님과 수업을 진행하면 좋을 것 같습니다.(1분 남았다고 밖에서 노크를 함.)"},{"q":"앞서 말했던 책 이름이 ‘영어를 잘하면 우리는 행복해질까’였습니다. 정말로 영어를 잘하면 우리는 행복해질까요?","a":"행복해질 것 같습니다! 영어를 잘해서 의사소통 능력이 향상되면 다양한 외국인 친구들을 만나 많은 경험을 쌓을 수 있을 수 있고 또 타지에 나가더라도 적응이 빨라 살아가는 데 많은 도움이 되니 행복해질 것 같습니다."},{"q":"영어는 우리나라 모국어가 아닌데도 행복해질까요?","a":"모국어가 아니어도 영어를 활용해 실험을 하고 논문을 작성하고 좋은 성과를 이루어내 우리나라를 널리 알릴 수 있고 뽐낼 수 있으니 행복해질 거라고 생각합니다!"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"2대 1 면접, 10분 동안, 학생부 기반 면접","notes":"인 가능. 8시에 번호표 받고 한 시간 정도는 아무것도 없이 기다려야만 함, (가져온 프린트 전부 넣고 수험표만 올려놓으라고 함) 첫 번쨰 조 8시 50분 출발. 한 조에 각 과당 두 명씩 이동. (두 번째 조는 9시 10분 출발. 한 명당 10분씩) 면접관들과 자리 엄청 가까움. (약 40~60CM?) 대화하는 듯 한 분위기. 편하게 하면 될 것 같다. 평소에 본인 활동에 대해서 여러 측면에서 깊이 생각해 보는 것이 도움이 될 듯. 끝나기 1분 전에 밖에서 노크해 준다고는 하는데 안 들린다.","qa":[{"q":"(2학년 지구과학 수행평가) 지구온난화 관련한 질문. (정확히 기억 안 난다. 어려운 질문 아니라 간단히 생각 확인하는 질문)","a":"적당히 잘 대답했다. 뭐라고 했었는지 기억이 안 난다."},{"q":"(2학년 지구과학 수행평가) 지구온난화로 인한 해수면 상승의 심각성을 어떻게 드러냈는가?","a":"IPCC 기후변화연구보고서 같은 자료들을 참고하여 수치적으로 드러냈던 것 같다."},{"q":"(2학년 지구과학 수행평가) 그러한 수치적 상승이(해수면의) 지구온난화 때문이 아니라 지속적으로 주기적으로 일어나왔던 지구의 변화? 작용 아닌가?","a":"이 수치가 주기적인 것 이상으로 이례적으로 크기 때문에 지구온난화 때문이라고 생각한다. 대답이 애매했는지 표정이 이상하셨다."},{"q":"(3학년 동아리 시간) 사용후 핵연료 심층처분장 관련한 활동 어떻게 했는지 설명해달라는 내용의 질문","a":"아는 대로 대답하였음. 동기-과정-결과-의미 순으로 설명하되 의미에 스스로가 에너지 기술 관련 정책 전문가를 꿈꾸는데 이러이러한 활동이 이러이러한 점에서 이런 꿈을 이루는 데 어떠한 기본 소양을 길러준 것 같다는 식으로 답했음."},{"q":"(3학년 동아리 시간) 심층처분장 부지 선정하려면 무엇무엇을 고려해야 하는가?","a":"아는대로 말씀 드렸는데, ‘이 활동을 하기 전에도 이러이러한 점은 고려해야 할 것 같았는데 활동을 하면서 흥미로웠던 점은 이러이러한 점(지질학적 요건 등)도 고려해야 한다는 것이었다.’ 이런 형식으로 답변했었음."},{"q":"에너지 정책에 관심 있냐는 질문","a":"그렇다고 하고, 구체적으로 한국에너지기술연구원 연구전략본부에서 연구원으로 일하고 싶다고 함."},{"q":"그럼 무슨 과목 들어야 할 것 같은가?+정책전문가로서 어떤 가치관을 중요시 여기는지?","a":"개인적으로는 국제에너지시장분석이나 에너지환경기술경영 등 과목 수강하고 싶다."},{"q":"(3학년 물리 시간을 예로 드시면서) 어려웠던 활동 소개해 달라.","a":"3학년 동아리 시간의 파이로프로세싱 관련 활동이라고 소개하다가 끝남.끝나고 보니 잘했다는 느낌은 아니었다. 대기할 때 앞번호 아이 면접하는 것이 약간 들렸는데 분위기가 좀 달랐다.대기실에서 다른 과 지원자들과 함께 대기. 입실 시간(7시~8시) 동안은 자유롭게 휴대폰 확인, 가져온 프린트 확"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"영어영문학과","jeonhyeong":"학생부종합(일반전형)","method":"제시문 면접(인문학+사회과학)인문학제시문 (가)(나)(다) - 문제는 홈페이지에서 확인할 수 있습니다.","notes":"합니다. 본인의 답이 꼭 정답이 아니더라도 납득할만한 근거가 있고, 그걸로 교수님을 설득한다면 되는 것입니다! 그렇기 때문에 배경지식을 뽐내며 번지르르한 답변을 만드는 것보다, 제시문에 충실하여 논리적이고 명료한 답변을 만드는 것이 더 중요하니, 기출 분석할 때 다각도로 접근해보며 가장 논리적인 구조를 만드는 연습을 해보세요.모의면접 꼭~~~~~~~해보세요. 저는 면접 전날에 서울에 올라가서 모의면접을 2번 봤었는데, 그 경험이 상당히 도움이 되었습니다. (실제 면접보다 모의면접이 더 떨리기도...) 학교에서든, 학원에서든, 어디서든 상관없지만 단! 실전과 유사하게 긴장된 환경을 만들고, 그 속에서 면접 연습을 꼭 해봐야합니다. 면접날 답변 구상실이 너무 추워서 긴장이 더 되었었는데, 모의면접 했던 거 생각하면서 금방 안정을 되찾았습니다. 연습을 많이 하면 할수록 긴장 상태에서 안정 상태로 가는 속도가 더 빨라질겁니다. 자신에 대한 믿음과 자신감또한 올라갈거구요! 기출 분석, 답변 구성 연습하셨다면 모의면접도 반드시 여러 번 긴장된 상태에서 해보시길 바랍니다.면접, 생각보다 별거 아닙니다!!! 들어가 인사할 때도 웃으면서, 나올 때도 웃으면서! 반드시 방긋 웃으면서 자신감있게, 밝게 이야기하시구, 최대한 편안하게 하려고 노력하세요!!!! *^^* 위에 적은 tip들 참고하셔서 연습하시면 더 도움이 될 겁니다. 끝까지 포기하지 마시고, 최선을 다한다면 원하는 결과 얻을 수 있을 겁니다. 파이팅!!!!!","qa":[{"q":"1. 번역에 대한 세가지 관점 비교, 셋 중 타당한 관점을 본인의 독서경험을 들어 설명","a":"공통점: 번역가의 번역에 따라 독자의 수용양상 달라짐.차이점: 번역에서 주력해야할 부분(가) 원작의 느낌이 나도록 자연스럽게 수정, 독자가 이해하기 쉽도록(나) 번역문이 어색하더라도 원작의 형태 그대로(다) 원어, 번역어 모두 확장할 필요(다)가 타당하다고 생각함. ‘깐부’를 다른 영어단어가 아닌 ‘gganbu’로 번역한 것을 영어를 확장한 예시로, ‘the great gatsby’를 ‘최고의’, ‘멋진’이 아닌 ‘위대한 개츠비’로 번역한 것을 번역의 과정에서 새로운 의미를 발견한 예시로 설명함.tip) 문제에서 요구하는 종류의 예시가 아니더라도, 자기가 생각했을 때 적합한 예시라고 생각되면 미리 말씀드리고(깐부라는 단어는 책에서 근거한 것은 아니지만~) 당당하게 이야기할 것!tip) 비교 문제에서는 꼭 공통점과 차이점 모두 말할 것! 공통점 빼먹기 쉬우니까 의식적으로라 기억했다가 말하려고 노력하기.1번 문제 추가질문"},{"q":"깐부를 예로 들어 설명한 것이 왜 (다)와 연결되는지","a":"여기에 모두 적지는 못하겠지만... 깐부와 위대한 개츠비를 예시로 든 저만의 논리적 이유가 있었기 때문에 그것을 정리해서 답변을 했고, 교수님도 이해하셨다는 듯이 끄덕끄덕하고 넘어감."},{"q":"역사해석과 번역 과정을 빗대어 (가)(나)(다) 설명 + 사례","a":"주어진 글(역사해석과 번역과정을 빗대는 글) 요약(가) 역사 해석 시 주관적인 해석 가미하여 이해하기 쉽게 이야기를 만들것임.(나) 역사적 사실 그 자체를 강조할 것임.(다) 사실성과 허구성 적절히 조합사례: 유대인 학살에 가담한 독일 경찰대(가) 사회적 맥락, 순응주의 등을 이유로 들어 그들이 왜 유대인 학살에 가담했을지 설명(나) 유대인을 학살했다는 사실 자체에 집중(다) 사실 자체 + 왜 그랬을지 이유 제시tip) 위의 사례는 서울대 기출 중에 있었던 내용! 역대 서울대 기출을 풀면서 제시문 면접의 방법을 익히는 것은 물론이고, 핵심내용을 기억해두면 이렇게 사례를 요구하는 문제에서 다른 배경지식 끌어올 필요없이 용이하게 써먹을 수 있음.2번문제 추가질문"},{"q":"(이 부분을 잘 못 들으셨는지) (가)의 입장에서 역사해석 어떻게 했을지 다시 물어봄.","a":"다시 더 구체적으로, 이해하기 쉽게 설명함.사회과학제시문 (가)(나)(다) - 문제는 홈페이지에서 확인할 수 있습니다."},{"q":"자기실현적 예언의 관점에서 (나), (다) 비교","a":"자기실현적 예언 (가) 설명(나)(다) 공통점: 신뢰를 기반으로 함.차이점: (나)는 예측과 결과를 두고 보았을 때 비과학적, 비논리적 과정을 거침.(주술의 비과학성) 반면 (다)는 예측과 결과를 보았을 때 물가상승이라는 결과에 영향을 주는 행동들이 논리적으로 이어지므로 과학적임. (나)와 (다) 모두 예측과 결과 간의 상관성은 있지만, (나)는 논리적 인과성이 없고 (다)는 인과성이 있다. (이 부분은 저도 이야기하면서 이게 맞나 의심이 들었지만... 교수님들도 이해가 안된다는 표정을 지으셨지만... 안 그런 척 당당하게 이야기했습니다.)1번 문제 추가질문"},{"q":"상관성이 있다는게 무슨 뜻인가요?","a":"예측이 결과로 이어지는 것이 과학적이든 비과학적이든 연관이 있는 것으로 나타나기 때문에 ~(나)가 인과성이 없다고 했는데.. 인과성이 있는 거 아닌가?(나)도 물론 예측이 결과로 이어지는 과정을 보면 인과성이 있는 것 같지만 (다)에 비해서 과학적으로 설명되는 과정이 아니기 때문에 ~ 이 부분 열심히 설명했는데 한 분은 이해된다는 표정, 한 분은 이해 못하신 표정으로 다음으로 넘어감.(나)에서는 주로 믿음이라는 표현을 사용하는데 신뢰라는 말을 사용하시네요. 믿음과 신뢰는 차이가 있다고 생각하나요?이 때 조금 당황했지만... 차분하게 생각해보고, 믿음과 신뢰의 언어적 차이는 확신할 수 없지만, 제시문 (나)에서 신뢰라는 단어를 ~라는 맥락에서 사용하는 것으로 볼 때, 믿음과 유사한 의미에서 사용될 수 있다고 생각한다고 답변함."},{"q":"밑줄친 문제 해결 노력을 교육자, 언론인, 정책 입안자, 연구자 중 두 가지(세가지?) 이상의 관점에서 설명","a":"밑줄친 문제: 근거없이 예측을 확정짓고 낙인을 찍어 그것이 결과로 이어지는 현상교육자 – 교육 시 편견 없이 아이들 교육. 교육자의 특성상 성장기인 아이들과 접촉하므로아이들의 미래에 미치는 영향이 지대함을 강조함.언론인 – 기사 작성 시 사실검토과정을 거칠 것, 그 과정에서 자신의 주관을 개입하지 말 것을 강조함. 언론의 특성(정보 확산이 빠름)을 강조함.정책 입안자 – 가장 포괄적인 노력을 해야함. 문제를 예방하기 위한 사전적 노력과 문제 발생 후 사후적 노력으로 나누어 설명. > 교육자와 언론인 선발 시 교육과정을 거칠 것, 부당하게 차별당하는 사람이 그것이 부당하다고 인식할 수 있도록 할 것, 피해 발생 시 구제책 마련할 것 등 설명.tip) 해결책을 설명할 때 사전적 문제 예방책과, 사후적 구제 방법 등으로 나누어 설명하면 그냥 나열만 하는 것보다 훨씬 논리적인 구조가 될 수 있음.2번 문제 추가질문"},{"q":"잘 못 들어서 정책 입안자가 해야할 노력 부분 다시 말해주세요.(이 때 시간 얼마 안 남아서 조금 빠르게 말했더니 재질문하심.)","a":"다시 설명~선발 시 교육을 거쳐야한다고 했는데 선발과정에 교육을 넣어야한다는 의미인가요 아님 선발하고 교육을 해야한다는 의미안가요 아님 둘다인가요?(잠시 생각하다가) 선발과 교육의 순서가 중요한 것이 아니라, 교육자와 언론인이 교육의 과정을 거치는게 중요하다는 점에서 그렇게 답변한 것이라고 이야기함.제시문 추가질문 tip) 어떤 당황스러운 질문이 나와도, 말리지 말 것! 제시문의 내용, 자신이 답변할 때 어떤 의도로 그렇게 답변한 것인지를 중심으로 이야기하면 되니까! 차분하게 자신의 생각을 말하면 됩니다.시간 거의 다 되었을 때 마지막 추가질문고등학교 재학 시절 가장 인상깊게 읽은 책은?미리 준비한 답변 이야기함.서울대는 과별로 면접을 진행하기 때문에 대기 시간에 가져온 자료를 볼 수 있는지, 물을 나누어주는지, 시계가 있는지 등등의 세부사항이 상이합니다. 영어영문학과의 경우 대기실에 물과 간식이 있었고, 시계도 있었지만 모든 짐을 다 내야했습니다. 저는 18명 중 18번이 걸려서 아침 7시반까지 입실해서 오후 1시가 될 때까지 그저 멍~하니 대기해야했습니다. 내년에는 대기시간에 가져온 자료를 볼 수 있을지 모르니 챙겨가도록 하되, 올해처럼 금지당할 수도 있으니... 지루한 대기시간에 잠을 자거나 가져온 간식을 먹으며 버틸 수 있도록 해야합니다. 저는 자려고 노력했는데 대기시간이 너무 길어서 명상을 했습니다.ㅎ... 아 그리고 조금 추웠습니다!!! 핫팩 많이 챙겨가세요.서울대는 배경지식의 풍부함이 중요한 것이 아닙니다. 물론 어느정도 있으면 좋겠지만, 가장 중요한 것은 논리적으로 답변을 구성하는 연습입니다. 즉 답과 (제시문에서 찾은)근거를 연결지어 논리성을 만드는 연습이 가장 중요"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"서류 기반, 면접관 2명, 2단계 30%, 10분","notes":"생각보다 준비한 대로 안 나왔음. 인성 관련된 내용을 주로 대비했는데 전공적합성을 주로 물어봄. 첫 질문을 매끄럽게 답하지 못해 면접관이 전공의 기초와 심화 사이의 어중간한 내용을 질문했음. 첫 질문을 매끄럽게 답하는 것이 중요하다 생각됨.","qa":[{"q":"지원동기가 어떻게 되나요?","a":"2학년 동아리 시간에 이중슬릿 실험으로 실험 설계에서 주변 환경과 변인 통제의 중요성을 배웠고, 3학년 자율 주제 탐구 활동에서 핵융합에서의 전기에너지 생산을 탐구하며 블랭킷의 역할과 중요성을 알게 됨. 서울대는 우리나라에 단 하나뿐인 구형 토카막 장치 VEST를 소유하고 있기에 직접적인 실험, 연구가 가능함. 서울대에 진학하여 핵융합 분야의 전문가로 성장하고자 함."},{"q":"블랭킷에 대해 탐구했다고 했는데 역할과 중요성을 말해 보세요.","a":"블랭킷의 역할에는 3가지가 있는데, 첫째는 핵융합 원료인 삼중수소 생산임. 블랭킷 내부에서 리튬과 중성자를 반응시켜 삼중수소를 생산함. 둘째, 차폐제의 역할을 함. 핵융합 과정에서 나오는 미량의 방사능을 차폐해줌. 셋째, 중성자의 운동에너지를 열에너지로 변환해 줌. 중성자의 운동에너지를 열에너지로 바꾸어 외부 열기관을 통해 전기에너지를 생산하는 것으로 알고 있음. 탐구하며 사소하다고 생각한 부품이 상당히 중요하다는 것을 알게 됨."},{"q":"2학년 독서 시간에 중국의 EAST와 한국의 KSTAR를 비교하는 신문을 작성했다 했는데 관련 내용을 말해 보세요.","a":"EAST와 KSTAR는 주력 연구 분야가 다름. 중국은 전자 플라즈마의 유지에 주력하고 있고 우리나라는 이온 플라즈마 유지를 주력으로 연구하고 있음. 이처럼 각국의 다양한 분야의 연구 결과를 공유하고 함께 연구하여 ITER 프로젝트를 완수하는 것이 중요하다 생각함."},{"q":"융합과학 시간에 무엇을 배웠나요","a":"1학기에 걸쳐 2가지 주제로 탐구활동을 진행함. 토카막에서의 전자기장의 역할과 JET의 해체와 의의에 대해 탐구함. 토카막에서 용기 내부를 손상시키지 않고 플라즈마를 진공용기 내부에 띄어서 운전하기 위해 초전도 자석으로 자기장을 형성함. JET 해체의 힘든 점은 핵융합 실험 과정 중 발생한 방사능을 세척하는데 오래 걸린다는 것이고 JET 해체의 의의는 이후의 ITER프로젝트에 JET부품을 재활용 가능하다는 것임."},{"q":"가장 좋아하는 과학 과목은?","a":"물리학1 과목이 논리적으로 이해 가능해서 좋았음. 토카막 내에서 플라즈마의 운동을 이해하는 것이 힘들었는데, 물리 시간에 자기장 내에서 하전 입자의 운동을 배우며 더욱 깊게 이해할 수 있었음."},{"q":"핵융합 원료가 무엇이며 생산 방법을 말해보세요.","a":"중수소와 삼중수소, 이외에도 붕소 등 다양한 원소를 쓰는 것으로 알고 있음. 중수소는 해수에서 추출 가능하고, 삼중수소는 주로 리튬과 중성자의 반응으로 얻을 수 있는데, 이 리튬을 광산이나 해수에서 추출할 수 있음. 또한 최근에 이산화탄소 플라즈마를 이용해 해수에서 리튬 추출률을 약 3배 정도 향상시켰다는 연구 결과도 있음."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(기회균형특별전형-사회통합)","method":"생기부 기반 면접 10분","notes":"면서 봐주셨던 분이었습니다. 웃으면서 너무 어려운 질문 던지셔서 좀 힘들었어요.질문이 정말 예상치 못하게 나왔어요. 저는 칸트를 좋아해서 말한 게 맞지만 생기부에 칸트 내용이 하나도 없는데 계속해서 질문하시는 걸 보니 어쭙잖게 좋아하는 척을 하면 안 될 것 같다고 느꼈습니다. 생기부에 있는 활동을 다 설명할 수 있는 건 당연하고, 생기부 외에 지원동기에서 말할 내용도 잘 준비하셔야 될 것 같아요.입실시간 지나면 수험표, 신분증, 물 빼고 전부 다 가방에 넣어서 복도에 줄지어 놔뒀어요. 그리고 면접 보는 방은 대기실 바로 앞에 있어서 부르면 나와서 면접 보고 바로 짐 챙겨서 나갔어요.","qa":[{"q":"반갑습니다. 자율이나 동아리 활동 중에서 기억에 남는 게 있으면 말해줄래요?","a":"2학년 동아리 활동에서 이주민에 관한 책을 읽고 난민 출신 강사분을 초청해서 북토크 한 내용 설명."},{"q":"학생은 난민 수용에 찬성하는 입장인 거네요? 그러면 난민 수용에 반대하는 사람들은 어떻게 설득할 수 있을까요?","a":"인도주의적 측면을 강조할 수도 있지만 난민이 한국에 정착함으로써 경제적인 측면에 기여할 수 있음 설명."},{"q":"학생이 이렇게 사회 문제에 관심 많은 거 알겠습니다. 여기 왜 지원했나요?","a":"사회 문제에 관심을 가지면서 살아오다가 윤리 과목을 접하고 철학이 단순한 사색이 아니라 보편적 가치와 존엄성 실현에 큰 역할을 할 수 있음을 알게 되면서, 더 공부하고 알아가면서 사회에 기여하고 싶다는 내용."},{"q":"그럼 어떤 사상이나 철학자를 보고 그런 생각을 했나요?","a":"칸트의 인간성 정식 내용 설명."},{"q":"인간성 정식이 사회 문제 해결에 기여할 수 있다는 건가요? 인간성 정식에서 인격을 수단만으로 대하는 것과, 동시에 목적으로 대한다는 것의 의미를 사회 제도와 연관지어서 설명할 수 있나요?","a":"수단만으로 대하는 제도와 목적으로 대하는 제도를 각각 사례를 들어가면서 설명함."},{"q":"그러면 칸트 말고 다른 사상이나 철학자를 법이나 사회 제도를 만드는 것과 연결지어서 설명해 보세요.","a":"공리주의와 입법 연관지어서 설명."},{"q":"(8분 정도 지난 시점. 옆에서 듣고만 계시던 교수님께서 질문하심) 책임윤리 뜻이 뭐예요?","a":"(아는 게 요나스밖에 없어서 요나스를 설명하려고 함)"},{"q":"아니아니 요나스 말고, 학생이 생각하는 책임윤리가 뭐죠?","a":"(당황하고 횡설수설 답해서 기억이 안 남)"},{"q":"그렇군요. 요나스와 칸트를 비교해 볼 수 있겠나요?","a":"못하겠다고 했음."},{"q":"그럼 학생이 생각하는 책임윤리의 정의가 그런 거라면, 그것의 대(對)가 되는 사상이나 철학자가 있으면 말해 줄 수 있어요? 이건 고등학생 수준에서는 좀 어렵죠?","a":"이것도 답변 못 함."},{"q":"(1분 남았다는 노크 소리 들림) 이쯤 하고 마지막으로 학생이 하고 싶은 얘기 있으면 하고 면접 마치도록 할게요.","a":"준비했던 말 하고 나옴.면접관들이 굉장히 편안한 분위기로 진행하셨어요. 표정을 일부러 굳히지도 않으시고, 쭉 무표정이었던 분과 웃으"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"학생부종합(지역균형전형)","method":"전체 지원자를 여러 개의 조로 나눠 진행 , 8시30분까지 입실, 입실 후엔 준비한 대본 못 봄면접은 10분씩 진행","notes":"‘내가 진로가 이것이니까 이것을 중심으로 질문을 계획하면 되겠지?’ 라는 안일한 생각으로 면접에 임하면 안됩니다. 내가 제일 준비 안한 것이 질문으로 깊게 파고들 수 있는 것이 면접입니다. 자신의 생기부에 있는 내용들을 모두 꼼꼼히 분석하고 준비하세요. 논리적 허점이 보이면 바로 지적하고 비판하는 것이 서울대학교 면접인 것 같습니다.","qa":[{"q":"프로이트와 아들러의 교육 심리에 대해 조사했었는데, 이들의 주장에 대해 말해보세요","a":"네, 프로이트는 무의식에 잠재되어 있는 욕구를 해소하기 위해 교육심리치료가 필요하다고 주장했습니다. 성장기 아이들은 자라면서 집중되는 욕구가 신체 부위를 이동하면서 달라지는데, 입이나 항문 등의 신체 부위에 집중되는 욕구를 적절히 해소해 주어 트라우마가 발생하지 않도록 도와주는 것이 중요합니다. 아들러는 무의식에 있는 잠재 의식을 끌어 올리는 프로이트의 주장과는 달리 타인에 대한 열등감으로 인해 발생하는 좋지 않은 감정을 잘 해소해 주는 것이 중요하다고 주장합니다. 타인과의 상호작용을 통해 적절하게 협력하고 경쟁하는 관계에서 열등감을 잘 해소하는 심리치료가 중요하다고 강조합니다."},{"q":"그렇다면 본인이 생각하는 교육심리치료란 무엇이 있다고 생각하시나요?","a":"(답변을 제대로 준비하지 못하여 또래와 함께 경쟁하고 소통하는 심리치료를 제시하였으나, 방안이 모호하여 추가 꼬리 질문을 계속해서 받았고, 실현 가능성이 있는지, 또래와 경쟁하는 것이 오히려 열등감을 유발시키는 것은 아닌지와 같은 논리적인 허점들을 지적당함)"},{"q":"사회 문화 시간에 공교육과 사교육이 격차를 줄이기 위해 공교육의 질을 높이는 것이 중요하다고 주장했는데, 공교육의 질을 높이기 위한 방안은 무엇이 있다고 생각하시나요?","a":"제가 제시하였던 공교육의 질을 높이기 위한 방안은 교육방송에 금전적인 지원을 통해 유능한 강사들이 모두가 들을 수 있는 교육방송에 많이 참여하여 교육의 질을 높일 수 있도록 노력하는 것이 중요하다고 생각합니다. 또한 디지털 교육 기술을 많이 보급하여 교과서를 편리하게 들고 다닐 수 있도록 하거나 여러 시청각적 이미지를 통해 수업의 이해를 돕는 것을 통한 교육이 공교육의 질을 높일 수 있는 방안이라고 생각합니다."},{"q":"과연 공교육에 지원을 많이 한다고 해서 유명하고 능력 있는 강사들이 사교육을 버리고 올 수 있을까요?","a":"(공교육의 질을 높이기 위한 방안 자체에 대한 답안을 준비하는 것이 마땅한 해결책이 생각나지 않아 허점을 지적당함, 이 질문에 대해 명쾌한 답을 내리지 못하고 우물쭈물한 기억이 남)"},{"q":"그렇다면 사교육 격차를 완화하기 위한 방안은 무엇이 있다고 생각하시나요?","a":"제가 공교육의 질을 높이기 위한 방안만 생각해서, 지금 현재 심화되어 있는 사교육 격차를 완화하기 위한 방안은 직접적으로 생각해 보진 못했습니다."},{"q":"밴드부장으로서 성취감 있었던 경험이 있었나요?","a":"밴드부장으로서 성취감 있었던 경험은 축제 무대에서 좋은 공연을 선보이기 위해 밴드부원들과 함께 악곡을 연습하여 음정과 박자를 개선하고 화합하고 조화로운 연주를 할 수 있게 노력하였고, 그 결과 축제 전 팀 2등이라는 성과를 보일 수 있어서 성취감이 있었던 것 같습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접","notes":"","qa":[{"q":"초전도체에 관심이 많은거 같은데 어쩌다가 관심이 생기게 됐나요","a":"제 상식과 다른 현상이였기 때문입니다. 저는 이전에 입자는 온도가 낮을수록 운동을 적게하게 되어 전류가 흐르지 않을 것이라고 생각했는데 초전도체는 일정 온도 이하의 낮은 온도에서 전류가 더 잘 흐른다는 점 때문에 관심이 생기게 되었습니다."},{"q":"그러면 초전도체와 고체는 어떻게 전류가 흐르는 방식이 다른가요","a":"초전도체는 쿠퍼 전자쌍에 의해 전류가 흐르지만 고체는 자유전자의 운동에 의해서 전류가 흐른다고 알고 있습니다."},{"q":"SRAM과 DRAM의 차이를 설명할 수 있나요","a":"두 메모리는 정보를 읽고 저장할 수 있는 장치로 sram은 dram보다 더 속도가 빠르다고 알고 있습니다."},{"q":"베르누이 법칙과 운동량을 관련지어서 조사했다는데 어떤 내용을 조사한건가요","a":"베르누이 법칙이란 유체의 속도와 압력에 관한 내용입니다. 저는 운동량 또한 속도에 관련되어 있다는 점에 주목하여 유체의 질량, 속도, 압력에 대한 연관성을 조사했습니다."},{"q":"고등학교에서 공부를 하면서 어떤 과목이 더 관심이 있었나요","a":"저는 물리학인 것 같습니다. 물리학은 모든 과학의 기반이 되는 과목이라고 생각하기 때문입니다. 물리학을 공부하면 화학, 생명과학, 지구과학을 더 이해하기 쉬워지고 물리학이 모두 관련되어 있다고 느꼈습니다. 이러한 점 때문에 물리학에 더 관심이 있었던 것 같습니다."},{"q":"이 과에 지원한 동기가 뭔가요","a":"저는 소재를 연구할 수 있는 연구원이 되고 싶기 때문입니다. 이전에 화학을 공부하면서 원자의 구조와 배열에 따라 소재의 성질이 달라진다는 것을 알게 되었고, 이러한 점이 흥미로워 재료를 연구할 수 있는 재료공학과에 지원하게 되었습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"교수님 두 분과 일대일 면접, 면접 시간 10분","notes":"교수님과의 거리가 1~2미터 정도로 가깝습니다. 모의 면접 시 가까운 거리에서 연습하세요.전혀 긴장되는 분위기도, 압박하는 분위기도 아닙니다.대기 중에 어떤 자료도 볼 수 없습니다. 마음 편하게 대기하세요.","qa":[{"q":"재료공학부 지원 동기와 대학 오면 하고 싶은 거 이야기해 주세요.","a":"재료공학은 더 나은 재료의 개발을 통해 여러 환경문제와 사회문제에 솔루션을 제공하는 학문 분야로 알고 있습니다. 재료 개발을 통해 여러 환경문제와 그로 인해 나타나는 사회문제를 해결하여 노인, 장애인 등의 소수를 포함한 모든 사람이 건강하고 행복한 삶을 영위하는 데 기여하고 싶기 때문에 재료공학부에 지원하였습니다. 대학에 가면 제일 먼저 타 학과 학생들과 함께 연구하거나 프로젝트를 진행해 보고 싶습니다."},{"q":"그럼 친구들이랑 연구하고 싶은 관심 분야가 있나요?","a":"청정 에너지에 관심을 가지고 있습니다. 핵융합 발전이라든지, 태양광 발전 등에 재료공학이 기본이 되지만 재료공학만으로 가능한 게 아니기 때문에 타 학과와 협업을 말씀드렸습니다."},{"q":"타이탄호와 관련해서 여러 가지 계산을 하셨던데 간단히 설명해주세요","a":"해당 활동을 할 당시 물리학1에서 압력, 부피, 온도 관계에 대해서 배우고 있었습니다. 마침 타이탄호라는 잠수정이 내파를 당했다는 기사를 봤고 기사를 읽다 보니 수업 시간에 배운 내용으로 사고 당시 잠수정이 받은 압력이나 힘 등을 계산할 수 있겠다 생각했고 활동을 진행했습니다. 사고 당시 수심을 해저 3800미터로 예상하고 있고 수심이 10미터 낮아질 때마다 1기압씩 증가하므로 381기압 정도의 압력이 가해졌을 것이라고 정리했습니다. 이를 pa 단위로 바꾸면 4000만 정도가 됩니다. 타이탄호의 길이, 높이, 생김새를 바탕으로 겉넓이를 계산하니 15.75제곱미터가 나왔고 압력과 곱하니 사고 당시 6억 뉴턴 정도의 힘을 받았을 것이며 이는 항공모함 100대 그리고 반 친구 900만 명이 누르는 힘이라고 설명했습니다.(되게 재밌는 활동이었겠어요, 어떻게 숫자를 다 기억하고 계시네요?)"},{"q":"계산 과정을 지금 다시 분석했을 때 문제가 있다면?","a":"힘은 벡터값이기 때문에 상쇄가 되거나 할 것 같은데 그냥 공식에 대입해서 힘을 구하는 게 옳은지 묻고 싶습니다."},{"q":"그렇네요, 힘이 상쇄되었다면 잠수정이 왜 찌그러졌을까요?","a":"힘과 압력의 명확한 차이를 잘 모르고 있는 것 같습니다."},{"q":"미네랄과 정수과정에 관한 실험을 하셨네요, 설명해주세요.","a":"이 실험을 하기 전에 해수담수화 기술에 대해 조사한 적 있습니다. 해수담수화와 정수 모두 과정이 복잡하고 비용이 많이 든다는 문제가 있었고, 불필요한 물질만 흡착하는 소재를 개발할 수 있다면 과정을 단순화하고 비용을 절감할 수 있다고 생각했습니다. 간이 정수 키트 세 칸을 쌓아올리고 필터로 사용하는 재료를 모래, 활성탄, 마그네슘 조각으로 바꿔가며 소금물을 여과시켜 여과를 더 잘 시키는 소재를 찾고 싶었습니다. 10% 농도의 소금물을 부어 실험을 해보니 모두 9%정도로 나타났지만 동일한 재료로 다시 실험을 진행해도 값이 계속 달라졌기 때문에 유의미한 실험값은 아니라고 생각합니다.(아주 흥미롭네요.)"},{"q":"왜 실험 과정에 오차가 발생했을까요?","a":"가정용 염도계를 사용해 염도를 측정했습니다. 염도계는 소금물 속 Cl 음이온을 검출하는 전기전도 방식을 사용하기 때문에 마그네슘 조각과 반응해 MgCl2를 만들어 염도가 낮게 측정될 거라 기대했지만 충분히 반응할 만큼의 시간이 없었다고 생각합니다. 대학 진학 후에 원하는 결론을 얻기 위해 실험을 설계하는 법을 배우고 전문적인 장비를 가지고 실험을 다시 진행해 보고 싶습니다.(재밌는 실험이네요.)"},{"q":"화학 실험 동아리 와화학에서 이것저것 실험을 많이 했는데, 그래서 형광과 인광이 뭔지 설명해 줘봐요.","a":"제가 되게 재밌게 했던 활동이라 기억에 남습니다. 형광은 전자가 단일항의 들뜬상태에서 단일항의 바닥상태로 전이할 때 발생하는 빛이고, 인광은 전자가 삼중항의 들뜬상태에서 단일항의 바닥상태로 전이할 때 발생하는 빛입니다."},{"q":"그래서 두 개의 차이가 뭐죠?","a":"형광은 전자가 플립없이 떨어지기 때문에 인광에 비해 더 잦은 빈도로 일어나고 따라서 허용된 전이라고 한다고 알고 있습니다. 인광은 삼중항의 전자가 바로 떨어질 수 없어서 스핀 방향을 바꾸며 떨어져야 하기 때문에 드물게 일어나고 따라서 금지된 전이라고 합니다. (금지된 전이라는 용어까지 아시네요ㅎㅎ)"},{"q":"너무 물리만 물어봤네요 화학에서는.... 생분해 플라스틱, pla에 대해 조사했네요. 설명해 볼래요?","a":"pla는 락트산, 그러니까 젖산이 에스터 결합을 해서 여러 개가 연결돼 있는 사슬 형태의 물질입니다. 기존의 플라스틱은 c-c 결합을 하고 있어서 미생물에 의한 분해가 힘들지만 미생물이 에스터 결합은 잘 끊을 수 있어 생분해가 된다고 알고 있습니다."},{"q":"그러면 에스터랑 이써의 차이를 알아요?","a":"죄송하지만 다시 말씀해 주실 수 있을까요?"},{"q":"이써요 이써 (화학식도 불러주심)","a":"죄송합니다. 아직 일반화학, 유기 무기 화학은 깊이 공부해 보지 않아서 모르는 것 같습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"조선해양공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 10분","notes":"면접시간이 생각보다 많이 짧음. 학과에 대한 정보보다는 생활기록부 기반으로 질문함.","qa":[{"q":"지원 동기가 뭐예요?","a":"저는 조선해양공학 기술과 인공지능 기술을 융합하여 선박을 가장 경제적이고 안정적으로 운행하는 알고리즘을 개발하고 싶습니다. 따라서 서울대학교 조선해양공학과에서 배우는 조선해양기계학습을 성실히 이수하여 조선해양공학에서 사용하는 인공지능 기술에 대해 배우고 싶고, 또한 서울대학교 조선해양공학과 딥러닝연구실에서 현재 경제적인 운송을 위한 날씨 경로 개발과 해안지역 안전 항해를 위한 강화학습 모델을 개발하는 프로젝트를 진행중이라고 알고 있는데, 저도 이러한 프로젝트를 통해 저의 목표에 한 발짝 더 다가가고 싶어서 지원하게 되었습니다."},{"q":"조선해양공학과 인공지능 기술을 결합하는 것은 다른 학교에서도 할 수 있는 것 아닌가요?","a":"네, 하지만 현재 서울대학교 딥러닝연구실에서 진행하고 있는 프로젝트가 저의 목표와 관련되어있기 때문에 서울대학교에 지원하게 되었습니다."},{"q":"수학에서 가장 좋아하는 분야가 어디예요? 그 이유는?","a":"미분을 가장 좋아합니다. 왜냐하면 변화량을 통해 미래를 예측한다는 것이 흥미로웠기 때문입니다."},{"q":"적분이 그래프의 면적을 의미하는 이유가 뭘까요? 부피도 되지 않을까요?","a":"저희가 다루는 적분은 2차원 좌표평면에서 존재하는 1차원 그래프를 적분하는 것이기 때문에 2차원 면적이 나온다고 생각합니다."},{"q":"그럼 왜 면적이 나올까요? 면적의 절반이 나올수도 있고 면적의 1/5가 나올수도 있는 것 아닌가요?","a":"(제대로 답변 못함)"},{"q":"1학년때 도서관 활동에 많이 참여했네요. 참여한 이유가 뭘까요?","a":"고등학교에 올라오면서 학업으로 인해 책을 읽을 시간이 줄어들 것 같아 도서관 행사에 참여해서 조금이라도 책을 읽을 기회를 늘리고자 했습니다."},{"q":"생활기록부에 약학에 관련된 내용이 많네요, 약학에서는 인공지능을 어떻게 활용할 수 있을까요?","a":"약학에서 구조 활성의 정량적 관계를 이용하는데, 이는 분자의 구조에 따른 특성을 예측하는 방법입니다. 이를 통해 각각의 분자들의 특징에 따른 효과를 인공지능으로 예측하고 의약품을 개발 할 수 있습니다."},{"q":"그런거는 인공지능이 아니더라도 할 수 있지 않나요?","a":"단백질은 고분자이기 때문에 여러 분자들의 구조를 이해하고, 각각의 구조에 따른 특성을 예측해야 할 뿐만 아니라 여러 분자들이 섞이면서 나오는 새로운 특징들을 이해해야 하는데 이를 하기 위해서는 인공지능이 필요하다고 생각합니다."},{"q":"그럼 무슨 인공지능 모델을 사용해야 할까요? 아는 인공지능 모델이 있을까요?","a":"(모른다고 함)"},{"q":"DNA 염기서열 분석법에 대해서 보고서를 작성한 적이 있네요, DNA 염기서열 분석법에 대해 간단히 설명할 수 있을까요?","a":"네 DNA 염기서열 분석법 중 제가 가장 인상깊게 조사했던 파이로시퀀싱에 대해 설명해보겠습니다. 파이로시퀀싱은 DNA의 염기를 투입했을 때, 염기가 DNA에 결합을 하지 않으면 효소에 의해 분해되고, 결합을 하게 된다면 발광 효소로 인해 빛이 나는 방식으로 염기를 분석하는 방법입니다. 이 과정에서 생명과학적 지식들과 화학적 지식들이 같이 사용된다는 점에서 가장 재미있었던 것 같습니다."},{"q":"DNA 염기서열 하면 유전자 가위가 생각나는데, 유전자 가위에 대해 어떻게 생각하나요?","a":""},{"q":"유전자 가위의 윤리적인 측면을 말씀하시는 걸까요?","a":""},{"q":"유전자 가위의 윤리적인 측면이나 기술적인 측면이나 아무거나 말해보세요.","a":"네 유전자 가위의 기능적인 측면에서는 현재 치료할 수 없던 유전병들을 유전자 가위 기술 한 번에 치료한다는 점에서...(면접끝남)"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"학생부종합(기회균형특별전형)","method":"총 10분, 3분 공통문제 질문 후 7분 서류 기반 면접 진행서류 기반 면접은 학생의 생기부에 나오는 내용을 바탕으로 하므로 학생마다 질문의 차이가 있기 때문에 본 면접 후기에는 공통 질문만 기록했습니다.","notes":"문을 받게 되니 답변이 간결하되 핵심을 담고 있어야 합니다. 과정을 너무 길게 이야기하기보단 결과를 우선 중심적으로 이야기하고 추가 질문이 들어온다면 그때 더 자세한 설명을 하는 것을 추천드립니다. 자신의 생기부에 대한 확실한 숙지를 하는 것은 기본 중의 기본입니다. 진로, 자율, 동아리 내용뿐만 아니라 교과목 활동에 대한 확실한 이해 역시 요구됩니다. 마지막으로 팁을 드리자면, 서울대는 지적역량뿐만 아니라 리더십과 인성도 중요시하는 학교입니다. 답변을 할 때 이런 요소들도 챙기며 연습하는 것이 도움될 것입니다.","qa":[{"q":"사회적 문제를 과학 분야 간 융합으로 해결한 사례를 말해보세요. 개인적인 사례도 좋고 역사적인 사례도 좋습니다.","a":"우주쓰레기에 대해 말씀드리려 합니다. 우주쓰레기를 기존에는 포획하는 방식으로 해결하곤 했는데, 그 방식이 충분하지 않다고 판단한 연구자들은 새로운 방식으로 자가포식 메커니즘을 이용한 로켓을 개발했습니다. 생명과학에서 다루어지는 자가포식 메커니즘을 우주공학 분야의 로켓과 융합해서 우주쓰레기라는 사회적 문제를 해결한 사례라고 생각합니다."},{"q":"자가포식 메커니즘을 이용한 로켓에 대해 더 자세하게 설명해주세요.","a":"자가포식 메커니즘을 이용한다는 것은 로켓이 제 임무와 역할을 다했을 때 자가포식을 통해 소멸하게 되는 것을 말하는데, 생명체 내의 세포가 제 역할이 다하면 자가포식을 통해 사멸하는 것과 유사하다고 알고 있습니다."},{"q":"첨단융합학부는 분야 간 융합이 중요한 학부입니다. 융합 분야의 연구자로서 가져야 할 자질을 하나 말해보세요.","a":"저는 융합 분야 연구자로서 가져야 할 자질이 ‘이해’라고 생각합니다. 연구를 함께 진행할 때 어떤 분야가 어떤 부분에 적용되었을 때 가장 효율적인지에 대한 확실한 ‘이해’가 있어야 하고, 다른 분야의 연구자들과 서로를 ‘이해’하는 능력이 있어야만 융합을 통한 최대의 시너지를 얻는 것이 가능하기 때문입니다."},{"q":"서울대학교 첨단융합학부에 진학한다는 것은 미래의 인재가 되기 위한 과정을 거친다는 것입니다. 자신이 인재의 자질을 가지고 있다는 것을 보여주는 근거를 제시해보세요.","a":"제가 미래의 인재가 될 수 있다는 것은 제가 가진 아이디어를 말씀드림으로써 보여드릴 수 있다고 생각합니다. 저는 서울대학교 첨단융합학부에 진학해서 뉴로모픽 반도체와 양자컴퓨터의 융합 기술을 개발하려는 목표를 가지고 있습니다. 제 목표를 실현한다면 전력 효율의 증가를 통해 인류의 삶의 질을 향상할 수 있을 것입니다. 이런 아이디어와 목표를 지니고 연구에 임할 것이라는 다짐이 인재로서의 제 자질을 보여준다고 생각합니다.서울대학교 기회균형 면접은 10분 정도로 비교적 짧게 진행됩니다. 그중 3분은 공통 질문, 7분은 서류 기반 질"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"개별 / 대면 / 서류기반 면접 / 평가자 2:1 / 면접시간 10분 내외","notes":"면접관 두 분 모두 교수님 같으셨음. 거리가 약 1m 정도로 매우 가까움.전공 내에서 지망하는 세부 전공과 관련된 질문은 나오지 않았음.","qa":[{"q":"블록체인과 nft 원리가 뭐에요?","a":"네트워크의 거래 내역을 담은 장부를 네트워크 참여자들에게 나누어주어 보안성을 높인 기술입니다."},{"q":"왜 ‘체인’이라는 이름이 들어갈까요?","a":"아 거래를 담은 블록이 서로 연결돼서 체인의 형태를 띠어서 그렇습니다."},{"q":"왜 보안성이 높은가요?","a":"각 참여자가 그 체인을 공유하고 있기 때문입니다."},{"q":"음…그건 아닌데","a":"아 블록을 악의적으로 조작하면 앞 뒤 체인과의 링크가 끊어지게 돼서 다른 분기로 진입하기 때문에 그렇습니다."},{"q":"음... 해시 함수의 특징 때문에 그런 건데 나중에 공부해봐요.","a":"넵 알겠습니다"},{"q":"CoT와 관련된 탐구가 있는데, CoT가 뭔가요?","a":"CoT는 LLM에 단계적 사고를 하도록 하는 프롬프트입니다.그 탐구는, 인공지능 기초 과목에서 비버 챌린지라는 컴퓨팅 사고력 문항을 풀이할 때 올바른 답이 나오지 않았던 경험을 계기로 진행했습니다. 수능 수학 문제, 비버 챌린지 문제에 대해 기본 텍스트 프롬프트, CoT, 텍스트와 이미지를 활용한 멀티 모달리티 프롬프트를 사용했습니다. 결과적으로 수능 수학 문제는 CoT, 비버 챌린지 문제는 멀티 모달리티 프롬프트가 좋은 성능을 보였습니다. 수능 수학 문제는 인간의 연역적 사고를 필요로 하기 때문에 CoT가 좋은 성능을 보였고, 비버 챌린지 문제는 상황에 대한 이해가 중요하기 때문에 이 이해를 돕는 멀티 모달리티 프롬프트가 좋은 성능을 보인 것으로 추측해 보았습니다."},{"q":"다익스트라 알고리즘이 무엇인가요?","a":"다익스트라는 그래프 분석 알고리즘인데, 분석하고자 하는 그래프의 가중치가 양수일 때 사용할 수 있습니다."},{"q":"뭘 구하려고 쓰는 알고리즘인가요?","a":"어…최단 경로입니다"},{"q":"이걸 구현할 때 힙 자료구조가 필요한데, 알고 있어요?","a":"아 힙이 쓰인다는 건 알았는데, 힙 자료구조는 몰라서 안 썼습니다. 추후 자료구조에 대한 강의를 듣고 공부하고 싶습니다."},{"q":"아...그럼 힙은 안 쓰고 다른 걸로 구현한 거네요?","a":"넵. 저는 파이썬으로 구현해서, 리스트를 사용해서 구현해 보았습니다."},{"q":"이건 어려운 알고리즘인데, 어디서 배웠어요?","a":"인공지능 수학 같은 공동교육과정에서 배웠습니다."},{"q":"수학 잘해요?","a":"네. 좋아합니다."},{"q":"그럼 어떤 과목을 제일 잘해요?","a":"문학입니다."},{"q":"어떻게 공부했어요?","a":"시나 소설에서 어떤 상황에서 생겨나는 화자의 마음을 탐구하는 것을 중점적으로 공부했습니다."},{"q":"왜 좋아해요?","a":"제가 하고자 하는 일이 인간의 지식을 인간의 사고로 옮기는 일인데, 이를 위해서는 멀티 모달리티로 된 지식을 벡터 공간으로 인코딩해야 합니다. 이 과정을 모든 사람들이 인정할 수 있도록 하려면 인간의 의식을 오래 담아온 인문학과 같은 문학이 큰 역할을 할 것이라 생각했습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"서울대학교","dept":"건설환경공학부","jeonhyeong":"학생부추천/지역균형","method":"학생부 면접 / 대기실에서 대기 후 순서에 따라 조별로 이동, 10분 면접 진행","notes":"면접 후 나오면 학교 선배인 척 말을 거는 이단 종교 신도가 많음","qa":[{"q":"우리 학과에 지원하게 된 동기가 무엇인지에 대해 구체적으로 좀 알려주세요","a":"저의 꿈은 정부 산하 부처에서 국토균형발전, 도시재생 등에 대해 연구하는 업무를 하며 우리 사회의 안전과 발전에 기여하는 것입니다. 2022년 수도권 대홍수 사태, 광주 인천 아파트 붕괴 사건 등을 보며 재해안전과 건설안전을 위해 필요한 것은 무엇일지 생각하게 되었습니다. 이후 BIM과 디지털트윈의 결합 등에 대해 연구하며 건설환경공학이 최첨단기술과 융합할 때 비로소 혁신적 해결방안을 마련할 수 있음을 알게 되었습니다. 또한 국토균형발전과 도시재생 등에 관한 기사를 접하고 건설환경공학이 우리 사회의 구조적 문제를 해결할 수 있는 학문이라는 점을 깨닫게 되었습니다. 저는 앞으로 혁신적 사고와 최첨단 기술을 융합하여 사회 안전과 발전에 기여하고 싶었기에 이 학과를 지원하게 되었습니다."},{"q":"3학년때 TBM 관련해서 한 탐구활동이 있던데, 이거에 대해서 한번 이야기해봐요.","a":"TBM은 우선 커터헤드를 회전시키면서 디스크 커터가 지반을 굴착합니다. 이후 이수 또는 굴착된 버력으로 챔버를 채워 막장압을 유지합니다. 그리고 굴착과 동시에 이렉터를 이용해 터널 벽면에 세그먼트를 설치하는 방식으로 작동됩니다. 여기서 저는 TBM 공법의 트렌드에 대해 조사하며 지름을 길게 한다는 초단면화, 빠른 굴진을 하는 초굴진화, 우리나라의 한강터널과 같이 터널의 길이를 연장하는 초장대화, 더 깊이 하는 대심도화 등에 대해 알아보았습니다."},{"q":"그러면 이 TBM 공법이 어떤 지반에 이용되는 것이 좋을지에 대해 알고 있는 것이 있나요?","a":"TBM 공법이 발파진동이 적어 안전성이 높고, 도심지에 근접하게 건설할 수 있다는 내용을 본 적이 있습니다. 그렇지만 그게 어떤 지반에 적용되는 것이 유리할까에 대해서 구체적으로는 제가 잘 모르겠습니다."},{"q":"과학분야에 관심이 많아서 1학년때 동아리를 한 것 같은데, 이거에 대해서 한번 얘기해주세요.","a":"네. 1학년 때 한 라온동아리는 토론동아리였습니다. 토론동아리에서 각종 주제에 대해 토론을 하며, 통일에 대한 찬반을 주제로 토론을 할 때 건설환경 분야와 접목해서 근거를 말한 적이 있습니다. 북한의 경우에는 기본적인 상수도, 그러니까 소방시설보다도 이 기본적 상수도 자체가 제대로 구축되어 있지 않고, 건물 같은 경우에도 내진설계가 되어 있지 않고 안전 측면에서도 부실한 건물들이 많은 상태입니다. 그렇기에 전면적인 도시 재개발이 필수적일 것이고, 또 통일이 되면 대륙을 연결하는 철도가 구축되어 물류 운송에도 적합할 것입니다. 그래서 그런 과정에서 또 우리 토목공학의 최첨단 기술 등을 접목시키며 많은 발전을 이뤄낼 것입니다. 이런 부분에 대해 이야기했습니다."},{"q":"네. 보면 국토균형발전에 대해 탐구를 많이 한 것 같은데, 국토균형발전이 왜 필요한 걸까요?","a":"우리나라의 경우에는 전국에서 소멸 위험지역, 그리고 20세에서 39세의 여성에 대한 65세 이상 여성의 비율을 나타낸 수치가 0.5를 넘지 않는, 그런 지역이 절반이 넘습니다. 이렇게 지역 소멸이 일어나며 수도권 인구집중이 나타나고, 그러면 집값 상승, 경쟁 심화 등으로 인해 저출생, 일자리 부족과 같은 부가적인 사회문제까지 이어지게 되기 때문에 지역에 대한 균형을 유지하는 것이 헌법적 가치까지 고려했을 때에도 필수적이라고 생각합니다."},{"q":"그렇다면 지원자가 가지고 있는 단점이다 싶은 것. 장점은 많을 거 아니에요. 단점이다 싶은 것에는 어떤게 있나요?","a":"지금은 많이 극복이 된 단점이지만 우선 저는 선천적으로 체력이 약한 경향이 있었습니다. 1학년 때는 많이 느끼지 못했는데 2학년이 되며 잠도 많아지고, 이런 체력 문제가 드러나게 되면서 이걸 어떻게 해결할까에 대해 많이 생각해 보았습니다. 저희 학교같은 경우에는 체대입시를 준비하는 친구들도 많이 있었습니다. 그래서 그 중 한 친구에게 체력을 기르기에 좋은 게 뭐냐 물어봤더니, 그냥 뛰는 게 가장 좋다라고 하였습니다. 그래서 그 이후로 그 친구들과 함께 소화도 시킬 겸, 점심시간마다 운동장을 몇 바퀴씩 뛰고, 이렇게 하다보니 지금은 정말 많이 좋아졌습니다."},{"q":"그러면 지원자가 가장 중요하게 생각하는 가치, 그런게 있을까요?","a":"저는 능력과 인품을 겸비한 사람이 되자라는 것을 제 좌우명으로 삼고 있습니다. 예를 들면 세종대왕 같은 경우에도 훈민정음을 창제하실 때, 말하고자 하는 바가 있어도 뜻을 펼치지 못하는 백성들을 가엾이 여기는, 그런 측은지심으로 훈민정음을 창제하였다고 하셨습니다. 이렇게 제가 가진 능력과 인품이 결합해 시너지를 이룰 때 비로소 우리 사회에 이바지하는 그런 훌륭한 인물이 될 수 있다고 생각합니다.전공질문보다 공통질문의 비중이 다소 높았음, 교수님들이 학생들의 생기부를 꼼꼼히 숙지특이점하진 않은 듯 했음.합/불 분석최초합아쉬운 점"}],"naesin":"1.03","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합전형/ 기회균형특별전형(사회통합)","method":"서류 기반 면접 면접 대기실에 입실을 완료한 후 수험생 확인 및 안내사항을 전달받음. 이후 / 면접실로 이동하여 서류 기반 면접을 진행함.","notes":"서울대 입학 웹진 ‘아로리’ 확인!!","qa":[{"q":"지구과학 실험, 기하, 인공지능 수학을 선택했는데 왜 선택했나요? (남)","a":"지구과학 실험을 선택한 것은 천체 물리학에 관해서는 어려서부터 관심을 가지고 있었고, 기하는 물리학, 수학과 함께 항공우주공학에 필수적으로 사용되는 학문이어서 선택했습니다."},{"q":"여기는 기계관데요? (남) (웃음, 분위기 환기?) 그렇다면 왜 기계공학과에 지원하게 되었나요? (여)","a":"저는 고등학교 3년 동안 배우는 지식은 대학 수준의 지식에 비하면 아주 기초적인 수준의 지식이라고 생각했습니다. 평생 공부하게 될 전공을 고등학교 3년의 얕은 경험을 기반으로 선택하는 것이 부담스럽게 느껴졌고, 보다 폭넓은 분야를 다루는 기계공학과에 지원하여 공부하는 것이 앞으로의 저의 진로 선택을 비롯해 저에게 도움이 될 것이라 판단하였습니다."},{"q":"(3학년 물리학 세특 중 레이놀즈 수에 관한 탐구 내용) 레이놀즈 수가 무엇인가요? (남)","a":"층류, 난류와 같은 유체의 유동을 구분하는 무차원 수라고 알고 있습니다."},{"q":"그렇다면 실제 난류의 예시는 어떤 것이 있을까요? (남)","a":"수도꼭지에서 물을 강하게 틀면 물이 불규칙적으로 층을 이루지 못한 채 흐르는 것이 있습니다."},{"q":"그러면 층류에는 어떤 것이 있죠? (남)","a":"아까와 같은 예시를 들어 설명하자면, 수도꼭지에서 물을 약하게 틀 때 물이 층을 이루어 흐르는 것이 있습니다."},{"q":"1학년 동아리 활동 시간에 가장 기억에 남았던 것은? (여)","a":"양자 컴퓨터 관련 책을 읽고 토론한 것이 가장 기억에 남았습니다."},{"q":"어떤 내용으로 토론했는지는 기억이 나나요? (여)","a":"음.. (기억이 잘 안 났음) 양자 컴퓨터의 발전이 인류에게 꼭 도움이 되는지에 관해 토론했습니다."},{"q":"혹시 본인은 어떤 생각인가요? (여)","a":"음... 양자 컴퓨터의 도입은 많은 분야에서 빠르게 시간을 절약할 수 있게 해주어 도움이 되었지만, 너무 빠른 것은 삶의.... 꼭 필요한 것들을 놓치게 할 수 있어..있다고 생각합니다."},{"q":"학교 생활하면서 어려웠던 것이 있나요? (여)","a":"네. 저는 중학교 때 인간관계에 관한 회의감으로 방황했던 적이 있습니다. 밖에서는 항상 타인의 시선을 의식에 스트레스 속에서 살았습니다. 그러던 중 아들러 심리학이 담긴 미움받을 용기라는 책을 알게 되었습니다. 이 책에서 제가 가장 기억에 남았던 것은 내가 통제할 수 있는 것과 없는 것을 구분하라는 ‘과제의 분리’였습니다. 타인의 의식은 통제할 수 없기에 그것에 얽매이지 말고 자유롭게 살아가라는 내용이었습니다. 저는 고등학교에 올라와서도 항상 이 책과 함께 생활하였고, 이전과 같은 강박증에서 벗어날 수 있었습니다."},{"q":"그렇다면 왜 유체는 층을 이루어 흐르죠? (남)","a":"흐르는 유체의 중심에서 바깥쪽으로 갈수록 속도가 점점 느려지는데 이러한 속도 차이 때문에 유체가 층을 이루어 흐른다고 생각합니다. Ÿ 입학사정관 남녀 두 분이 면접을 진행하셨음. 위의 질문 순서는 다 기억이 나지는 않아 대략적인 순서임. 두 분이 번갈아서 진행하며, 자신이 했던 활동에 대한 꼬리질문이 핵심.Ÿ 보통의 면접 준비 할 때의 예상 질문같은 것은 거의 직접적으로 물어보지 않았음. 아로리에도 나와있는 것이지만 서울대 면접관들은 준비된 답변을 싫어함. 구체적으로 예상하지 못한 질문에는 웅얼거리며 답변하지 못한 채 예상 질문에 대해서만 기계적으로 뱉어내는 것을 싫어함. 학과에 대한 지원동기, 이후의 진로계획, 선택과목의 선택 이유 등에 관해서특이점는 잘 정리해 놓고, 나머지는 예상 질문과 답변 암기가 아니라 생활 기록부에 나와있는 활동들을 돌아보며 구체적으로 꼼꼼히 여러번 복기하는 과정을 거치면 됨.Ÿ 10분 동안 아주 많은 것을 물어볼 수는 없고, 본인이 갔던 면접은 지원자들에게 마지막으로 하고 싶은 말, 1분 자기소개 같은 것은 전혀 물어보지 않음. 순식간에 시작해서 10분이 지나는 즉시 끊고 다음 지원자가 들어갔음. 결론은 생기부에 적혀있는 자신의 활동들에 대해 잘 ‘숙지’한 채 (답변을 달달 외우는 것은 비추천) ‘주요’ 예상 질문에 대한 답변을 준비하면 됨. 합/불 분석아쉬운 점말을 더듬은 것."}],"naesin":"1.41","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류평가 100 (2배수) 【2단계】 1단계 성적 70 / 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"기계공학부","jeonhyeong":"학생부종합/지역균형","method":"생기부기반 / 2명의 면접관과 10분간 면접","notes":"","qa":[{"q":"간단하게 지원동기와 자기소개 해주세요","a":"다양한 기계장치와 그중에서도 엔진에 관해 큰 흥미를 느껴 기계공학부에 지원하였습니다. 어릴 적부터 비행기에 대한 관심이 높아 중학교 고등학교를 거치며 비행기에 대한 탐구를 진행했고 비행기에 탑재된 여러 기계장치들과 엔진에 대해 알게 되었습니다. 이후 ‘무거운 비행기가 어떻게 하늘을 날까?’ 라는 호기심이 ‘저런 섬세한 기계장치들이 모여서 하늘을 난다는 장엄한 일을 하는구나’라는 충격이 되었고, 기계공학에 자연히 이끌리게 되었습니다. (긴장해서 자기소개를 까먹었습니다.)"},{"q":"자기소개도 해주세요","a":"저는 학업에 대한 끈기와 협업능력을 가진 지원자라고 생각합니다. 학교생활을 하며 이해가 안되는 부분에 대해 넘기지 않고 끈기있게 탐구하여 습득하는 경험을 많이 하였고, 리더의 역할을 자주 맡으며 다양한 성격의 동료와 성공적으로 협업하는 경험을 하였습니다. 이러한 경험을 통해 더욱 그러한 역량을 기르는 데에 노력했습니다.(생기부 기재내용을 바탕으로 지원동기와 자기소개 준비하였습니다.)"},{"q":"생활기록부를 보니 1학년때 종이비행기에 대한 강연을 듣고 활동을 진행하신거 같은데, 어떤 활동을 하셨나요?","a":"종이비행기 강연자분이 오셔서 종이비행기를 비롯하여 물체가 하늘을 나는 원리에 대해 알려주시고 그것을 바탕으로 종이비행기의 비행을 설계하는 방법에 대한 강연을 들었습니다. 이후 강연 내용을 바탕으로 종이비행기를 멀리 날아가는 목적으로 직접 제작하여 날려보는 활동을 진행했습니다."},{"q":"대륙간탄도미사일이나 종이비행기가 멀리 날아가게 할 수 있는 방법이 뭘까요?","a":"우선 대륙간탄도미사일과 종이비행기의 가장 큰 차이는 동력이라고 생각합니다. 대륙간탄도미사일에는 엔진이 탑재되어 비행중에도 지속적으로 출력을 얻을 수 있다고 알 수 있습니다. 하지만 종이비행기는 던지는 순간 손을 떠날때 주어지는 동력만으로 비행을 합니다. 때문에 비행에 관여하는 다양한 요인중 균형에 관한 부분이 멀리 날아가게 하는 부분에 있어 중요하다고 생각합니다. 직선 비행의 가정하에 좌우에서 작용하는 중력과 양력 항력 추력이 같아야 할 것이고 이를 통해 우선적으로 무게중심과 공력중심이 비행방향의 중심축에 위치해야 합니다. 이러한 과정으로 균형을 통해 동력이 헛되이 소비되지 않게 하는 것이 멀리 날아가게 하는 방법 중 하나라고 생각합니다."},{"q":"지원자의 생활기록부를 보면 항공쪽에 대한 관심이 높은것 같은데, 서울대학교에는 항공우주공학과가 따로 있단 말이죠? 왜 기계공학부에 지원하셨는지 말해줄 수 있을까요?","a":"앞서 말씀드린 대로 비행기에 대한 탐구를 진행하며 비행기에 탑재된 다양한 기계장치와 엔진에 대한 흥미가 높아져 그러한 기계에 대해 더 자세히 공부하고 싶어 기계공학부에 지원하게 되었습니다. 큰 중량의 물체가 하늘을 난다는 것에 대한 경외감과 호기심이 그것을 이루게 하는 기계장치에 대한 깊은 인상으로 이어졌고, 중학교 고등학교에서도 배우는 간단한 과학적 지식을 바탕으로도 복잡하고 효율적인 기계를 설계 제작하는 기계공학에 대해 매료되어 기계공학부를 지원하게 되었습니다."},{"q":"답변을 들어보니 엔진에 대한 관심이 높으신 것 같은데 엔진과 관련하여 10년 뒤에는 어떤 일을 할 것 같고 어떤 일을 하고 싶나요?","a":"새로운 매커니즘의 엔진을 개발하고 싶습니다. 물론 기존의 엔진에 대해서도 다양한 연구 개발을 수행할 것 같습니다. 하지만 기존 엔진의 메커니즘 초월하는 새로운 엔진을 만들어 보고 싶습니다. 예를 들면 현재 열심히 개발 중인 핵융합에너지를 이용한 엔진이나, 이론상으로 에너지의 극치라 여기는 반물질을 이용한 엔진을 설계하여 보고 싶습니다. 현재까지는 고등학생의 지식으로 아는 지식이 드물겠지만 서울대학교 기계공학부에 들어가 관련 지식을 배우고 그러한 바람을 실현하고 싶습니다."},{"q":"그럼 엔진에 대한 탐구에 서울대학교 기계공학부의 어떤 커리큘럼이나 수업이 도움이 될거라고 생각하세요?","a":"엔진은 그 엔진이 탑재된 동체에 대한 부분과 엔진 사용 시 동체의 운동을 고려해야 한다고 생각합니다. 때문에 서울대 안에 있는 풍동실험시설이 이러한 부분에 있어 도움이 될 것 같습니다. 동체가 운동하는 환경은 실제 환경이기 때문에 지구 내에서 운동하는 동체의 경우 관련한 유체역학에 대한 부분을 고려해야 된다고 생각하기에 풍동시설 같은 부분에 도움을 받을 수 있다고 생각합니다."},{"q":"100톤의 무게의 순금과 100톤 무게의 로켓발사체 중 어떤 것의 값이 높을까요?","a":"제가 순금의 가격을 잘 모릅니다. 하지만 질문해 주신 내용에 대해 생각해 봤을때 100톤 무게의 로켓발사체의 값을 높게 상정하고 싶습니다. 로켓발사체에 포함되는 물질, 원소 하나하나의 질량으로 값을 매겼을때 값은 꽤나 저렴한 것으로 알고 있습니다. 하지만 그런 원소를 가공하여 부품을 만들고 이 부품을 조립하여 기계장치를 만들고 그러한 기계장치가 모여 로켓발사체를 이루는 과정을 생각했을때, 크게 연결이라는 이러한 부분에 높은 가치를 두고 싶습니다. 연구자들이 이러한 연결을 생각해내고 제조과정에서 이러한 연결을 수행하고 하는 모든 과정에 엄청난 노력과 지성이 탑재되어 있다고 생각합니다. 이러한 부분에 있어 100톤 무게의 로켓발사체에 더 큰 값을 매기고 싶습니다. (마지막 질문이 기억이 나지 않습니다. 이 질문을 40초 남짓 남았을때 받아 답변 도중 면접이 종료되었습니다.)4명이 한 조가 되어 면접을 진행하는 층에 입실함. 지원자 한 명에 면접관 두 분이 10분동특이점안 면접을 진행함. 입장하자마자 느낄 수 있을 정도로 면접관 두 분이 압박면접관과 온화한 면접관으로 나뉨높은 내신과 무난했던 면접에도 불구하고 불합격한 이유는 생활기록부 내용이 주로 우주항합/불 분석공쪽이어서가 아닐까 생각함. 서울대 기계공학부의 커리큘럼에 대한 질문에 답변을 잘하지 못함아쉬운 점마지막 질문에 답변하는 도중 면접이 끝남"}],"naesin":"1.19","result":"불합격","resultNote":"최초후-보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100%(3배수) 【2단계】 1단계서류70%+면접30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회교육과","jeonhyeong":"학생부종합/지역균형","method":"서류 확인 면접 / 학생 1명과 교수 2명이 10분간 서류 면접 진행","notes":"","qa":[{"q":"사회 문화 과목에서 ‘지역에 따른 교육 격차’를 주제로 탐구했다고 적혀있는데, 탐구 과정을 자세하게 설명해 줄래요?","a":"책을 읽고 코로나19가 불러온 교육 격차에 대해 알게 됨. 이를 좀 더 일반적인 상황으로 만들어보고자 탐구를 진행함. 거주 지역별 지대를 독립 변인으로 설정하고 교육의 질을 종속 변인으로 설정함. 이때, 교육의 질에 대해서 다양한 기준을 적용시켰음"},{"q":"정치와 법 과목에서 ‘국회에 계류 중인 교원 보호법과 개정안을 둘러싼 여러 교원 단체, 시민 단체, 이익 집단의 입장을 정치 주체 별로 소개’ 했다고 적혀있는데, 설명해 줄래요?","a":"당시 ~~ 기사를 보고 미래 교원이 된 자신도 저러한 상황에 처할 수 있음을 생각하게 되었고, 그렇다면 어떠한 법률을 통해 자신을 보호할 수 있는지 알아보고자 연구 진행함."},{"q":"그러면 정치 주체 별 입장을 알려줄 수 있을까요?","a":"기억이 안나용(실제 답변)"},{"q":"2학년 때부터 멘토링을 진행해 왔다고 적혀 있는데, 어떠한 가치를 중점적으로 두고 멘토링을 진행하였는지?","a":"멘토링을 진행하면서 친구들이 단순히 암기 형식의 학습만을 하지 않을 수 있도록 하려고 하였다. 그래서 수업 시간에 배운 학습 내용이 적용된 기사를 하나씩 찾아와서 분석한다거나, 서로의 오개념을 수정시켜 주는 방식으로 진행했다."},{"q":"사회 과제 연구에서 청소년 혐오 표현 관련 보고서를 작성했다고 하는데, 그 동기를 알고 싶음.","a":"주변에서 볼 수 있는 다양한 청소년들이 혐오표현을 거리낌 없이 사용하고, 그에 대한 문제의식을 갖지 못하는 모습을 볼 수 있었음. 그래서 혐오표현을 사용하는 이유와 종류, 사용 대상을 등을 알아보고자 보고서를 작성함"},{"q":"포괄적 차별금지법에 대한 내용이 적혀있는데, 이 법률에 대한 생각은 어떠한지?","a":"당시 조사를 하면서 차별금지법에 대한 찬반이 나뉘었던 걸로 기억함. 찬성측은 단순히 표현의 자유를 침해하는 것이 아닌 오히려 서로의 자유를 보장해 주는 법이 될 수 있다고 주장하였고, 반대 측은 그럼에도 불구하고 표현의 자유가 침해되는 것은 사실이라고 주장함. 저는 법률을 도입하여 혐오 표현을 규제하는 것은 본질적인 해결책이 될 수 없다고 생각하기 때문에 포괄적 차별금지법 도입에 대해서 회의적인 시각으로 바라보고 있음. 법보다는 차이에 대한 교육을 통하여 혐오 표현의 원인인 다름을 이해하지 못하는 것을 해결할 수 있다고 생각함. 한 분께서만 질문 하시고 다른 한분은 그냥 적고만 계셨다. 생기부에 있는 내용을 다 숙지특이점하는게 필요하다. 특히 생기부 내용에 있는 자신의 진로나 전공과 관련된 활동같은 경우는 무조건 내용, 동기는 다 생각해 놓고 면접을 가는 편이 좋다고 생각한다.합/불 분석긴장해서 날려먹은 내용들이 많아서, 면접 끝나고 불합격을 예상하긴 했다.긴장을 너무 많이 해서 준비한 내용도 잊어먹어 제대로 답하지 못했다. 긴장을 푸는 연습이 아쉬운 점필요했을 것 같다."}],"naesin":"1.43","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합/ 기회균형특별전형-사회통합","method":"생기부 기반 면접 (2:1 대면 면접) / 대기실 → 복도에서 대기 → 면접(10분 내외) ∘밖에서 선배님들이 힘차게 응원해주심. 간식도 주심. 엄청 분위기 좋음. 면접장 안도 서울대라는 이름이 주는 중압감이 있지만 기본적으로 조교님들이 다 친절 하셨음. 옆에서 대기하던 친구가 젤리먹어도 되냐고 물어봤는데 흔쾌히 오케오케! 드세요! 해주심.","notes":"∘원래 대기실에서 자료 못 본다고 알고 있었는데 별 간섭 안하시는 것 같았음 (잘 모르겠음). 근데 복도에서 대기할 때는 아무것도 못보고 가만히 앉아서 기다려야 함. ∘학과마다 다를 수 있지만 두 학과 정도 묶어서 같이 대기했음. (지리+복지, 사회+심리 등등) / 면접 들어가기 1분전에 알려주심. 심호흡 천천히 하기.","qa":[{"q":"안녕하세요~ 앉으세요~","a":"넵! (앉음)"},{"q":"많이 떨리시죠?","a":"네 많이 떨립니다! ㅎㅎ"},{"q":"떨지말고 편하게 하세요~ 편하게~","a":"넵!"},{"q":"좋아요~ 학생이 보니까 영어를 되게 잘하시더라고요. 영자신문 만들기에서 ‘The true way to make Korea happy’라는 제목으로 물질적 풍요를 유독 강조하는 우리나라의 사회 풍조에 대해서 쓰고 자료도 수집하고 했던데, 왜 이걸 쓰게 됐는지, 그리고 쓰고 나서 느낀 점이 어땠는지 간략하게 설명해 주시겠어요?","a":"네 알겠습니다! 저는 저뿐만 아니라 주변 사람들, 사회가 편안하고 행복하길 바라는 사람이고, 그래서 행복에 관한 문제에 관심이 많았습니다. 신문기사를 읽다가 한 외국 언론에서 발표한 행복에서 가장 중요한 요소는 무엇인지에 대한 설문조사를 접하게 되었는데, 다른 나라 사람들은 주로 가족이나 친구관계라고 답한 반면, 우리나라 사람들은 물질적인 부, 즉 돈이라고 답했습니다. 우리나라 사람들은 왜 다른나라 사람들과는 달리 물질적인 부에 집착하게 된 것일지 궁금해서 작성하게 되었습니다. 기사를 쓰고 나서, 물질적 부만이 행복의 유일한 요소가 아닌데, 학력주의 등으로 인해 서로를 서열화하고 부만으로 행복을 나누는 풍조가 퍼진 것이 안타까웠습니다."},{"q":"알겠습니다. 학생이 행복에 관한 탐구를 되게 많이 하셨더라고요. 방대한 자료를 찾아보고 탐구를 수행했다고 하는데, 어떻게 행복에 관심을 가지게 되었는지, 어떻게 탐구를 진행했는지 설명해 주세요.","a":"저는 평소 편안해야 마음의 안정을 느끼는 사람이고, 저뿐만 아니라 제 주변 사람들, 이를테면 가족이나 친구, 제가 속한 공동체의 사람들이 행복해야 저도 행복을 느끼는 사람입니다. 제 자신은 행복한 사람을 보냈다고 생각했지만 고등학교 생활을 하면서 친구들과 사회의 사람들이 행복하지 않고 우울해하는 모습을 보고 왜 우리는 행복하지 못한 것일지, 그리고 행복하기 위해서는 어떻게 해야 하는지 궁금해졌기 때문입니다. 이런 궁금증을 바탕으로 저만의 행복지수 만들기(갑자기 말이 막혀서 이것만 말함) 등의 활동을 했습니다."},{"q":"그 행복지수 만들기 활동 말인데, 왜 지표를 이런 식으로 설정하게 되었나요? 그리고 실제로 이걸 해 봤을 때 다른 결과가 나오던가요?","a":"해당 지수는 제가 고등학교 생활 동안 탐구했던 더 나은 삶의 지수, 사회안전지수와 같은 삶의 질과 관련된 지표들을 종합하고, 그와 더불어 시대에 따라 변화하는 주관적이고 상대적인 행복을 반영하고자 했습니다. 그래서 미국의 한 대학교에서 실행했던 실험의 내용을 담은 <세상에서 가장 긴 행복 탐구 보고서>라는 책을 읽고 행복에 가장 영향을 끼치는 요소가 사회적 관계 형성이라는 점을 알고 사회적 관계 형성 지수를 추가했습니다."},{"q":"(더 말하려고 했는데 끊으심. 길어져서 그러신 것 같음.) 직접 시상을 해본 건가요, 아니면 고안만 한 건가요?","a":"시상을 아직 해보진 않았고, 고안만 해보았습니다."},{"q":"알겠습니다. 그러면 본인이 진행한 탐구와 다른 결론이 나올 가능성에 대해 생각해 본 게 있나요?","a":"저는 주로 행복을 사회적으로 더 거시적으로 측정하려고 했던 것 같은데, 경험이나(살짝 멈춤) 가정환경처럼 미시적인 부분을 고려한다면 다른 결과가 나올 수 있을 것 같습니다. 그러나 제가 그 부분은 고등학교 탐구에서는 반영하지 않아서, 그 부분에 대해서는 대학교에 입학하고 나서 추가적으로 탐구해 보고 싶습니다."},{"q":"2학년 동아리 활동에서 인문학적인 소양을 함양했다고 하는데, 이게 본인에게 어떤 변화를 주었나요?","a":"(답변하는 중에 1분 남았다고 밖에서 노크소리 들림) 현재 사회는 기술 발전 등으로 빠르게 변화하고 있고, 그 양상도 분화하고 있습니다. 동아리활동으로 쌓은 인문학적 소양이 이러한 현상들을 정치적, 경제적, 도덕적 관점 등 더 다양한 관점에서 바라볼 수 있게(문 열림) 해 준 것 같습니다."},{"q":"미안한데 시간이 다 되어서 여기서 끝내야 할 것 같아요~ 수고했어요~","a":"감사합니다!! (꾸벅 인사하고 나옴)∘면접 분위기가 편안한 편. 교수님들도 긴장하지 말라고 해주시고, 답변 들으시면서 응응, 어~ 하면서 들어주셔서 말하는 걸 어려워하는 나도 말하기 엄청 편했음.∘이 활동을 진짜 했는지, 탐구한 바를 바탕으로 추가탐구/실천해본 사례, 본인 생각이 어떻게 바뀌었는지, 해당 활동이 자신에게 어떤 영향을 주었는지 등을 중요시하시는 것 같음.∘생기부는 무조건 꼼꼼하게 뜯어봐야 하지만, 그렇다고 해서 예상질문&답변을 무작정 그대로 외우는 건 비추천. 어차피 그대로 안 나올 확률이 9할. ∘친구나 선생님과 자신이 했던 활동이나 관심있는 주제에 대해 이야기하듯 연습하는 것도 좋을 것 같음. 오히려 평소에 긴장을 많이 하는 편이면 이런 분위기가 오히려 말문도 특이점트이고 좋음.∘본인이 3년 동안 얼마나 활동을 열심히 했는지가 바로 나옴. 성실하게 활동했으면 설령 본인이 예상하지 못한 질문이더라도 정확한 개념을 묻는 게 아닌 이상 어렴풋이 기억날 확률 높음.∘본인 생기부가 주제, 색깔이 확실하다면 그것에 대해서 자세하게 물어보시는 것 같음(사람 / 면접관 스타일마다 다를 순 있지만 내 경우는 행복을 주제로 한 탐구를 많이 해서 그 내용을 많이 물어보셨는데 면접 시간 거의 대부분을 내가 공들여서 했던 활동에 대해서 얘기했음.)∘(경상도 사람 기준) 면접관님께서 말씀을 굉장히 천천히 하심. 쓰읍. 어~ 이런거 많이 하심. 질문시간+ 답변시간이 생각보다 길어서 질문이 몇 개 안 될 수도 있음.합/불 분석1단계 합격∘말하면서 내용을 정리하는 타입이라 반복하는 표현이 많았고, 말이 좀 길어진 것 같음.아쉬운 점∘편안해도 면접이다보니 떨려서 말 조금 더듬거림."}],"naesin":"1.36","result":"불합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 2배수 서류 100% 【2단계】 1단계 70+면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"사회학과","jeonhyeong":"학생부종합 / 지역균형","method":"서류 확인 면접 7:40-8:20 입실, 8:20-8:50 대기실 전체 대기, 이후 면접 번호에 따라 5분전 / 복도 대기, 면접 10분 대기실에서 전자기기는 사용할 수 없지만 종이는 볼 수 있기 때문에, 자료를","notes":"미리 프린트해올 것.","qa":[{"q":"면접관1: 동아리 활동 기억하죠? 1학년 때 시사토론, 2학년 때 프리토킹, 3학년 때 경사법이라는 동아리를 했는데, 특히 3학년 활동에 관심이 갑니다. ‘68혁명과 마오주의’라는 주제에 대해 탐구를 했는데 전체적으로 설명해주시고, ‘40년대 자유주의 운동보다 68혁명이 더 큰 영향력을 가진 이유’에 대해서도 말씀해 주세요.","a":"장 뤽 고다르 감독의 ‘네 멋대로 해라’라는 영화를 보다가 고다르 감독이 68운동에 참여하는 장면이 나왔음. 그 뒤에 마르크스와 마오쩌둥의 얼굴이 그려진 포스터와 깃발이 나왔는데, 당시 냉전 체제 하에서 자유주의 진영 국가에서 일어난 운동에 공산주의 국가의 이념이 활용된다는 것이 흥미로워 주제로 선정하게 되었음. 마오주의가 68운동의 이념적 배경으로 작용한 이유는 소비에트식 공산주의와의 차이점에서 찾을 수 있음. 소비에트식 공산주의는 산업 중심이었지만, 마오주의는 농민 중심의 참여를 강조하는 혁명이라는 점에서 68세대의 환호를 받음. 이에 더해 극동아시아에서는 서구와는 다른 유토피아가 건설되고 있다는 오리엔탈리즘적 환상이 더해진 것이라 볼 수 있음. 발표 후 ‘40년대 자유주의 운동보다 68혁명이 더 큰 영향력을 가진 이유’를 묻는 질문을 받아서 추가 조사를 해봄. 그 이유는 범위에서 찾을 수 있음. 40년대 자유주의 운동은 제2차 세계대전 이후 자유와 권리의 회복을 강조한 반면 68운동은 더 넓은 범위에서 일어났음. 이는 이후 페미니즘과 록 음악의 발전으로 이어졌기 때문에 더 큰 영향력을 가짐. 또한 40년대 자유주의 운동은 국가적 단위에서 일어났다면, 사회학자 프란츠 파농이 정의했듯이 68세대는 ‘Live TV generation’임. 그렇기 때문에 세대적 연대를 바탕으로 초국가적 영향력을 가짐."},{"q":"면접관2: 문화에 되게 관심이 많아 보이네요. 무슬림... 아랍... unipolarity... 이런 내용을 다뤘는데, 사실 앞으로 단극성 체제로 갈 것인지, 다극성 혹은 양극성으로 갈 것인지 논란이 많이 되잖아요. 거기에 대한 본인의 의견과 그리고 바람직한 체제가 무엇인지에 대해서도 말씀해주세요.","a":"미국 중심의 단극적 체제가 유지될 것이라고 생각함. 군사, 경제, 문화적 측면에서 미국이 절대적 우위를 차지하고 있기 때문임. 특히 경제의 경우에는 미국이 달러 패권을 쥐고 있기 때문에 세계 경제의 주도권을 가지고 있음. 페트로 달러 체제가 현재 위기에 있지만 여전히 석유 거래의 대부분이 달러로 이루어지고, 외환 보유고의 59%가 달러인 것으로 알고 있음. 그렇기 때문에 미국 중심의 단극적 체제가 유지될 것이라고 생각함."},{"q":"면접관2: 그럼 중국의 영향력이 그렇게 크진 않다. 양극적 체제로 가진 않을 것이다. 이렇게 생각하는 건가요?","a":"이전에 ‘중국이 세계를 지배한다면’이라는 책을 읽었음. 그 책이 20년 전쯤 책인 것으로 알고 있는데, 그 책을 읽으면서 작가가 예상한 중국의 위상과 현재의 모습을 비교하면서 읽었음. 그 결과, 책에서 작가가 예상한 중국의 부상에 비해서 현재 중국의 영향력이 그리 크지 않다고 생각함."},{"q":"면접관1: 방금 세계의 단극성...에 대해서 얘기를 했는데 3학년 사회문제탐구 시간에 마강래의 지방도시살생부를 읽었어요. 기억나죠? 그 책에서도 단극체제와 비슷하게 ‘수도권 일극체제’를 얘기하는데, 마강래의 주장을 요약하고 그에 대해 비판해주세요.","a":"모든 지방을 균형있게 발전시키는 것은 비효율적이므로 선택과 집중을 통해 광역도시 중심으로 압축적으로 발전해야 한다는 것을 주장한 것으로 알고 있음. 하지만 지역균형발전은 헌법에서도 보장하는 가치이고 도의적으로 보았을 때도 맞음. 또한 노인들의 경우에는 살던 곳에 계속 살고 싶어하는 경향이 있기 때문에, 효율성을 문제로 압축 발전할 도시를 선별하는 것은 노인들의 의사와 상충된 방향으로 갈 수 있다는 점에서 비판할 수 있음."},{"q":"면접관1: 어떻게 상충된다는 것이죠?","a":"노인들이 원래 살던 도시가 압축 발전할 도시로 선별되지 않으면, 투자가 줄어 인프라가 낙후될 수도 있음. 효율적 투자를 위해 도시를 선별하는 것은 선택되지 않은 도시에 살고 싶어하는 사람의 선호를 무시할 수 있다는 점에서 비판할 수 있음."},{"q":"면접관1: 지역 불평등이 심해질 수 있다는 거죠?","a":"네.(1분 남았다는 노크 소리)"},{"q":"면접관2: 시간이 얼마 안남았는데, 사회학과 입학 후 무엇을 배우고 싶은지와 졸업 후 계획에 대해서 말씀해주세요.","a":"사회학과 진학 후 정책 설계 과정에 대해 배우고 싶음. 고등학교에서 사회 문제를 분석하고 그에 따른 해결책을 제시하는 보고서를 작성하는 활동을 많이 함. 그 과정에서 경제 성장과 환경 보호, 사회적 규제와 개인의 자유 등의 딜레마적 상황에 직면함. 그 상황에서 항상 상반된 입장을 절충해서 균형점을 제시해야 한다는 식으로 해결책을 제시했지만 이는 너무 당연하고 추상적이게 들려서, 실질적인 변화를 가져오기에는 역부족이라고 생각함. 따라서 사회학과에 진학한다면 구체적인 정책 설계 과정을 배우고 싶음. 현대 사회의 사회문제는 한 국가에 국한된 것이 아니라 초국가적 영향력을 가지고 있다고 생각함. 따라서 졸업 후에는 UNDP 같은 국제 정책 기구에 들어가고 싶음.(문 열림)"},{"q":"면접관2: 국제 기구에 들어가고 싶다는 거죠? 네 잘 들었습니다.꼬리 질문이랑 압박 질문이 심하다고 했는데, 꼬리 질문이 생각보다 별로 없었음. 주장의 특이점한계점을 지적하거나 반대 입장에서 질문하실 줄 알았는데, 호응 잘해주시고 잘 들어주심.꼬리질문 제외 크게 4질문 (마오주의, 단극성, 지방도시살생부, 앞으로 계획)을 물어보셨는데, 합/불 분석지방도시살생부를 제외한 3질문은 예상한 질문이라서 수월하게 답변할 수 있었음.면접 분위기가 좋아서 웃으면서 자신감 있게 답변했는데, 이가 합격에 도움이 됐다고 생각함. 아쉬운 점질문을 길게 하셔서 답변도 길게 하다 보니, 몇 질문밖에 못하고 시간이 끝남.","a":""}],"naesin":"1.09","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100 (3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합/지역균형전형","method":"서류 기반 면접 대기실에서 대기 후 면접 2분 전에 본인 차례임을 알려줌. 그 후 면접실 바로 밖에서 약 1~2분 대기 후 이전 차례 학생이 나오면 면접실에 / 들어가서 면접을 진행함. 10분 내외로 면접이 진행되며, 면접이 끝나면 퇴실함. 대기실 입실 시간 이후에는 본인이 준비한 자료 전혀 보지 못함.","notes":"2분 남았을 때 노크 한 번, 그리고 면접 시간이 다 되었을 때 노크 한 번으로 총 두 번 노크해 줌.","qa":[{"q":"길이 많이 미끄럽지는 않았냐고 질문함.","a":"많이 미끄러워서 조심해서 왔다고 답변했습니다."},{"q":"3학년 동아리활동에서 머신러닝 파트를 맡아 데이터 기술 개념 정리 활동을 진행했는데, 이에 관한 설명 부탁함.","a":"데이터 기술 개념 정리에서 인공지능, 머신러닝, 딥러닝 간에 어떠한 관계가 있는지에 답변했습니다. 그리고 머신러닝 파트를 맡았기에 머신러닝 알고리즘에 관해 탐구를 진행하였으며, 그중 나이브베이즈와 의사결정트리가 있음을 알게 되었다고 했습니다."},{"q":"나이브베이즈와 의사결정트리가 무엇이냐고 질문함.","a":"나이브베이즈와 의사결정트리가 무엇인지 답변했습니다."},{"q":"3학년 자율활동에서 오일러 공식에 관해 탐구 활동을 진행했는데, 오일러 항등식의 수학적 의미와 실용성에 관한 설명 부탁함.","a":"세특에서 말한 오일러 공식이 정확하게는 오일러 항등식임을 밝히고, 오일러 항등식을 구성하고 있는 5가지 숫자들의 수학적 의미에 관해 답변했습니다."},{"q":"5가지 숫자들로 구성된 오일러 항등식 자체의 수학적 의미가 무엇인지, 그리고 탐구활동을 진행하며 느낀 점을 질문함.","a":"관련성이 없어 보이는 숫자들 간의 연결성을 드러낸다는 점을 중심으로 오일러 항등식의 수학적 의미에 관해 답변했습니다. 더불어 탐구활동을 진행하며 숫자들간의 연결성이 있음을 알게 되고, 이에 흥미를 느꼈으며 추후 이와 같은 분야를 연구해보고 싶다고 답변했습니다."},{"q":"오일러 항등식의 실용성에 관해 질문함.","a":"물리, 컴퓨터와 같은 분야에서 활용될 수 있다고 답변했습니다."},{"q":"리더쉽을 발휘한 경험과 그에 대한 느낀점에 관해 질문함.","a":"동아리 부장으로서 리더쉽을 발휘한 경험에 관해 답변했습니다. 동아리 활동 계획, 과학체험전 참여 등 여러 활동을 진행하며 리더쉽을 발휘했다고 답변했습니다.(중간에 2분 남았다고 노크함) 과학체험전과 동아리 활동 계획 등을 하며 어려움을 느꼈으며, 처음에는 적극적으로 학교생활에 참여하고 싶어 부장을 맡았지만, 부족한 점을 되돌아보며 책임의 중요성을 느꼈다고 말했습니다.(뒤에 할 말이 더 남았지만 끝나서 못함.)특이점매우 편안한 분위기에서 면접이 진행됨. 압박 면접과 같은 분위기는 전혀 없었음.아쉬운 점본인이 약간 간과한 부분에서 질문이 나올 수도 있으니 주의할 것."}],"naesin":"1.25","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"식품ㆍ동물생명공학부","jeonhyeong":"학생부 종합/지역 균형","method":"학생부 기반 면접 입실→공지 후 소지품 모두 제출→대기(30분 정도)→면접→면접 후 대기(10분 정 / 도)→퇴실 전자기기뿐만 아니라 학생부나 예상 질문지 같은 종이까지도 모두 제출해야 함.","notes":"대기 시간 동안 할 수 있는 것이 아무것도 없으므로 짐은 최대한 간소하게 챙겨 가는 것이 편함","qa":[{"q":"학생부 기반으로 질문할게요. ‘Survival of the friendliest’를 읽고 활동을 했다고 되어 있는데, 책 내용 중에 가장 공감 가는 내용과, 그 이유가 뭔가요?","a":"우선 그 책을 읽게 된 계기부터 말씀 드리겠습니다. 1학년 진로 활동 시간에 ‘이기적 유전자’를 읽었는데, 거기에서는 적자생존과 경쟁의 관점으로 진화를 바라봤습니다. 하지만 이 책에서는 제목에서처럼 진화에서의 협력과 유대를 강조하고 있으므로, 상반된 관점을 비교해 보기 위해 읽었습니다. 책에서는 보노보와 호모사피엔스의 예를 사례로 들며 때로는 강함보다 상냥함이 생존에 더 도움이 될 때가 있다고 말하는데요, 학교에서도 머리가 좋지만 불친절한 친구보다는 공부를 조금 못하더라도 항상 웃는 얼굴로 다른 친구들을 대하는 친구가 학교생활을 더 잘합니다. 생존에 비유하기는 애매하지만, 확실히 개체의 강함보다는 타인에 대한 친절함이 생활에 더 도움이 될 수 있다는 점에서 공감이 갔습니다."},{"q":"3학년 때 길고양이 개체 수를 줄이기 위한 방법을 탐구했는데, 어떻게 했는지 자세히 말해 주세요.","a":"우리 학교에는 길고양이가 매우 많아서 학생들과 선생님들, 그리고 고양이가 모두 불편을 겪습니다. 수학Ⅰ과 영어 독해 작문에서는 길고양이 개체 수를 TNR을 통해 조절하는 방안에 대해 자세히 탐구했었는데, 학교에서 TNR을 시행하기에는 무리가 있기 때문에 서식지를 분리하는 것으로 방법을 강구해 봤습니다. (크로마토그래피, PCR 이용 방안 설명~~~)"},{"q":"해수 공급 여부에 따른 토마토 당도 상승 실험의 계기, 본인의 역할과 느낀 점을 말해 보세요.","a":"우리 지역의 마늘이 해풍을 맞고 자라서 타 지역보다 맛있다는 기사를 보고, 그렇다면 다른 식물을 재배할 때도 해풍을 맞게 하면 더 맛있어지지 않을까? 하는 가설을 세운 뒤, 친구들과 생명과학에서 배운 대조 실험을 진행했습니다. 그 결과, 실제로 희석한 해수를 공급한 실험군에서 토마토 당도가 더 높았습니다. 실험 중간에 당도 측정계가 없는 문제점이 있었는데, 화학적 지식을 기반으로 전류 측정계를 대신 사용하자는 아이디어를 제시하여 실험이 성공적으로 이루어질 수 있도록 기여했습니다. 저희가 내린 결론이 지역 사회 발전에 도움이 될 수 있을 것이라는 생각에 뿌듯했던 경험이었습니다."},{"q":"해풍과 해수는 차이가 좀 있지 않을까요?","a":"네, 하지만 지리적 여건상 해풍을 직접 맞게 하기는 어려웠기 때문에 우선 식물이 물을 흡수하는 방법에 대해 알아봤습니다. 뿌리로 흡수하는 방법이 있고, 잎을 통해 흡수하는 방법이 있는데, 해풍이 뿌리보다는 잎에 닿을 것이라고 판단했기 때문에 희석한 해수를 잎에 뿌리는 방법, 즉 엽면시비 방법으로 해수를 공급함으로써 최대한 한계점을 보완하려 했습니다."},{"q":"한국사 시간에 곰이 마늘과 쑥만을 먹고 100일간 버틸 수 있는지를 탐구해 봤네요? 왜 안 될 거라고 생각했죠?","a":"(나는 인간으로 가정하고 진행한 건데 교수님은 곰이라고 생각하고 계셨나 봄) 필수 아미노산과 탄수화물이 결핍되어 있을뿐더러, 쑥 속의 카로틴이라는 성분이 지방을 분해하기 때문에 동굴 속에서 에너지를 최대한 비축해야 하는 상황에서 불리하게 작용할 것이라 생각했기 때문입니다."},{"q":"실제로 곰은 겨울잠을 세 달간 자면서 아무것도 먹지 않기 때문에 가능합니다~ 한국사 선생님이 배경지식이 없어서 그렇게 하라고 시켰을 수도 있는데, 아니에요~","a":""},{"q":"‘반려동물 영양학’을 읽으면서 고양이 사료에 대해 탐구했는데, 음... 그러면 고양이 사료에서 가장 중요한 건 뭘까요?","a":"당뇨병 위험이 있기 때문에... 탄수화물 비율을 조절하는 것이 가장 중요하다고 생각합니다. 그리고, 비타민B도 중요한 것으로 알고 있습니다."},{"q":"고양이 사료에서 가장 중요한 건 타우린이에요. 체내에서 합성을 못하기 때문에. 고등학교 선생님은 이런 거 잘 모르시니까 그럴 수 있어요. 대학 가서 배우면서 통합적 지식을 넓히면 좋을 것 같아요~(1분 남았다고 노크함)","a":""},{"q":"시간 거의 다 돼서 나가봐도 좋아요~ (인사하고 나옴)학생부 외에 지원 동기나 향후 계획, 목표 등 상투적인 질문 없었음. 학생부에서도 수학, 과특이점학 말고 영어나 한국사같이 안 중요하다고 판단한 과목에서 질문하심합/불 분석초반에 긴장해서 목소리도 떨렸고 물어보지 않은 것까지 너무 장황하게 설명함. 지원 동기아쉬운 점랑 마지막 할 말 연습 많이 했는데 할 기회가 없었음. 시간 1분 남겨놓고 끝나서 마지막 할 말은 할 수 있었을 것 같은데 안 하고 그냥 나와서 조금 아쉬운 마음이 있음","a":""}],"naesin":"1.93","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형(○) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합/기회균형특별전형","method":"서류 확인 면접 입실 > 수험표 및 신분증 확인 > 전자기기 수거 > 대기 > 면접 > 전자기기 / 회수 후 퇴실 전자기기 수거 후 아무것도 할 수 없음","notes":"(책 읽기x, 유인물x, 자는 것, 멍떄리기, 화장실 정도만 허용)","qa":[{"q":"예... 자기소개 하고 우리 원자핵 공학과에 지원하게 된 동기를 말해보세요","a":"넵 저는 열정의 온도만으로도 핵융합을 상용화 시킬수 있는 열정과 다양한 분야의 관심을 가진 면접번호 ○이라고 합니다. 제가 원자핵공학과에 지원하게 된 동기를 말씀드리겠습니다. 저는 원래 원자핵공학과 수학 두 분야에 많은 관심을 가지고 어느 분야로 진학할지 많은 고민을 하였습니다. 그런데 생각해보니 수학은 제가 노력해서 어떤 결과를 얻는다고 하여도 사람들에게 그 이익이 즉각적으로 돌아가지 않습니다. 하지만 원자핵 공학과는 제가 만약 플라즈마 물리학에 대해서 공부하여서 핵융합의 상용화에 도움이 되는 어떤 발견을 한다면 그 이익이 사람들에게 에너지의 형태로 즉각적으로 돌아갈 수 있습니다. 그런 원자핵공학과의 비전에 매력을 느껴 이 과에 지원하게 되었습니다."},{"q":"음... 학생은 그러면 핵융합에 대해서 관심을 가지고 있는거 같은데요. 핵융합의 난제 같은 것도 조사한거 같은데 말해볼래요?","a":"먼저 토카막 방식에서 핵융합의 난제는 플라즈마의 불안정성 때문에 발생됩니다. 플라즈마를 가열할 때 4000만 캘빈까지는 플라즈마에 전류를 걸어주어 그 전기저항을 이용하여 가열하는 방식을 사용하는데 이 방식은 전류를 걸어주기 때문에 전기장, 자기장이 생겨 플라즈마의 운용을 방해합니다. H-모드의 경우에 가장자리 불안정 현상이 발생하여 곳곳에서 플라즈마의 밀도와 온도가 다른곳이 생겨서 자기섬이 형성되어 플라즈마가 붕괴되는것과 같은 핵융합의 난제가 있습니다."},{"q":"학생이 유체역학에 대해서 공부를 한 것 같네요. 유체역학과 핵융합은 어떤 연관이 있을까요?","a":"먼저 핵융합에서 플라즈마는 디바이 차폐를 만족시키는 이온화된 기체를 뜻합니다. 핵융합은 이런 이온화된 기체인 플라즈마를 얼마나 잘 유지하고 조정하느냐에 달려있습니다. 따라서 유체의 움직임을 예측할 수 있는 유체역학이 필요합니다."},{"q":"3학년 때 공학 동아리를 했다고 나와있네요. 어떤 동아리이고 몇 명 정도 가입되있었나요?","a":"공학에 관련된 수학과 물리학에 관련하여 공부하거나 혹은 자신이 만들고 싶은 것을 만드는 그런 동아리입니다. 대략 23명 정도 가입되어 있습니다."},{"q":"(위의 꼬리질문) 그럼 학생은 여기서 어떤역할을 하였나요?","a":"제가 1학년 때부터 수학과 물리학에서 여러 심화탐구를 많이 진행하다보니 다른 학생들보다 교과과정에 없는 그런 지식을 얻는 법이나 기초적인 미적분, 물리학 지식이 많습니다. 이런 지식을 방식으로 심화탐구에 어려움을 겪는 학생들에게 편미분, 변분법 등을 가르쳐주거나 혹은 이런 지식은 어떤 장소(웹사이트)에서 얻으면 된다 이런걸 알려주는 역학을 하였습니다."},{"q":"허허 학생이 ‘진국’이라는 별명을 가지고 있네요. 왜 이런 별명을 가졌나요?","a":"선생님과 제 친구들이 제 수업 태도와 학문에 관한 태도를 보고 그런 별명을 지어주었습니다. 저는 항상 수업에서 가장 앞자리에서 누구보다 열심히 수업에 참여하였고 수업에서 배우는 지식만이 아닌 조금 더 스스로 공부하여 선생님에게 물어보며 심화탐구하였습니다. 또한 전에 말했다싶이 저는 여러 친구들에게 제 지식을 많이 나누어주었습니다. 이런 지식에 대한 제 태도를 보고 친구들이 “와 이 녀석 ‘진국’이네. 노벨상 타자.” 약간 이렇게 제 별명이 진국이 되었습니다.특이점테이블이 있고 입학사정관 , 교수님과의 거리가 가까움 합/불 분석아쉬운 점유체역학에 관련된 내용을 별로 탐구하지 않았는데 더 탐구하였으면 좋았을 것 같음"}],"naesin":"1.62","result":"불합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(2배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"원자핵공학과","jeonhyeong":"학생부종합/지역균형","method":"확인 면접 / 대기하다가 타이머로 정확히 10분간 확인 면접 진행","notes":"대기시간동안 면접 준비 불가능","qa":[{"q":"생기부를 보니까 고급 물리학을 들은 것이 인상깊은데 고급물리학을 들은 이유가 있나요?","a":"저는 고등학교 생활 동안 물리에 관심이 많았습니다. 중학교 3학년 겨울 방학 때 여러 분야의 책을 읽었습니다. 그 중 물리 분야의 책에 흥미가 갔고, 그 뒤로 물리에 관해 탐구하며 더 심화된 물리학 수업을 듣고 싶다는 생각이 들어 고급물리학을 수강했습니다."},{"q":"1학년때 보어 원자모형의 문제점을 파악하고 물질의 이중성을 통해서 해소했다고 나와있는데, 보어 원자모형의 문제점이 뭔가요?","a":"보어 원자모형은 전자의 정상상태를 가정하고 전자가 특정 정상 상태의 궤도에서만 돈다고 가정하는 이론입니다. 보어 원자모형에서 전자가 입자라면 특정 궤도를 계속 돌지 못하고 에너지를 잃어 원자핵 쪽으로 떨어진다는 문제가 발생합니다. 하지만 전자가 파동성을 가진다면 파동이 정상파가 되어야 함으로 특정 궤도를 도는 것을 설명할 수 있습니다."},{"q":"물리 중에 관심 있는 분야가 따로 있나요?","a":"저는 양자역학에 관심이 많습니다. 1학년 때부터 물질의 이중성, 불확정성 원리 등에 관해 탐구한 경험이 있으며 스핀과 관련하여 탐구하는 등 여러 양자수에 관하여도 학습하였습니다"},{"q":"스핀이 뭔가요?","a":"스핀은 전자 등의 입자에 내재되어 있는 각운동량을 뜻합니다. 스핀에 관해 처음 알게 된 것은 스핀트로닉스라는 책을 통해서 였습니다. 하지만 그 책은 스핀을 이용한 기술에 주목하여 스핀을 전자의 자전이라고 간단히만 설명하였습니다. 저는 이전의 물질의 이중성에 관한 탐구를 바탕으로 전자가 입자성과 더불어 파동성을 가진다는 것을 알고 있었고, 전자가 파동이라면 스핀을 어떻게 설명할 수 있을 지 의문을 가지게 되었습니다. 따라서 스핀이라는 책을 통하여 스핀에 관해 심화탐구한 결과 입자에 내재되어 있는 각운동량임을 알게 되었습니다."},{"q":"그럼 물리에 관심이 있는 건 알겠는데 왜 원자핵공학과에 지원한 것인가요?","a":"저는 학문적 소양을 갖추는 동시에 이를 활용하여 인류에 도움이 되는 기술을 개발하고 싶다는 목표가 있습니다. 지만 고등학교 3년 동안 학문적 탐구를 한 경험은 많았지만 이를 일상생활에 적용하고 새로운 것을 개발하는 경험이 부족하다고 생각했습니다. 저는 대학이 부족한 부분을 배우고 성장하는 곳이라고 생각했기에 공과대학에 지원하였습니다. 그 중 제가 관심있는 양자역학을 활용할 수 있고 제가 관심있는 환경 문제를 해결하는 데에 원자로가 핵심 기술이라고 생각하였기에 원자핵공학과에 지원하게 되었습니다."},{"q":"환경 문제에 원자로가 왜 핵심 기술인가요?","a":"현재 화석 연료를 대체하기엔 다른 친환경 에너지는 충분한 에너지를 내지 못하고 있다고 생각합니다. 따라서 많은 에너지를 생산할 수 있는 원자로가 핵심 기술이라고 생각합니다."},{"q":"저희 학과에서 듣고 싶은 분야가 있나요?","a":"양자역학을 활용한 양자공학과 제가 관심있는 환경과 관련된 시스템 공학 관련하여 공부하고 싶습니다."},{"q":"진로 계획이 있나요?","a":"아직 구체적인 계획은 없지만 대학원 진학 후 연구소에 취업하여 사람들을 위한 기술을 개발하고 싶습니다."},{"q":"공부 외에 하고 있는 것이 있나요?","a":"저는 공학자는 인류와 밀접하고 특히 원자핵공학과는 기술의 부작용이 크기 때문에 올바른 과학 윤리관을 정립하는 것이 중요하다고 생각했습니다. 따라서 토론을 하거나 여러 사례를 고찰하며 올바를 과학 윤리관을 정립하기 위해 노력하였습니다."},{"q":"질문을 잘 이해 못한 것 같은데 취미생활이 있냐고 물어본겁니다.","a":"아 저는 배드민턴을 즐겨 치고 중학교때 처음 접한 저글링도 즐겨 하고 있습니다."},{"q":"아까 연구원이 되고싶다고 했는데 연구원의 자질에 맞다고 생각하는 본인의 장점을 한번 자랑해보세요.","a":"저는 창의력이 뛰어나다고 생각합니다. 1학년때부터 열매가 둥근 이유나 종이가 물에 젖으면 쭈글쭈글해지는 이유 등 저만의 궁금증에 대해 탐구하였는데 교과 선생님들께서 창의력이 뛰어나다고 칭찬해 주신 것이 기억에 납니다."},{"q":"연구원에게 중요한 능력이 뭐라고 생각해요?","a":"새로운 무언가를 발견하기 위해서는 창의력이 첫 번째로 중요하다고 생각합니다. 그 다음으로 공학은 조금의 오차도 큰 실패로 이어질 수 있다고 생각하기 때문에 성실함과 꼼꼼함도 (문 열고 들어옴)"},{"q":"시간 다 됐네요 수고하셨습니다. 특이점질문을 조곤조곤 하시는데 질문의 날카로움이 느껴짐.지원자에게도 긴장감과 압박감이 큰 면접이었겠지만 면접관의 질문에 차분히 본인의 소견을 조리있게 성실하게 답변하려고 노력한 점, 면접관의 추가 질문과 전공적합성을 파악하는 질문에 합/불 분석가감없이 본인의 활동 내용과 견해, 고교생활을 어필한 점이 긍정적인 평가로 이어진 것으로 보임.아쉬운 점","a":""}],"naesin":"1.47","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"지역균형","method":"서류 확인 면접 / 간단한 인사 -> 질문","notes":"대기실, 면접실 모두에서 분위기가 딱딱하지는 않은 편이었음 오전 이른 면접이었으며, 아침을 먹고 왔냐고 따뜻하게 맞이해 주셨음. [질문 내용1]","qa":[{"q":"(윤리와사상 세특 관련) 미디어 리터러시 교육 제도에 대해 탐구했다고 했는데 학생이 실제로 교사가 되면 어떻게 학생들에게 미디어 리터러시 교육을 할 건가요?","a":"학생들이 어떤 사례 속에서 직접 어떤 정보를 받아들일지 결정하고 자신만의 수용 기준을 설정해 보는 활동을 계획한다는 식으로 답변했습니다."},{"q":"학생들에게 직접 생각하게 했는데 잘못된 방향으로 생각한다면 어떻게 할 건가요?","a":"미디어 리터러시 자체의 개념에 대해 다시 설명해 줌으로써 자신의 수용기준에 대해 다시 생각해 볼 기회를 준다는 식으로 답변했습니다.[질문 내용2]"},{"q":"(3학년 자율활동 중 독서내용) 루소의 다른 책 읽은 거 있나요?","a":"아직 읽어보지는 못했으나 제가 읽은 책의 바탕이 된 책이 루소의 ‘에밀’인데 그 책을 읽어보고 싶다는 식으로 답변했습니다."},{"q":"루소의 자연주의 교육관을 현대교육에 적용했을 때의 의의점이 뭐라고 생각하나요?","a":"창의성, 자율성 강화를 중심으로 답변했습니다."},{"q":"부작용도 있을 것이라 생각하는데, 부작용에는 어떤 것이 있나요?","a":"학교교육에서 배우는 것은 공부뿐만이 아니라 미래사회 구성원으로서 갖추어야 할 사회성, 협업능력 등의 다양한 태도와 가치관이 있습니다. 자연주의 교육관을 적용하면 이러한 역량을 기르기 어려움이 있기에 자연주의 교육관은 현대, 미래사회에 전적으로 적용하기는 어렵고 선택적 수용이 필요합니다."},{"q":"수능 윤리과목 응시하셨나요?","a":"네. 평소 윤리과목을 좋아하고, 사상가들의 생각을 심층적으로 분석하는 것을 좋아하여선택했다는 식으로 답변했습니다.[질문 내용3]"},{"q":"그럼 루소의 사상 중에 가장 기억에 남는 거 있었나요?","a":"네. 사회계약론 중에서 일반의지라는 개념이 가장 기억에 남습니다. +일반의지 개념 위주로 추가 설명하였습니다."},{"q":"일반의지에 대해 더 구체적으로 설명해 줄 수 있나요?","a":"서로 충돌하는 욕구같은 것은 배제하고, 모두가 갖는 오직 공익만을 지향하는 것이라는 느낌으로 답변했습니다.[질문 내용4]"},{"q":"미래의 교사에게 필요한 역량이 뭐라고 생각하나요?","a":"미래 사회의 특성상 공부만을 똑같이 가르치기보다는, 학생들 개개인이 스스로 관심과 소질이 있는 것을 배울 수 있는 어떤 태도와 사회성 등을 길러주는 역량이 필요하다는 식으로 답변했습니다."},{"q":"인공지능이나 디지털 교과서 도입같은 변화에 따라 달라지는 역량은 없나요?","a":"우선 인공지능은 (까지 말했는데 시간이 끝남) 꼬리 질문이 있었지만 공격적이라기보다는 생각을 물어보는 질문을 많이 하심. 특이점떨어뜨릴 생각으로 쉬운 질문만 물어본 것 같기도 함.합/불 분석2차 추합 예상 가능한 범위에서 질문이 나왔으나, 긴장하여 구체적 방안을 생각해 내지 못해 추상적아쉬운 점으로 대답한 점."}],"naesin":"1.19","result":"충원합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100% 【2단계】 면접(30) + 1단계 성적(70%)","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"윤리교육과","jeonhyeong":"학생부종합 / 지역균형","method":"생기부 기반 / 생기부 기반 10분 진행","notes":"","qa":[{"q":"이 학과에 지원하게 된 동기를 말씀해 보세요,","a":"고등학교 2학년, 윤리와 사상 수행평가를 준비하면서 우연히 보게 된 넷플릭스 드라마 ‘소년심판’은 윤리교육과를 선택한 결정적인 계기가 되었습니다. 드라마는 소년범을 혐오하는 주인공이 판사로서 실제 사건을 바탕으로 한 소년범죄를 다루는 내용인데, “인생에서 중요한 것은 마침표가 아니라 쉼표다.”라는 대사가 가장 인상 깊었습니다. 누구나 실수를 하지만 그렇다고 그 실수가 곧 실패는 아니라는 의미로, 이것이 유교 사상가 순자가 말한 화성기위와 닮아있다고 생각했습니다. 인간의 본성은 악하다는 성악설의 대표 학자인 순자는 예법과 후천적인 교육을 통해 악한 본성을 교화하여 충분히 선하게 바뀔 수 있다고 믿었습니다. 저는 이러한 순자의 사상을 본받아 교권을 침해하거나 문제행동을 보이는 학생들에게 바뀔 수 있다는 믿음을 가지고 다가가려는 윤리 교사가 되고자 윤리교육과에 지원하게 되었습니다."},{"q":"정말 그 이유로 윤리 교사를 꿈꾸게 된 게 맞아요? (다른 면접관분이 웃으심)","a":"(1차 당황했지만 웃으면서) 네, 정말 맞습니다."},{"q":"순자의 화성기위를 들면서 촉법소년의 악한 본성을 교화하면 선하게 바뀔 수 있다고 했는데 지원자 본인이 생각하는 우리나라 윤리 교육의 방향성은 어떠해야 한다고 생각해요?","a":"현재 우리나라에서는 윤리라는 분야를 주요 과목이 아닌 범교과로 분류하고, 학교에서 이루어지는 윤리 교육은 단순히 영상을 틀어주고 감상문이나 활동지를 작성하는 등 너무나 피상적으로 이루어지는 것이 문제라고 생각합니다. 그래서 저는 우리나라의 윤리 교육이 실생활과 연관되어 학생들이 몸소 느끼고 중요성을 깨달아 훗날 어른이 되었을 때 윤리적이고 올바른 인재로 성장할 수 있는 교육으로 나아가야 한다고 생각합니다."},{"q":"순자 말고 본인이 고등학교 생활을 하면서 좋아하거나 영향을 준 사상가가 있다면 그 사상가의 대표적인 개념 하나와 함께 구체적으로 설명해 보세요.","a":"네, 물론 있습니다. 제가 너무 좋아하는 실존주의 사상가 중 한 명인 사르트르입니다. 실존주의 사상을 한마디로 요약하면 자신이 삶의 주인이 되어 주체적으로 살아가라는 것입니다. 사르트르는 ‘실존은 본질에 앞선다.’라는 유명한 명언을 남겼습니다. 인간만이 세상에 우연히 내던져진 존재로서 자신이 삶의 주체가 되어 능동적이고 주체적인 삶을 살아간다는 의미입니다."},{"q":"만약 수업 시간에 반에서 마음대로 돌아다니면서 방해하는 학생이 있어요. 그런 상황이라도 실존주의에 입각해서 자유롭게 하게 둘 거에요?","a":"<죽은 시인의 사회>라는 영화가 있습니다. 거기에 키팅 선생님이라는 인물이 나오는데, 기존의 수업방식을 깨고 밖으로 나가 들판에 드러누워 수업을 하거나 책상 위에 올라가서 ‘카르페 디엠’을 외치며 세상을 바라보는 시각을 달리하라는 메시지를 던집니다. 키팅 선생님처럼 학생들에게 어느 정도의 자유를 제공하며 각자의 개성을 인정하는 것도 교사로서 필요한 덕목이라고 생각합니다. 하지만 수업을 방해할 정도로 돌아다니는 학생들이 있다면 지금이 수업 시간임을 확실히 알려주고 자리에 앉을 것을 권유하여 자유에도 제한점이 있다는 것을 인지시킬 것입니다."},{"q":"마지막으로 하고 싶은 말 있으면 해보세요.","a":"저는 윤리를 정말 좋아하고 누군가를 가르치는 것도 적성에 맞다고 느꼈는데, 제가 좋아하고 잘하는 것들을 윤리 교사라는 꿈으로 실현하기 위해서 본교의 윤리교육과에 꼭 진학하고 싶습니다. 또한 제가 다른 사람들보다 음악적 재능이 있다고 자신할 수 있는데, 본교에 입학하게 된다면 윤리교육과의 밴드 동아리인 ‘율리타카’에서 활동하며 드럼을 치면서 학교생활을 즐기고 싶습니다. 감사합니다!- 면접관은 남자 두 분이 계셨음. 30대 후반쯤 보이는 오른쪽 분은 푸근한 인상에 잘 웃어주셨는데, 나이가 있으신 왼쪽 분은 잘 안 웃으셨고 당황하게 만드는 질문을 많이 하심. 특이점분위기는 대체로 밝고 좋았음.- 가번호가 스티커로 주어져서 왼쪽 가슴에 부착할 수 있게 함. - 그냥 인사해도 되고 “가번호 ~입니다.”로 해도 상관없다고 함.합/불 분석최초합생기부 기반이라 여러 번 정독하고 예상 질문을 정리하면서 다양한 내용으로 대비했는데 아쉬운 점한 주제로만 너무 파고들면서 꼬리 질문을 많이 해서 아쉬웠음."}],"naesin":"1.17","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100(3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"인문계열","jeonhyeong":"지역균형전형","method":"학생부 기반 면접 대기실 대기 후 순번이 되면 해당 면접실로 이동하여 면접의원 2인이 면접 / 평가함","notes":"학교나 개인정보를 면접 중 말하지 않도록 주의해야함","qa":[{"q":"학생부에 고고학이랑 역사에 관심이 많다고 서술되어 있는데 본인 진로와 관련해서 기억에 남는 탐구활동이 있는지?","a":"최종 진로는 학예연구사다. 학예연구사의 가장 중요한 연구 중 하나는 전시를 기획하고 유물을 구성하는 것이라고 알고 있다. 따라서 3학년 동아리 활동 때 3D 프로그램으로 학교 역사관을 설계해 보는 활동을 통해 이러한 업무를 직접 체험해 보려고 했다."},{"q":"고고학에 관심이 많은 것 같은데 해당 분야에서 벗어나서, 수학 과목에서 인공지능과 빅데이터에 대한 탐구를 많이 한 것 같은데 왜 그랬는지?","a":"1, 2학년 때 탐구를 하다가 고고학에서 유적지 도굴 흔적 탐사에 빅데이터를 활용하는 등, 인공지능 분야에 접목한 시도가 다양하게 이루어지고 있다는 것을 알게 되었다. (답변에 고고학이 또 나오니까 질문한 교수님 웃으심;;) 이러한 인공지능 학습법의 원리가 무엇인지 궁금해서 해당 분야를 탐구해봤다. 따라서 2학년 때 빅데이터 학습에 이용되는 경사하강법을 조사했고 함수 그래프 미분을 통해 그래프의 최솟값을 찾음으로써 인공 지능이 바람직한 정답과 가장 근접한 답을 찾게 하는 방법을 이해했다. 인공지능과 빅데이터가 점점 더 많은 분야에 활용되고 있는 만큼 인문학을 전공하고자 하는 사람도 이러한 기술을 이해할 만한 기본 소양을 갖춰야 한다고 느꼈다."},{"q":"2학년 언매 때 ‘향토색’이라는 거랑 보들레르 철학을 연관시켜서 탐구를 했는데 이에 대해 설명 좀 해줄 수 있는지?(질문이 구체적이지 않아서 당황)","a":"보들레르 철학은 수능특강 지문에서 처음 접했다. 보들레르는 당시 정해진 양식에 따라 고전 속 인물을 그려내던 아카데미 예술은 개성과 생명력이 없다고 비판했고 동시대를 살아가는 인물, 그 인물들이 살아가는 순간 속에서 의미를 끌어내야 한다고 주장했다. 한국에도 근대 개화기에 서양 미술이 전파되면서 예술 양식이 변화될 때 변화를 주도한 사상이나 예술가가 있었는지 궁금해서 한국 개화기 예술을 정리한 책을 읽음."},{"q":"향토색이라는 용어를 사용했는데 향토색이 부정적으로 작용한 구체적 사례가 있는지?","a":"향토색 자체는 국가 고유의 정체성과 세계의 문화 다양성을 지켜주는 것임. 그러나 이러한 향토색이 극단적 보수주의나 수구주의로 변질되었던 사례가 있었다고 앞서 설명한 책에서 읽었다. 한국에도 화가들이 자신의 그림을 소개하고 그림을 전시하는 다양한 행사가 있었는데 책은 서양의 양식을 받아들인 화가들은 해당 행사들에 그림을 전시하는 것이 거부되거나 그림이 자체의 예술적 가치가 아닌 서양 양식의 사용 때문에 비판받았다고 설명했다."},{"q":"그러면 근대 프랑스나 한국에서 본인이 제일 좋아하는 작가가 있는지?","a":"마네가 있다. 그림의 형식뿐만 아니라 내용, 소재 등에서도 혁신을 추구했던 화가였다. 프랑스가 멕시코에 허수아비 정권을 세웠을 때 이를 비판하는 그림을 그려내는 등 사회에도 적극적으로 참여하고 의견을 낸 화가라 좋아한다."},{"q":"아까 학교 역사관 프로젝트 얘기 나왔는데 가장 좋아하는 박물관이 있는지? 그리고 학교 역사관을 만들 때 본인이 가장 중요시한 3가지 물건이 있다면 무엇인지?","a":"국립공주박물관. 유물을 다량으로 묶어서 전시하는 방식이 아니라 유물 하나하나에 집중할 수 있도록 전시관이 구성되어 있어서 좋았다. 무령왕릉을 실제로 재현해놓은 공간도 있고 전시관 자체가 무령왕릉을 발굴했을 때 유물 배치 순서 그대로 유물을 관람할 수 있도록 구성된 공간도 있는데 사람들이 역사를 생생하게 체험할 수 있도록 하는 것 같다. 학교 역사관에 관해서, 학교의 역사는 결국 학생들의 일상으로 구성되기 때문에 학생들의 생활 모습을 드러내는 사물들을 가장 중요하게 생각했다. (1분 남았다는 노크 소리 들림) 따라서 학생들의 생활 모습을 담은 사진, 그리고 학생들의 생활상을 담은 인터뷰를 편집한 자료, 학생들이 봉사활동을 할 때 쓴 사물 등 학생들의 모습 자체를 드러내는 것을 중시했다."},{"q":"수고했습니다.","a":"감사합니다.-아이스브레이킹이 있을 거라고 듣고 갔는데 아이스브레이킹 없었음. 인사하고 앉으니까 ‘학생부 기반으로 진행하는 면접이고 총 3가지 질문을 할 예정입니다. 첫 번째는 학업 역량에 관한 질문입니다’ 하시고 그대로 시작함. (그런데 질문은 3개보다 많았다.)-교수님은 두 분인데 예상 외로 두 분 다 눈 잘 맞춰주시고 질문도 거의 똑같은 빈도로 하심. 특이점두 분 다 젊으신 편이었는데 이건 면접실마다 다를 것 같음. 교수님이 들고 계신 서류는 책상에 세우는 가림막으로 가려져 있음. 얼굴이랑 어깨만 보임.-교수님하고 거리가 1. 5미터 정도로 생각보다 멀게 위치함.-끝나고 나서 생각해 보니 지원동기, 인상 깊었던 도서 등에 대한 질문이 없었음.학생부에 기록된 내용을 꼼꼼하게 다시 복기하고 간 점과 당황스러운 꼬리 질문에 적절히 합/불 분석임기응변으로 아는 것을 토대로 잘 대처하여 대답하였기에 최초합이 가능했다고 생각함.준비해 간 것(지원동기, 도서 등등)과 다른 질문이 나와서 잠깐 당황함. 모든 기대를 버리고 가는 것이 좋을 것 같음. 수학 관련 질문 때 고고학 외 분야에서 답변하길 바라신 것 같은데 아쉬운 점애초에 진짜 목적이 고고학 관련이었던 탐구라서 또 고고학 얘기가 나오니까 교수님 웃으심. 실망의 웃음인지 그냥 순수하게 웃기셨던 건지는 모름."}],"naesin":"1.52","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류평가 100% 【2단계】 1단계 성적 70% + 면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합/지역균형","method":"생기부 면접 큰 대기실에서 앉아서 대기함. (개인 학습 자료 열람 불가) / 면접 10분. 4명씩 무작위로 불러서 면접 시행","notes":"","qa":[{"q":"자기소개 간단하게 해주세요.","a":"고등학교 시절 저는 환경 문제와 사회적 책임이라는 키워드 깊은 관심을 가지고, 기후 불평등을 해결할 방안으로 기업들이 탄소를 감축하면서 개발도상국과 함께 성장할 수 있는 방안에 대해 탐구하였습니다. 또한 지방 소멸과 저출산 문제를 해결하기 위한 기업과 사회의 역할을 친구들과 토의했고, 해결 방안으로 지방에 특수한 산업 분야를 중심으로 스타트업 군집을 형성하여 우량 일자리를 제공함으로써 수도권 인구를 분산하는 방안을 제시하는 등 우리 사회가 지속 가능한 사회가 되는 방법을 탐구해 왔습니다. 이 활동을 통해 환경을 보호하고 사회적 가치를 추구하는 기업 경영이 기업의 이해관계자를 포함한 사회 구성원 모두에게 긍정적 영향을 미칠 수 있음을 알게 되었습니다. 그래서 저는 기업들이 이윤 추구뿐 아니라 사회의 구성원으로서 사회 문제를 해결하는 것에 앞장서도록 하여 정의로운 사회를 만드는 기업 경영가가 되는 것이 꿈입니다.서울대학교 자유전공학부에 입학하여 열린 학문적 환경에서 동료들과 협업을 통해 융합적 지식을 갖추고, 소통하는 능력을 길러서 사회의 긍정적인 변화를 이끄는 데 기여하고 싶습니다.[질문 1번]"},{"q":"그린워싱 관련 활동을 했다고 적혀있는데 그린워싱 사례 말해볼까요?","a":"저는 그린워싱이 심각하게 일어나는 분야가 아기 용품이라고 알고 있습니다. 부모님들이 아기들이 사용하는 물건에는 특히 예민하기 때문에 그런 기업에서는 친환경, 유기농 등의 키워드를 검증 없이 사용하고 마케팅하는 그린워싱이 자주 발생하는 것 같습니다. [질문 2번]"},{"q":"2학년 한국지리와 3학년 동아리 활동에서 지방 소멸 문제를 해결하기 위해 기업 도시를 짓는 그런 활동을 했는데 어떻게 한다는 건가요?","a":"평소 지방 소멸 문제가 심각하다는 것을 뉴스로 자주 접하고 이것의 주요 원인이 지방 도시의 우량 일자리 부족이라고 생각했습니다. 그래서 각 지자체에서 세제 감면 혜택과 지역 대학과의 연계 등의 유인책을 통해서 지역에 스타트업 클러스터를 형성하고, 대기업과의 협업을 통해 하나의 특정 산업도시를 만들어 수도권으로의 인구 유출을 방지할 수 있는 방안을 고민한 활동이었습니다."},{"q":"(꼬리질문) 일자리를 만들어 놓는 그런 건 지자체에서 다 하고 있고 중소기업들도 많이 있는데 인구가 계속해서 유출되는 이유는 뭐라고 생각해요?","a":"저는 그것이 우량의 일자리 부족이라고 생각합니다. 일자리는 많으나 젊은 연령대가 원하는 높은 질의 일자리는 수도권에 몰려 있고, 우리나라에서 투자하는 자본 80% 이상도 수도권에 집중되어 있습니다. 사람들이 원하는 인프라와 우량의 일자리를 만들기 위해서 특정 산업 중심의 도시가 만들어져야 한다고 생각합니다."},{"q":"(꼬리질문) 한국지리 시간에 외국의 도시 기업 사례만 조사했는데, 우리나라 도시에도 이러한 사례가 있죠? 알고 있는 거 있으면 한번 말해보세요.","a":"어.. 외국의 사례를 한국에도 적용해 우리나라 문제를 해결해 보면 어떨까 했던 거라서.. 잘 모르겠습니다.[질문 3번]"},{"q":"ESG 경영에 대해서 많이 한 게 보이는데, ESG 중에서 가장 중요한 게 뭐라고 생각해요?","a":"ESG 모두 경영에 있어서 매우 중요하지만, 저는 지배구조가 가장 중요하다고 생각합니다. 지속 가능한 경영을 위해서는 기업 내부가 청렴해야 하고, 주주에게 이익도 많이 환원하고 전문 경영인을 통해서 기업이 부패하지 않게 유지하는 것이 가장 기본적이고 중요한 부분이라고 생각하기 때문입니다."},{"q":"1분 정도 남았는데 마지막으로 하고 싶은 말 있으면 해보세요.","a":"일단 제 이야기를 끝까지 경청해 주셔서 정말 감사드립니다. 저는 서울대학교 자유전공학부에 입학하여 교수님들, 그리고 학우들과 주제 탐구 세미나 시간에 참여하여 다양한 주제를 다양한 관점으로 토론하면서 학문 간의 경계에 구애받지 않는 융합적인 공부를 꼭 해보고 싶습니다. 또 환경 정책과 인권 문제에 대한 것을 대학교에서 학문적으로 같이 공부하면서 ESG 경영을 전문적으로 하는 경영인이 되고 싶습니다. 정말 열심히 탐구할 자신이 있습니다! 감사합니다.면접실이 협소했고 면접관과의 거리가 생각보다 가까워서 조금 더 편안한 분위기였음.특이점생각보다 무거운 분위기가 아니었고 웃으면서 하는 면접.합/불 분석아쉬운 점답변 말하고 다른 생기부 활동과 관련지어서 보충 답변 했으면 더 좋았을 것 같음."}],"naesin":"1.33","result":"충원합격","resultNote":"최초후 1 보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"자유전공학부","jeonhyeong":"학생부종합/지역균형전형","method":"학교생활기록부 기반 면접 / 다수의 평가자에 의한 다단계 종합평가","notes":"","qa":[{"q":"지원 동기를 말해주세요.","a":"저는 고등학교 3학년 때 제 고장의 인구 감소 문제에 대한 정책 제안서를 작성하는 활동을 했습니다. 이 활동을 통해 제가 지역 사회의 문제를 외부에서 바라보는 것에서 끝나지 않고 그 문제를 해결하는데 보탬이 될 수 있다는 가능성을 발견하게 되었습니다. 이후로 지역 활성화를 도울 수 있는 로컬 콘텐츠 개발자라는 꿈을 가지고 다양한 탐구 활동을 펼쳤습니다. 하지만, 하나의 학문으로는 지역 문제의 근본적인 해결/지역 활성화가 어렵고 지역에 대한 관심, 콘텐츠 기획에 대한 이해뿐만 아니라 공공정책학, 행정학 등 다양한 학문의 융합이 필수적임을 알게 되었습니다. 이러한 깨달음을 바탕으로 학문의 지리적 경계를 뛰어넘는 학제적 사고를 키우고자 서울대학교 자유전공학부에 지원하게 되었습니다."},{"q":"자유전공학부에 와서 어떤 과에 가고 싶은지?","a":"제가 자유전공학부에 입학하게 된다면, 학생 설계 전공과정을 통해 도시학과 경제학, 공공정책학 등을 함께 배울 수 있는 도시 사회학 수업을 개설하여 도시 브랜딩에 대해 체계적으로 배우고 싶습니다. 저는 3학년 영어권 문화 수업에서 미국의 볼티모어가 야구장 개장을 통해 범죄도시에서 스포츠 도시로 이미지 쇄신에 성공한 사례를 조사한 적이 있었습니다. 이때, 저는 도시의 이미지가 관광객 유입, 일자리 창출 등 지역에 미치는 영향력이 크다는 것을 알게 되었습니다. 이를 계기로 제가 사는 지역을 리브랜딩 하고 싶다 생각해 직접 스포츠 명문 도시 OO시라는 테마로 우리 지역을 홍보해보면 어떨까? 하고 관련 영상을 제작해 보았습니다. 해당 영상에서는 경기 장면뿐만 아니라 팬들의 응원하는 모습을 담았으며 이 과정을 통해 저는 도시 이미지가 단순히 지역에 대한 외부인 / 타지인의 관심을 환기하는 것 뿐 아니라, 지역 내 거주민들의 자부심과 공동체 의식을 강화하는 방식으로서 존재 한다는 것을 깨달았습니다. 이때의 흥미를 바탕으로 대학에 입학해서는 도시 이미지가 주민들의 소속감을 어떻게 촉진하는지와 도시브랜드를 구축하는 과정에 대해 체계적으로 배우고 싶습니다."},{"q":"들어보니 지역 도시를 위해서는 여러 학문이 필요해서 자유전공학부에 지원했다는 것 같은데, 우리나라는 서울에 사람이 많이 살잖아요. 서울에 이사를 가고 이런것들은 개인의 선택인데, 문제가 있을까요?","a":"네, 물론 서울에 이사를 가는 개인의 선택에 대해 비판을 가할 수는 없습니다. 하지만, 이런 수도권 과밀화 및 지방 소멸은 국가적 차원에서 불균형으로 이어지고, 이러한 불균형은 민족 공동체의 와해를 유발합니다. 국민들은 자신을 국가의 일원으로서가 아니라 지역적인 집단으로서 인식하게 될 가능성이 커집니다. 이는 민족 공동체의 결속력을 약화시키고, 민족적 통합이나 국민적 연대의 감각을 둔화시킬 수 있습니다. 또한, 수도권에 인구와 자원이 집중되면 지방은 점점 더 소외되고, 지방 주민들은 자신들이 국가 발전에서 제외된 느낌을 받을 수 있습니다. 이는 \"우리나라\"라는 집단 정체성을 약화시키고, 각 지역이 자기 지역 우선주의나 지역주의를 강화하는 결과를 초래할 수 있습니다. 만약 이럴 경우, 국가적 차원에서의 큰 문제가 발생했을 때 연대를 통해 해결할 수 있는 가능성이 적어진다는 점에서 문제라고 생각합니다."},{"q":"근데 이제 미국은 땅도 크고 주 단위로 나라가 운영이 된다하지만 우리나라는 되게 작잖아요? 그런데도 지역이 필요하나요?","a":"우리나라는 영토가 작지만, 꼭 필요하다고 생각합니다. 앞서 말씀드렸듯이, 국가적 차원의 큰 문제가 발생했을 때 ‘국민’이라는 이름으로 연대하여 해결하는 것은 중요합니다. 예컨대, 우리나라가 과거 외환위기를 맞았을 때 대한민국 국민이라는 정체성을 토대로 금 모으기 운동을 진행했었고, 그러한 연대 덕분에 국가 위기를 빨리 해결할 수 있었습니다."},{"q":"민족 정체성 이야기하셨는데, 관련한 활동이 있더라고요? 코즈모폴리터니즘에 대한 보고서를 쓰셨다던데 내용이랑 느낀점을 이야기 해주세요","a":"네, 제가 평소에 생각해오던 세계시민주의는 다른 나라의 일을 우리나라의 일처럼 여기는 것이었습니다. 하지만 1학년 일본 고교 교류 프로그램을 통해 같은 동아시아 문화권, 지리적 인접 국가임에도 사고관과 가치관에 큰 차이를 보이는 것을 보고 과연 제가 생각하던 세계시민주의가 가능할까? 하는 고민에 탐구를 시작했었습니다. 저는 ‘코즈모폴리터니즘이란 무엇인가’라는 책을 참고해서 세계시민주의로 대표되는 코즈모폴리터니즘의 필요성에 대해 정리했습니다. 이후, 진정한 세계시민주의가 되기 위해서는 교내 세계시민 교육의 방향이 바뀌어야 한다고 생각했습니다."},{"q":"그렇다면 난민을 대함에 있어서 지역은 어떤 대처를 보여야할까요?","a":"우선, 난민을 수용하자/수용하지말자 이야기를 하기 앞서 난민을 수용할 수 있는 환경이 마련되어야 한다고 생각합니다. 여기서 말하는 환경은 단순히 행정적 인프라만을 말하는 것이 아니라, 우리의 인식도 포함됩니다. 얼마 전 국내에서도 난민 수용을 두고 의견이 분분했습니다. 저는 이것이 아직 국내가 난민 수용의 환경이 잘 마련되지 않아서 생긴...(시간이 되어 면접 종료)"},{"q":"마지막으로 하고싶은말 있으시면 하세요","a":"네, 저는 앞서 말씀드렸듯이 자유전공학부에 입학하면 꼭 지역 브랜딩에 대해 배우고 싶습니다. 저는 해당 홍보영상을 만드는 활동에서 이미지를 만들어가는 스토리텔링에 정말 큰 흥미를 느꼈습니다. 이때의 흥미를 바탕으로 꼭 도시 이미지를 구축해가는 브랜딩 과정과 이것이 지역 거주민의 소속감에 미치는 영향에 대해 배우고 싶습니다. 이상입니다. 감사합니다.총 4개의 면접실이 있으며, 앞 면접자의 내용이 잘 들림. 면접실에는 2명의 교수님이 계시특이점고 10분의 시간을 정해 놓고 면접을 봄. 3분, 1분의 시간이 남으면 노크로 알려주고 10분의 면접 시간을 넘기려 하지 않으려고 함.학교생활기록부의 전체적인 주제와 방향를 먼저 정한 후, 면접 준비와 예상 답변을 구상하합/불 분석였던 것이 많은 도움이 되었음.아쉬운 점생기부에 기재된 도서의 내용을 답변에 녹이지 못한 점이 아쉬웠음."}],"naesin":"1.02","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"재료공학부","jeonhyeong":"학생부종합/지역균형전형","method":"서류(생기부) 기반 면접 / 1인당 10분, 교수님 2분과 진행","notes":"출석체크 후 면접번호를 부여받고 나면 서류를 보는 등의 행위 불가능 [질문 내용1]","qa":[{"q":"위 학부(재료공학부)에 지원하게 된 동기를 말씀해주세요.","a":"다양한 분야에 관심이 많은 학생으로 빛에 대한 탐구에서 시작해 촉매와 관련한 활동을 진행했습니다. 또한 수소연료전지와 항산화제 관련 연구 활동은 특히 기억에 남습니다. 이러한 다양한 관심사에 대해 '소재'라는 키워드를 잡았고, 특히 서울대학교 재료공학부 홈페이지에서 본 '재료공학은 모든 학문의 근간이 되는 학문이다.'라는 것에서 더욱 실마리를 잡을 수 있었습니다. 특히 앞서 말한 제 활동이 재료공학이 나아갈 촉매와 바이오 분야에 특히 도움될 수 있을 것이라 생각하여 지원하였습니다.[질문 내용2]"},{"q":"다양한 실험을 했다고 하셨는데 정말 그렇네요. 수소연료전지와 관련해서 연구를 했다고 나와있는데 실험을 한 이유가 무엇이고 어떤 실험인지 설명해주세요.","a":"이 실험을 한 계기는 수소연료전지에서 흔히 사용되는 백금촉매의 한계성 때문입니다. 다른 촉매가 더 활성을 나타낼 순 없는지 탐구하기 위해 진행하였고, 이 실험은 촉매의 활성을 평가하기 위한 실험으로 금속결합을 하고 있는 구리봉과 공유결합을 하고 있는 숯과 샤프심을 촉매로 정해 가설을 세워 각 촉매의 활성을 평가하고 그 이유를 찾았던 실험입니다."},{"q":"그럼 그 가설은 뭐였나요?","a":"구리봉의 크기를 두 가지로 설정했던 것과 관련하여 가설을 세웠습니다. 가설을 세울 당시는 단면적이 큰 구리봉이 표면적이 크므로 활성이 높을 것이라 예상합니다. 하지만 실제 실험에서는 반대의 결과를 확인했습니다. 이에 대한 분석으로 전류밀도라는 개념을 통해 해석했습니다. 전류밀도란 전류가 오히려 단면적에 반비례한다는 것으로 이를 통해 결과를 분석할 수 있었습니다."},{"q":"그럼 여태까지 계속 촉매와 관련하여 이야기하고 있는데 촉매에 특히 관심이 있는 이유가 있는지?","a":"공학에서 가장 중요하다고 생각하는 효율과 가장 밀접한 분야라고 생각하기 때문입니다. 공학이 효율을 통해 사람들에게 필요한 것을 만들어내듯이 촉매도 반응 속도에 영향을 미쳐 효율을 추구하는 것 같습니다.[질문 내용3]"},{"q":"또한 항산화 관련 연구에서 사과의 유해성 평가를 진행했다는데 이에 대해 설명해주세요.","a":"그 실험은 2학년 때 진행했던 DPPH assay의 실험의 연장선입니다. 작년의 실험에서 사과가 가장 활성이 높았다는 연구 결과를 얻었고 이를 기반으로 사과를 선정하여 실험했습니다. 사과 시료를 처리한 곳과 처리하지 않은 곳을 대조해보니 그람음성균, 그람양성균과 관련해 그람음성균이 사과 시료에 의해 없어진 것을 알 수 있었고 이에 대한 이유를 두 균의 대표적 차이인 펩티도글리칸 층을 근거로 해석했습니다."},{"q":"그럼 그 그람음성균과 그람양성균은 직접 배양한 건가요?","a":"네. 학교의 물리실과 화학실의 세균을 채취해 직접 배양해 사용했습니다.[질문 내용4]"},{"q":"통합과학 시간에 주기율표를 새로운 경향에 따라 새로 만들었다고 되어 있는데 어떤 활동이었는지 설명해주세요.","a":"다양하게 생각해 보았습니다. 원래의 주기율표는 금속, 비금속, 준금속에 대한 명확한 구역이 나누어져있지 않습니다. 이를 보완해 차례대로 금속, 비금속, 준금속을 배열해 보았습니다. 또한 '일상생활에서 가장 많이 사용되는 원소가 뭐라고 생각해?'라는 질문을 바탕으로 각자 주기율표를 작성해보고 의견을 공유하는 시간 가진 활동이었습니다.[질문 내용5]"},{"q":"(2분 남았다고 밖에서 노크하심) 리더십을 보여준 경험이 있다면 빠르게 말씀해주세요.","a":"1.2.3학년 모두 학급 부반장 맡았습니다. 특히 의견차이가 생겼을 때 중재안을 내놓는 등의 경험이 있습니다. 또한 동아리부장으로서 학교에서 전체적으로 진행하는, 전체 학생 대상으로 한 프로젝트를 맡은 적이 있는데 이와 관련해 소통의 과정에서 리더십을 보일 수 있었습니다.[질문 내용6]"},{"q":"10년 후 무엇이 되고 싶나요?","a":"멘토연구자가 되고 싶습니다. 제가 생각하는 멘토연구자란 신입 연구원과 활동적으로 소통하고 새로운 기술을 가감없이 받아들이는 연구원입니다.(여기까지 말하고 문열림.)밖에서 진행요원분께서 면접 시간이 2분 남았을 때 노크하시고 면접 시간 10분이 끝나면 문을 그냥 여셔서 답변 중이었어도 중단하고 나와야 함. 공과대학 교수님의 1인 사무실을 특이점면접실로 사용해서 바로 앞에서 얼굴 마주보며 면접. 무거운 분위기는 아니고 중간중간 고개도 끄덕이시며 학생이 하는 말을 잘 들어주시는 분위기. 합/불 분석아쉬운 점"}],"naesin":"1.17","result":"불합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( O ) 【1단계】 서류100(3배수) 【2단계】 1단계70+면접30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"첨단융합학부","jeonhyeong":"종합/기회균형","method":"생기부 기반 면접 / 면접관3명에 학생1명,","notes":"꼬리질문을 많이함. 문이 열리면 면접 종료","qa":[{"q":"첨단융합학부는 융합형 인재를 기르는 곳인데 융합형인재가 갖춰야 할 역량이 무엇이라고 생각하나요? 그리고 자신이 융합형 인재로 성장할 수 있다고 생각하나요?","a":"융합형 인재로서 가장 필요한 역량은 소통력이라고 생각합니다. 저는 고등학교 1학년, 반장을 한 경험이 있습니다. 반장을 하면서 아이들의 의견을 하나하나 듣고 최대한 모두가 만족할 수 있는 의견을 수립하려고 했습니다. 이때의 경험으로 키운 소통력을 이용하여 저는 융합형 인재로 성장할 수 있다고 생각합니다."},{"q":"그래요? 그러면 그러한 역량이 가장 필요한 문제는 뭐라고 생각해요?","a":"한 분야의 전공에만 치우쳐있지 않아, 서로 소통하며 협력하는 그러한 공동의 문제, 다양한 전공에 걸쳐져 있는 문제가 발생했을 때 가장 필요하다고 생각합니다."},{"q":"그러면 고등학교 때 실제로 그러한 사회적인, 공동의 난제를 해결하기 위해서 노력했던 경험이 있나요?","a":"네 있습니다. 학년특색활동을 진행했었습니다. 서로 다른 관심분야를 가진 학생들이 모여 지역사회의 문제를 해결하려는 활동이었습니다. 어촌 지역에 요즘 소통의 부재와 젊은 사람들의 일자리가 부족해지고 있는데, 이 문제를 해결하기 위해서 스마트 섬이라는 것을 만들어 해결하려 했습니다."},{"q":"맡은 역할은?","a":"저는 스마트섬이다보니 전력의 문제가 심하여 태양전지의 효율을 높이는 방안을 고안하였습니다. 기존의 태양전지 대신 퀀텀닷을 이용한 태양전지를 활용하여 전력효율을 올리려고 했습니다. (다음질문이 더 있었으나 3분이 끝나 문을 두드림. 생기부 질문으로 넘어감)"},{"q":"과학과제연구, 물리학실험, 인공지능 수학 등 되게 소인수 과목을 수강하셨던데 그 동기가 무엇인가요?","a":"반도체에 관심이 생기면서 물리학실험을 수강하며 물리적 역량을 기르려고 했습니다. 데이터 시트를 만들면서 최소제곱법이 사용된다는 것을 알게 되었고 그러한 최소제곱법을 탐구하기 위해 인공지능 수학을 수강하게 되었습니다."},{"q":"과학과제연구 내용을 보니까 꽤 어려운 걸 다루었는데 탐구하면서 어려웠던 점은? 그리고 어떻게 극복했는지","a":"(긴장해서 대답을 제대로 못했습니다.) 저는....양자역학을 다루다 보니까 처음에는 직관적으로 이해가 되지 않았지만, 양자역학의 역사를 탐구하면서 이해도를 깊게 만들었습니다. <어떻게 극복했는지.>어..여러 자료들도 찾아보고 막히는 게 있으면 선생님께 적극적으로 찾아가 해결했습니다(ㅜㅜㅜ...)"},{"q":"3학년 물리 동아리를 보니 탐구활동을 했는데, 이런 조사 같은 거 말고 실제로 실험활동을 수행한 적 없는지?","a":"네 있습니다. 2학년 때 해파리 흡수율 실험을 진행했었습니다. <진행하면서 어려웠던 점 있나요?> 어..실험을 진행하기 위해선 고가의 실험장비가 필요했었는데 그러지 못했던 점입니다. <어떻게 극복?> 해파리를 동결건조 시켰어야 했는데 동결건조장비가 없어 불가피하게 다른 방안으로 대신했습니다.특이점수학 관련 성적이 모두 1등급우수한 수학, 물리학 성적합/불 분석이를 뒷받침하는 교과세특에서 우수한 자기주도적 역량늦은 진로 선택임에도 불구하고 뛰어난 진로 관련 심화탐구아쉬운 점늦은 진로 선택으로 3학년때만 거의 대부분이 진로 관련 탐구로 진행"}],"naesin":"1.53","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】70% 【2단계】30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"통계학과","jeonhyeong":"학교장추천전형/지역균형","method":"생기부 기반 대기실에서 대기 → 이전 면접자 끝나기 2분 전 면접실 밖에서 대기 → 10분 가 / 량 면접","notes":"","qa":[{"q":"통계학과에 지원한 이유는?","a":"4차 산업혁명 시대에, 저희 삶은 빅데이터, 인공지능과 매우 밀접해 있습니다. 이런 기술들은 가치 있는 데이터를 찾아내, 활용 목적에 맞게 잘 이용하는 것이 중요합니다. 이러한 안목을 배울 수 있는 곳은 통계학과라고 생각하여, 서울대학교 통계학과에 지원하게 되었습니다."},{"q":"통계학과에 입학하여 어떤 방향으로 진로를 희망하는지?(해당 질문에 대한 답변은 구체적으로 기억나지 않아 세부적인 내용은 다를 수 있음.)","a":"전 인공지능, 데이터 마이닝 분야에 관심이 있습니다. (여기서, 내가 그런 분야 위주의 활동을 뉘앙스의 말을 했던 것으로 기억함) 하지만 통계학엔 통계적 방법론을 다루는 분야 역시 있는 것을 알고 있습니다. 그렇기에 저는 서울대학교 통계학과에 입학하여 두 분야를 모두 공부해 본 후 진로 재탐색을 하려 합니다."},{"q":"가치 있는 데이터라고 했었는데, 그럼 가치 있는 데이터는 어떻게 판단하나요?","a":"주관이 개입할 것 같습니다. 여러 논문, 자료 등과 비교해보며 신뢰할 만한 자료인지 판단해야 할 것입니다. 또 데이터가 한 쪽으로 편향되어 있지는 않은지 등을 검토해야 할 것 같습니다."},{"q":"만약 데이터가 원래 편향된게 맞다면?","a":"(당황)...잠시 생각할 시간을 주셔도 괜찮겠습니까?몇 초 시간이 흘러도 답이 나오지 않자"},{"q":"다른 질문으로 넘어가겠습니다. 수2 활동에서 경사하강법이 나왔는데, 자신의 언어로 설명해 보세요.","a":"인공지능에 대해서는, 오차, 즉 다른 말로 손실을 줄이는 것이 중요합니다. 혹시 제스쳐를 좀 취해도 괜찮을까요? (네 가능합니다) x축 y축 좌표평면에 손실함수가 이렇게 생겼다고 해 보겠습니다. 손실을 최소화하는 것이 중요하기에, 여기 이 최솟값을 찾아야 합니다. 미분값이 음수라면 감소함수니, 해당 점이 오른쪽으로 이동하면, 증가하면, 그러니까 x축 방향으로 이동하면 함수값이 감소하게 됩니다. 미분값이 양수라면 그 반대가 됩니다. 이를 통해 미분값이 0인 최솟값을 찾을 수 있게 됩니다."},{"q":"경사하강법이 적용이 안 되는 경우도 있는데, 그럼 어떤 경우에 경사하강법을 적용할 수 있을까요?","a":"(음...우물쭈물...) 미분 같은 계산이 용이한 경우... (교수님: 아까 예로 들었던 그런 경우?) 네, 그런 경우에 적용할 수 있을 것 같습니다."},{"q":"경사하강법이 전역 최솟값이 아니라 다른 곳에 빠질 수 있는데, 어떻게 해결할 수 있을까요?","a":"그때 조사를 해 봤을 때, 확률적 경사하강법이란 것이 있었습니다. 점이 한 번에 이동하는 이동 거리를 조절한다면, 전역 최솟값이 아닌...다른 구덩이에 빠지더라도 진동하며 빠져나와 최솟값에 도달할 수 있습니다."},{"q":"통계와 미래 활동에서 확률적 모델을 설명했다고 했는데, ‘확률적’이란게 어떤 것이었는지 설명해 줄 수 있나요?(저런 느낌이었던 것 같긴 한데 질문이 정확히 기억나진 않음. ‘확률적‘ 이란 용어에 주목해서 질문하심.)","a":"우선 해당 자료에서 연구자들은 O*NET에서 702개의 직업 리스트를 사용했습니다. 여기서 제가 인상깊었던 것은 데이터의 처리 과정에 주관이 개입했던 것입니다. 데이터 중 전산화, 즉 컴퓨터에 대체될 가능성이 확실한 직업에는 1이란 라벨을, 확실히 대체되지 않을 직업에는 0이란 라벨을 붙였습니다. 이렇게 총 70개의 직업에 라벨을 붙였는데, 여기서 제가 정말 인상깊었던 것은, 로지스틱 모형을 사용해서 이렇게 라벨을 부여한 것이 얼마나 적절한지 검토했던 것이었습니다. (그 다음에 뭐라고 더 말했던것 같은데 기억이 안 남. 주관을 최소화하는 그런 방식이 인상깊었다...이런 식으로 말했던 것 같음.)"},{"q":"간단히 말해서 로지스틱 모형에서 확률적인 개념이 사용되었다는 거군요?","a":"네 맞습니다."},{"q":"데이터에 주관이 개입되었다는게 무슨 말인가요?","a":"아까 말씀드린 702개의 직업에 라벨을 매기는 것이었습니다. 전체 직업에 라벨을 붙인 게 아니라 여러 연구원 그룹들이 세미나 등에 참여하며 확실히 전산화 될 직업엔 1, 확실히 대체되지 않을 직업엔 0이란 라벨을 총 70개 부여했습니다. (이 다음에 또 주관 최소화 얘기 꺼냈는지는 잘 모르겠음.)내 자리에도 책상 있었음. 그래도 책상 밑 가림막이 그렇게 길진 않아서 다리를 떨거나 하면 잘 보일 것 같았으니 바른 자세 연습 필요함. 교수님들 테이블과 책상이 붙어있진 않았고, 특이점책상 1개 정도의 간격 있었음. 교수님 2분. 기본적으로 무표정 유지하셨지만 나름 웃으며 대화하는 분위기였던 것으로 기억함.합/불 분석최초합아쉬운 점내게 유리한 방향으로 면접을 이끌고 가기보단 교수님의 질문에 끌려간 경향이 강했음."}],"naesin":"","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100(3배수) 【2단계】 1단계 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"화학교육과","jeonhyeong":"학생부종합/지역균형전형","method":"학교생활기록부 확인 면접 / 지역균형전형, 기회균형전형 함께 면접 실시","notes":"10분, 대기시간 동안 자료 볼 수 없음.","qa":[{"q":"EDTA 실험 과정에 대해 말해보세요","a":"측정하고자 하는 물을 50ml 가량 넣습니다. 그 후에 암모니아 완충 용액과, 에리오크롬 블랙티라는 지시약을 넣습니다. 그 후 EDTA 용액을 한 방울씩 넣어주며 에리오크롬 블랙티가 변색하는 지점을 파악하여 사용된 EDTA 용액의 부피를 이용하여 물의 경도를 계산합니다."},{"q":"꼬리: 암모니아 완충용액을 넣는 이유는?","a":"pH를 10으로 맞춰줘야 하기 때문입니다."},{"q":"pH를 왜 맞춰주어야 하는지?","a":"pH가 너무 낮다면, 수소 이온 농도가 높아, EDTA가 수소 이온과 결합하여 정확한 결과를 얻을 수 없고, pH가 너무 높다면, 탄산이온이 침전되기 때문입니다."},{"q":"수소이온이랑 결합하면 왜 정확한 결과를 얻을 수 없죠?","a":"물의 경도를 측정하는 것이 칼슘이온이나 마그네슘이온과 같은 금속이온들을 측정하기 위함인데, EDTA와 수소이온이 결합하게 된다면, EDTA가 모든 금속이온과 결합하기 위해서는 더 많은 부피의 EDTA가 들어가게 되어 수식 상에서 EDTA 부피 값이 커져 실제 값과는 다른 값이 나올것이라 생각합니다."},{"q":"1학년 때 수학 멘토링 한 것에 대해 말해보세요","a":"당시 저희 반에 수학이라는 과목에 관심이 없는 학생들이 많았습니다. 저는 비교적 수학을 좋아하는 학생이었기 때문에 친구들의 수학이라는 학문에 대한 관심을 높이고자 하는 목적으로 멘토링을 하게 되었습니다. 단순한 지식 전달이 아닌, 학습 목표나 당위성을 스스로 알게 함으로써 체계적인 지식전달을 하려 노력하였습니다."},{"q":"요즘 교권추락과 관련하여 교사하려는 경향이 적은데 왜 지원한건지?, 어떻게 교육할 것인지?","a":"우선 최근 악성민원으로 인해 큰 문제가 발생한 사실을 알고 있습니다. 이에 미리 방지하기 위하여 모든 학생들을 최대한 평등하게 대우할 것입니다. 또한 저의 교육과정이나 신념들을 학부모들과 정기적으로 공유하는 방식으로 진행할 것 같습니다."},{"q":"꼬리: 신념이 무엇인데요?","a":"저의 신념은 교과서에만 나오는 딱딱한 내용을 공부하기 보다, 실험이나 융합을 통하여 학생들이 유연한 사고를 할 수 있게 하는 것입니다. 직접 실험을 하거나 다른 과목과의 연계성을 생각한다면 스스로 유연하게 생각할 수 있게 될 것입니다."},{"q":"1학년 때부터 지금까지 진로가 계속 변해온 거 같은데, 변해온 과정을 말해보세요.","a":"처음에는 환경에 관심이 많았으나, 저 혼자만의 힘으로는 부족하다는 것을 깨닫게 되었고, 과학을 대중화하는 것을 목표로 하여 사람들에게 체계적 지식 전달을 하기 위하여 화학교육과에 지원하게 된 것입니다.특이점사범대이기에 전공과목과 교직에 대한 인적성 관련 질문이 있음.합/불 분석진로희망이 화학교사는 아니지만, 면접에서 화학교육이 필요한 당위성을 적절히 표현함.아쉬운 점없음."}],"naesin":"2.02","result":"최초합격","resultNote":"최초후보순위","suneung":"최저충족","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100%(3배수) 【2단계】 1단계 70% + 면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"서울대학교","dept":"국어교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"대기실 → 복도 대기(5분) → 면접장(생기부 기반 면접) / 면접시간 10분 내외 / 면접위원 2명","notes":"압박 면접 분위기에 주눅들지 않는 연습을 많이 했는데, 이와 완전히 반대로 너무 부드럽게 “음~”, “어~” 해주시면서 계속 들어주셔서 오히려 당황했습니다. 면접장도 학과장실 같은 데서 본 것 같은데 분위기가 좋으니 딱딱하게 이야기하지 않고 계속 풀어가면서 지나치게 길게 이야기해 아쉬움이 남습니다. 계속 들어주신다고 계속 이야기하지 말고, 적당히 끊어서 1분 내외로 답변하는 연습하세요! · 8시 30분 정도에 모든 짐(자료, 외투, 가방 등 : 신분증, 수험표 빼고 전부)을 제출하고 대기했습니다.(물은 요청하면 한 병 주심) 면접 순번을 미리 알 순 없고, 자기 순번 5분 전에 관리원분께서 부르시면 복도로 나가서 대기하는 시스템이었습니다. 17번째로 3시간 대기했는데 그 시간 동안 속으로 헷갈렸던 답변 연습을 하며 긴장을 풀어서 오히려 좋았습니다. 앞 순번은 일찍 끝나니 좋은 거고, 뒷 순번은 여유있게 마음의 준비를 할 수 있어 좋으니 순서에 연연하지 말고 답변 내용에만 집중해 준비하세요! · 활동의 기승전결을 묻는 것과 더불어 정말 이 주제에 관심을 가지고 있는 학생인지 묻는 것 같다고 느꼈습니다. 모든 활동 과정을 다시 복기하고 외우는 것은 당연하고, 생기부에서 두드러지는 활동 및 적어도 관련 계열의 활동은 정말 진실하게 관심을 가지고 배경지식을 쌓고 면접장에 들어가시길 권유드립니다!","qa":[{"q":"1학년 때 영어로 글쓰기한 게 되게 재밌었어요~ 재능과 운의 요소가 둘 다 중요하다는 글을 썼는데 조금 더 자세하게 설명해주세요.","a":"1학년 때 친구를 보고 적었던 글이었습니다. 그 친구는 공부를 하고 싶은데 계속 잠이 온다고 이야기해서 구체적인 방안과 동기부여를 자주 해주었는데 (이 부분도 지나치게 풀어서 이야기해 아쉬움이 남음) 그런 모습을 보면서 노력을 하는 데 타고나는 기질적인 특성과 동기부여를 받을 수 있는 환경 등의 요소도 중요하다고 깨달아 쓴 글이었고 내 자신을 겸손하게 돌아보게 되는 활동이었습니다."},{"q":"교육학 시간에 인쇄 기반 문화에서 디지털 기반 문화로의 전환 과정에서 뇌의 읽기 회로가 변한다는 내용으로 수업 시연을 했다고 하는데, 구체적으로 읽기 회로가 어떻게 변하는지 구체적으로 설명해주세요.","a":"기본적으로 인쇄문화는 상호 소통이 아니라 독자가 주체적으로 이해해야 하기 때문에 내용이 일목요연하고 체계적일 수밖에 없고, 디지털 기반 문화는 영상 매체인데 영상 매체는 추상적인 내용을 구체적으로 이야기하기 때문에.. (이 답변하는데 이해가 안 되는 듯한 표정이셔서 예를 들어 덧붙여 설명함 ) 깊이 읽기가 어렵습니다. 때문에 뇌가 깊이 읽기에 익숙하지 않게 되고 이런 뇌를 가지고 인쇄 매체로 글을 읽을 때 일목요연하고 체계적인 글을 흡수하는 능력이 떨어지기 때문에 문해력이 현재 문제가 되고 있습니다."},{"q":"요즘 문해력이 글을 읽는 개념에서 영상을 보는 능력으로 개념이 바뀌고 있다~ 이런 이야기도 있는데 이거에 대해선 어떻게 생각하세요?","a":"문해력의 궁극적인 목적은 세상을 이해하고 사고를 확장하기 위해 매체를 이용하는 것이라고 생각합니다. 때문에 읽고, 말하는 능력에서 더 나아가 보고, 듣는 것까지 포함해 리터러시의 개념으로 확장해 문해력을 바라보아야 하고, 문해력이 좋다, 나쁘다의 기준은 세상을 이해하고, 사고를 확장하는 데 적절한 매체를 얼마나 잘 활용하느냐가 기준이 되어야 한다고 생각합니다."},{"q":"학생 생기부를 읽어보니까.. 뭐에 관심이 있는지 잘 나타나 있는 것 같아요. 능력주의나 문해력 같은.. 3학년 때 시험능력주의와 관련한 활동을 했는데 현재 우리 사회에 나타나는 능력주의도 있잖아요? 사회의 능력주의가 나타나는 원인이 뭐라고 생각하는지, 그리고 이를 학교 측면(교육측면이라고 하신 것 같기도 한데 기억이 잘 안 남 )이 아니라 사회 측면에서 어떻게 보완해야 한다고 생각하는지 말씀해 주세요.","a":"잠시 생각할 시간을 주시겠습니까? -> 네~ -> 체감 상 10초 ~ 20초 정도 생각한 것 같음.현재 한국 사회에서 능력주의가 심한 원인은 학력주의 때문이라고 생각합니다. 이 학력주의가 나타난 데엔 수능이 중요한 요소가 되는데 수능은 단일한 가치로 사람을 판단하고 그 결과가 중요시되는 사회 속에서 청소년 시기 학생들이 성공과 실패의 경험을 한다고 인식합니다. 그런 생각들이 청소년기에서 성인기로 넘어 갈 때 너무 중요하게 각인 돼서 사회에 능력주의가 만연해진다고 생각합니다.그리고 능력주의 사회를 보완하기 위해선 문화적 차원의 정부 지원이 있어야 한다고 생각. 경제적으로 부유한 집안과 아닌 집안에서 문화적 지원은 부모가 해줄 수 있는 한계가 있기 때문에.. (이 뒤로 계속 설명했는데 결론을 어떻게 지었는지 기억이 안 남) -> 이 답변하면서 밖에서 노트 소리가 나서 시간이 거의 다 됐다는 걸 알게 됨.)"},{"q":"그럼 그 과정에서 발생할 수 있는 차별이나 혐오 문제는 생각해 봤나요? 빨리, 짧게!","a":"어.. (노크 소리 들리고 빨리, 짧게 말하라고 하셔서 당황함, 한 5초 ~ 10초 정도 당황해서 면접관분들 번갈아가면서 바라봤던 것 같음 )"},{"q":"됐어요! 이만 나가봐도 돼요~","a":"(시간이 다 돼서 나가라고 하신 것 같음 -> 인사하고 나옴 )"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"물리 천문학부(물리학전공)","jeonhyeong":"학생부종합(일반전형)","method":"대기실 입실 → 신분확인 → 문제풀이 → 면접 → 퇴실 / 면접시간 15분 / 면접위원 2명","notes":"같은과끼리 대기했음, 시험장 앞에서 선배들이 응원함 · 들어가서 공부 불가라고 할때부터 아무 것도 볼 수 없음. · 핸드폰은 자신이 소지하나 가져온 가방에 꺼서 넣어놔야함. · 일단 답을 맞추는 것이 가장 중요함 · 밖에서 문제를 풀고 들어가는데 면접장 안에서 필기도구를 쓸 수 없고 오직 말로만 설명해야하며 그러므로 추가 질문이 나올 때 필기도구가 없는 것에 당황하지 말 것.","qa":[{"q":"푼 문제부터 답을 부르고 풀이과정을 설명해봐라","a":"1-1은 1번 문제는 포물선 운동을 빗면에서 다루는 문제입니다. 이럴 때 저는 빗면을 기울여 제가 볼 때 수평으로 만들고 중력가속도를 수평성분과 수직성분으로 분해하여 등가속도 운동방정식을 각 방향에 적용했습니다. (적용한 식을 설명하고) 탄성충돌을 고려하니 답이 ~이 나왔습니다.(답이 상수로 숫자였음)1-2은 공을 여기서 굴리면 떨어질 때 속도가 ~가 되는데 그대로 탄성충돌하여 충돌 전, 후 속력이 같고 이를 이용하면 탄성충돌이 원래 가던 방향대로 진행을 시켜보면 더 쉽게 구할 수 있다고 생각했습니다. 그냥 포물선 운동으로 계산하면 ~이 됩니다. (1-3(1),(2)는 잘 기억이 나지 않지만 쉬운 문제였음. (3)이 어려웠음) 포텐셜이 최소인 지점까지 내려가기 때문에 더 운동합니다.1-4은 답만 말함.Q1-1: 조건을 ~로 바꿔서 풀어보세요.(암산으로 풀 수 있는 수준이었음) 답함. (맞은 문제에 대한 추가질문이었던 것 같음.)"},{"q":"2-1번 말해보세요.","a":"전기력, 중력과 전자의 운동량 변화를 구하면 진자의 기울어진 각도를 구할 수 있습니다.이를 이용하여 계산한 과정 식 설명하고 답 말함.(1번은 제시문 관련 없어보였음)"},{"q":"2-2번 말해보세요.","a":"속도는 커지는데 가속도는 작아질 것입니다."},{"q":"2-3번 말해보세요.","a":"제시문을 사용하여 평형식을 세운 과정을 설명하고 계산 과정을 통해 구한 답을 설명함.(2-4번도 마찬가지)]"},{"q":"1-4번 답을 다시 보시겠어요? 답 틀렸죠?","a":"네"},{"q":"풀이를 어떻게 했어요?","a":"풀이과정 설명함."},{"q":"풀이 과정은 맞았는데 왜 틀렸지?","a":"(연필이 없어서 계산을 다시 할 수가 없었음, 많이 당황했음)풀이 과정을 다시 검토함."},{"q":"시간이 남았는데(3분정도 남았던 것 같음) 더 할말 없나요?","a":"문제지 뒤적거림."},{"q":"수고했어요.","a":"감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"산업공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"신분확인 → 대기실 입실 후 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 2명","notes":"한 대기실에서 항공우주과 친구들과 같이 대기 · 대기시간동안 자료 모두 못 보고 전자기기 사용 못함. · 제 생기부는 인문학적 소양을 많이 어필해서인지 인문학적 질문을 많이 하셨습니다. 산공과라는 과 자체의 특성을 잘 이해하는 것이 특히나 중요하다고 생각합니다. · 교수님들이 분위기를 편하게 이끌어주시고 압박 질문은 거의 없는 편이었습니다.","qa":[{"q":"산업공학과에 지원하게 된 동기를 이야기해 주세요.","a":"지속가능한 발전이 중요해진 사회에서, 국가와 기업이 인간과 환경을 위하는 일이 중요해졌습니다. 저는 국가와 기업이 인간과 환경을 위하는 방법을 택하려면, 결국 그 방법이 그들에게 경제적으로 이익이 되어야 한다는 것을 깨달았습니다. 따라서 산업의 최적화를 통해 국가와 기업의 변화를 선도하는 산업공학자가 되고자 산업공학과에 지원하게 되었습니다."},{"q":"활동 중에서 ‘실리콘밸리 사람들은 어떻게 일할까’라는 책을 읽고 활동을 했다고 나오는데, 이 책을 설명해보세요.","a":"이 책은 실리콘 밸리의 업무 방식을 이야기하는 책입니다. 우리나라에서는 아직 성취지향적인 성향이 뚜렷하고, 많이 일한 사람이 일을 잘하는 사람이라고 생각합니다. 그러나 실리콘 밸리는 다릅니다. 그들은 짧게 일해도 효율적으로만 일하면 된다고 생각합니다. 그리고 이런 생각을 뒷받침하는 확실한 성과금 제도, 해커톤 문화가 조성되어 있습니다. 이 책을 통해 어떻게 노동생산성을 효율적으로 증대시킬지 고민할 수 있었습니다."},{"q":"본인이 추구하는 본질적 목표가 무엇인가요? (삶의 목표를 묻는 질문이었음)","a":"모든 인간이 그러하듯, 저의 목표는 행복입니다. 인간은 사회적 동물입니다. 인간은 다른 동물처럼 날카로운 이빨을 가지고 있지도 않고, 힘이 세지도 않아서 타인이 없으면 한없이 나약해집니다. 따라서 인간의 행복은 결국 그 인간이 속한 공동체의 행복에서 온다고 생각합니다. 공동체가 행복하려면, 사회적으로 소외 받는 사람이 없어야 합니다. 따라서 저는 사회적 약자를 위한 기술을 연구하는 산업 공학자가 되어야겠다고 생각했습니다."},{"q":"생기부를 보면 스마트시티에 관심이 많은 것 같은데, 스마트시티가 뭐라고 생각하나요?","a":"스마트시티라는 것이 굉장히 추상적인 개념인데요, 저는 기술을 통해 인간의 삶의 질을 향상시키는 도시를 스마트 시티라고 생각합니다. 제가 제시했던 스마트 시티의 비전은 효율적인 도시, 약자를 위한 도시, 친환경적인 도시였습니다."},{"q":"전반적으로 ‘효율’에 관심이 많은 것 같은데, 산업공학자의 기본적인 역량이 뭐라고 생각하나요?","a":"자신이 설계하고 있는 기술 자체에 대한 수리과학적 이해, 데이터 분석을 통해 최적화된 효율적인 해를 찾으려는 노력, 마지막으로 사용자가 그 제품을 어떻게 사용하고 소비할지 인간을 이해하는 태도가 중요하다고 생각합니다."},{"q":"인간에 관심이 많다고 했는데, 인간을 이해하기 위해 어떤 노력을 했나요?","a":"저는 철학이 인간을 이해하는 좋은 방법이라고 생각하여 고전과 윤리라는 과목을 선택하여 수강하였고, 다양한 철학 책을 읽었습니다."},{"q":"그러면 읽었던 철학 책 중에 기억에 남는 책 있나요?","a":"장자입니다. 이 책에서 제가 깨달은 것은 아까 설명한 실리콘밸리 이야기와도 같은 맥락인데요. 장자가 따르는 도가 사상에서는 상선약수, 물과 같이 흐르는 삶을 가장 좋은 것으로 여깁니다. 흘러가는 대로 살고 싶은 것은 인간의 본성일 수 있겠다는 생각을 하게 되었습니다. 따라서 이런 인간의 본성을 잘 이해하여, 노동자에게 적절한 보상과 성과금을 주어 노동 생산성을 증대할 수 있다는 것이 중요함을 깨달았습니다."},{"q":"리더로서 활동한 경험이 있나요?","a":"네, 저는 반장과 동아리장 활동을 했습니다. 스마트 시티 플래너라는 동아리에서 동아리장으로 활동하였는데, 이 동아리는 다양한 공학분야에 관심 있는 친구들을 모아 스마트시티에서 어떻게 인간의 삶의 질을 향상시킬지 고민하는 동아리였습니다. 저는 이 동아리 활동을 통해 각 공학 분야가 어떻게 협력하는지 배웠고, 리더로서 어떻게 구성원들의 능력을 적재적소에 배치하고 협력하도록 이끄는 방법을 배웠습니다. 또한, 노인을 위한 열쇼크 방지 시스템 고안, 친환경 단열재 실험 등을 진행하며 산업공학자로서 추구해야할 가치를 정립할 수 있었습니다."},{"q":"그런 활동을 하는 게 쉽지 않았을 것 같은데, 어려운 점은 없었나요?","a":"실험 설계적인 측면에서 답변 드려도 되겠습니까?"},{"q":"네. 자유롭게 말씀하세요.","a":"친환경 단열재의 효율을 측정할 때, 열 전도가 잘 되는 그릇에 단열재를 설치하여 실험을 진행하였습니다. 그릇 안에 뜨거운 물을 넣고 온도가 하강하는 정도를 측정하는 식으로 실험을 진행했는데, 단열재가 구조적으로 안정적이지 않았기 때문에 저희가 예상했던 것보다 온도가 빠르게 하강하여 비교가 어려웠습니다. 구성원들과 함께 고민하여, 열이 반대로 이동하는 경우를 생각하였고 얼음을 녹이는 방식으로 단열재의 성능을 측정하여 효율을 비교할 수 있었습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"생물교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"질문과 답변을 반복하여 구성함. / 면접시간 10분 / 면접위원 2명","notes":"2:1로 진행하였으며 기본적인 질문들이 많았음. · 생기부에 적혀있는 활동 및 내용보다는 교직에 필요한 역량을 자세하게 듣고싶어 하는 분위기였음. · 충분하게 답변 시간을 부여받았으며 면접관들의 리액션이 좋은 편이었음. · 자신의 내용과 활동을 교직관과 연결하여 충실하게 준비하는 것이 필요하다고 생각함.","qa":[{"q":"사범대를 언제부터 희망했나요?","a":"중학교 3학년 때 가정사로 방황하던 시기가 존재하였습니다. 이때 저희 담임선생님께서 그러한 저를 보고 다양한 대화와 상담을 통해서 라포를 형성하셨고 이에 저는 방향성과 앞으로 나아갈 용기릉 얻었습니다. 저는 그러한 선생님을 존경하였고 평소 친구들과 지식을 공유하여 상호 발전하기를 좋아해 교사라는 직업을 희망하였고 이러한 경험이 사범대를 희망하게된 계기가 되었습니다."},{"q":"생물교육과를 졸업하면 어떤 진로가 있나요?","a":"일반적으로는 중등학교 교사가 되어 학교 현장에서 교육을 실천하는 경우가 많을 것이지만 생물 교과다 보니 생명과학 연구원이나 의약계열도 가능할 것입니다. 뿐만 아니라 교육을 현장이 아닌 제도적으로 실현하는 교육과정 평가원이나 교육청의 일도 존재합니다."},{"q":"교사에게 필요한 것은 무엇인가요?","a":"교사는 크게 기본적으로 인성적 부분과 학문적 부분에 대한 역량이 중요하다 생각합니다. 인성적으로는 학생들을 사회 구성원으로서 책임감을 가지고 사회에 동화될 수 있게 하는 것이고, 학문적으로는 단순히 지식을 전달하는 것이 아니라 그 지식을 학생이 자신의 흥미와 적성과 연결하여 지식 기반의 사회적 가치를 창출하는 것이 중요하다 생각한다. 이에 교사는 학생들의 세계에 방향성을 제시할 수 있는 다양한 경험을 하는 것이 가장 필요하다 생각하며 서울대학교에 입학하면 snu in the world와 교환학생, 교육봉사 활동에 참여하여 학생들에게 다양하게 도움을 줄 수 있는 교사가 될 것입니다."},{"q":"생물교사에게 필요한 것은 무엇인가요?","a":"지식기반의 사회적 가치 창출을 학생으로 하는 것이 중요하다 생각하기에 생물교사에게 있어서 학생들에게 다양한 시각울 제공하는 능력을 기르는 것이 가장 필요하다고 생각합니다. 현재의 교육과정이 대입목적에 맞게 유전학에 비중이 많이 가해지고 면역학이나 생태핟에 비중이 많지 않다는 것이 학생에게 미시적 시긱을 기를 기회만 제공하고 거시적인 다양한 시각을 제공할 슈 없는 부분이 아쉬웠습니다. 따라서 학생에게 올바란 시각을 제공할 수 있도록하는 교육과정을 재구성하는 능력도 생물교사에게 필요한 능력이라고 생각합니다."},{"q":"스테로이드의 항상성에 대해서 보고서를 썼는데 무엇을 학습하였나요?","a":"지식기반의 사회적 가치 창출을 학생으로 하는 것이 중요하다 생각하기에 생물교사에게 있어서 학생들에게 다양한 시각울 제공하는 능력을 기르는 것이 가장 필요하다고 생각합니다. 현재의 교육과정이 대입목적에 맞게 유전학에 비중이 많이 가해지고 면역학이나 생태핟에 비중이 많지 않다는 것이 학생에게 미시적 시긱을 기를 기회만 제공하고 거시적인 다양한 시각을 제공할 슈 없는 부분이 아쉬웠습니다. 따라서 학생에게 올바란 시각을 제공할 수 있도록하는 교육과정을 재구성하는 능력도 생물교사에게 필요한 능력이라고 생각합니다."},{"q":"평가지를 만들어 학우분들과 나눴는데 자세히 설명해주세요.","a":"학생들과 배운 내용을 공유하며 상호발전하기를 좋아하여 다양한 평가지를 만들었습니다. 1학년 때는 접할 수 있는 평가도구가 지필고사와 모의고사 밖에 없었기에 현 대입 양식의 평가지를 만들었습니다. 하지만 이러한 양식이 현 교육과정이 요구하는 다양한 요소들을 평가할 수 없다는 것을 알게 되었습니다. 2학년 때는 기존의 방식과 다른 오류 발전 유전 프로그램 평가양식을 만들었고 학생들에게 적용한 결과 긍정적인 반응을 이끌었습니다. 하지만 이 또한 기존 대입 시스템의 내부에서 진행된다고 생각이 되어 3학년 때는 기존에 질적으로 아쉽다고 느껴진 생태학 부분에 대해 독서 논술식 문항을 개발하여 적용해보고 평가 기준까지 새워보았으며 학생들과 오류를 발견하고 토의하며 평가에 대한 이해와 상호발전을 이루어 냈습니다"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"수리과학부","jeonhyeong":"학생부종합(지역균형전형)","method":"대기실 대기 → 순서가 되면 방앞에서 대기→입실 / 면접시간 10분 / 면접위원 2명","notes":"친절한 교수님들이 진행하는 편안한 분위기 · 학문관련된 학과는 교수님들의 전공분야에 따라 질문이 편향될 수 있음(어디에서 물어보실 지 모르니 철저히 준비 예) 난 다른 분야에 관심이 있는데 해석학이나 선형대수학 부분을 집중적으로 물어보실 수 있음.) · 지원동기, 리더십, 책 등은 하나도 안 물어보시고 처음부터 끝까지 수학내용만 물어보심.","qa":[{"q":"1학년에 고급수학을 들었네요? 고급수학을 수강한 동기와 들으면서 가장 중점적으로 공부한 것은 무엇인가요?","a":"고급 수학 지식들을 접하면서 학교에서 공부한것만으로는 부족하다 생각되어 고급수학을 수강하게 되었습니다(약간 더듬음). 제가 고급수학을 들으면서 가장 중점적으로 배운것은 ‘고유벡터’였는데요, 고유벡터에서 특히 회전행렬의 고유벡터에 대해 연구하면서 복소고유벡터를 알게 되었고, 복소고유벡터가 과연 어떤 방식으로 표현될 수 있을지, 그리고 어떤 의미를 가지는 지에 대해 탐구하였습니다."},{"q":"고유벡터는 어떤 의미를 가지나요(?)","a":"고유벡터는 회전변환..아니, 선형변환만의 특징을 잘 설명하는 벡터인것 같습니다. 고유벡터란 선형변환에 의해서 방향이 바뀌지 않는 벡터인데, 다른 벡터들은 선형변환에 의해 크기나 방향이 바뀌는 반면 고유벡터는 방향이 유지되기 때문에 선형변환만의 특징을 잘 설명해주는 벡터라 생각합니다."},{"q":"고유벡터는 항상 구할 수 있나요?","a":"(당황, 약 10초간 생각함)…제 생각에는 항상 구할 수 있을 것 같습니다. 선형변환에 대해서는 구할 수 있을 것.."},{"q":"(끊으면서)고유벡터를 구하는 방법에 대해 설명해보세요.","a":"고유벡터는 선형변환에 람다를 곱한 항등행렬을 뺀 다음 이 행렬의 행렬식이 0이 되어야함을 이용하여 연립방정식..아니 이차방정식과 연립방정식을 계산하여 구합니다."},{"q":"테일러 급수에 대해 공부한거 같은데 테일러 급수에 대해 말해주세요.","a":"테일러 급수는 해석함수를 도함수들의 한점에서의 값으로 구성된 항의 무한합으로 표현하는 방법입니다. 테일러 급수에서 항은 n팩토리얼 분에 (x-a)의 n제곱에 f의 a에서의 n번째 도함수를 곱한 꼴로 표현됩니다. 이렇게 구한 테일러 급수는 초월함수나 다항함수로 표현하기 힘든 함수를 다항함수로 표현할 수 있다는 것에 의의가 있는 것 같습니다."},{"q":"푸리에 급수에 대해서도 공부한거 같은데 푸리에 급수가 뭔가요?","a":"푸리에 급수는 주기함수를 사인과 코사인에 가중치를 곱한 것으로 구성된 무한합으로 표현하는 방법입니다. 푸리에 급수에서 가중치는 삼각함수의 직교성을 이용하여 적분하면 계산할 수 있습니다."},{"q":"푸리에 급수와 테일러 급수의 차이점은 무엇인가요?","a":"먼저 푸리에 급수는 주기함수를 무한합으로 표현하는 방법이고, 코사인과 사인을 이용해서 항을 표현한다는 점이 다른 것 같습니다.(잘 생각이 안나 말한것 반복)"},{"q":"테일러 급수는 항상 원래함수와 같나요?","a":"항상 일치하지는 않습니다. 테일러 급수는 매끄러운 함수를 대상으로 하는데, 그중에서도 테일러 급수와 원래함수가 일치하는 함수를 해석함수라고 합니다."},{"q":"미적분 시간에 감마함수에 대해 연구했다고 나와 있는데 이에대해 설명해주세요.","a":"lnt의 n제곱의 부정적분에 대해 탐구하면서 lnt의 n제곱의 부정적분과 n-1제곱의 부정적분이 팩토리얼의 점화식과 비슷하다는 것을 느꼈습니다. 이를 통해서 팩토리얼의 점화식과 일치시키기 위해 적분구간을 0~1로 설정하여 상수항을 없앴고, -가 반복하여 나오는 것을 없애기 위해 -lnt를 적중하는 것으로 바꿔 팩토리얼의 점화식을 만들 수 있었습니다. 이를 통해서 감마함수를 유도할 수 있었습니다."},{"q":"1학년때 원뿔곡선에 대해 심층탐구하고 실생활에서 활용되는 사례를 조사했다는데 예시를 말해주세요.A10답변 : 원뿔곡선 중 포물선은 평행한 직선이 입사했을 때 초점으로 모인다는 성질이 있습니다. 그래서 이런 성질을 활용하여 의료계에서는 빛을 한 곳으로 모아 결석을 제거하는 기술이 있는 것을 알고 있습니다.","a":""},{"q":"그거 말곤 없나요?","a":"네..딱히 생각이 나지 않는 것 같습니다."},{"q":"볼츠만 분포와 정규분포와의 연관성에 대해 설명해주세요.","a":"볼츠만 분포를 탐구하면서 볼츠만 분포식이 지수함수의 -제곱 꼴로 표현된다는 점과 볼츠만 분포의 그래프가 정규분포와 유사하다고 생각되어 비슷하다고 생각했었습니다."},{"q":"아까 테일러 급수가 항상 원래함수와 같지 않다고 했는데, 그런 경우 어떤 방식으로 테일러 급수가 일치하는 구간을 구할 수 있는지 설명해보세요.","a":"테일러 급수와 원래함수가 일치하는 구간을 계산하기 위한 방법은 비판정법을 활용하는 방법입니다. 비판정법은 a의 n번째 항분에 a의 n+1번째 항이 n이 무한대로 갈 때 1보다 작은 값으로 수렴해야 함을 이용하여 급수의 수렴성을 따지는 방법입니다."},{"q":"만약 급수의 항들이 비로 잘 표현되지 않는 경우는 어떻게 계산할까요?","a":"어..급수의 항들이 지로 잘 표현되지 않는 경우..(여기서 시간이 끝났니다. 시간이 끝났다고 알려주셔서 대답할 수 없었어요.)어.."},{"q":"대답 안하셔도 됩니다.","a":""}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"에너지자원공학과","jeonhyeong":"학생부종합(지역균형전형)","method":"면접시간 10분 / 면접위원 2명","notes":"면접관 분들과의 거리가 생각보다 많이 가까웠음 · 면접 대기실에서 전자기기 걷은 후에는 가져온 모든 자료 볼 수 없음","qa":[{"q":"화학, 생명 등 다른 과가 많은데 하필 우리 학과를 어떻게 지원하게 되었는지 이유좀 말해줄수 있을까요?","a":"저는 에너지의 지속가능한 발전과 소비에 기여하고 싶은 학생입니다. 전 세계적으로 인구는 계속 증가하고 있고, 1인당 에너지 소비량도 증가하는 상황에서 에너지의 확보는 필수적입니다. 그러나 화석연료는 자원이 한정되어 있어 고갈 문제가 있고, 지구 온난화의 원인이 된다는 점에서 대체 에너지의 개발이 필수적인 상황입니다. 저는 고등학교에 들어서서 이러한 문제를 해결할 수 있는 방안에 대해서 배웠습니다. 태양광이나 풍력과 같은 신재생 에너지, 그리고 핵융합 발전에 대해서 알아가면서 이를 개발하고 발전시키는 연구원이 되겠다는 꿈을 가졌고, 그래서 이 학과에 지원하게 되었습니다."},{"q":"그러면 연구원이 되고 싶은 건가요? 우리 학과에 와서 배우고 싶은거나 해보고 싶은게 있나요?","a":"네. 제가 여러가지를 배우다 보니 고등학교 수준에서는 이해할 수 없는 것들이 많았는데요, 저는 그 중 탄소포집저장활용 기술에 대해서 배우고 싶습니다."},{"q":"에너지의 개발에 어쩌다 관심을 가졌는지, 동기가 있나요?","a":"시작은 유튜브나 뉴스에서 기후 변화의 심각성에 대해서 많이 얘기를 하는데, 이에 대한 두려움에서였던것 같습니다."},{"q":"평소 일상생활에서 행복한 일과, 학업적으로 행복했던 경험 각각 하나씩 말해주시겠어요?","a":"일상생활에서는 제가 캐릭터 인형을 좋아해서, 이런것들을 판매하는 곳에 가서 구경할 때 행복하다는 감정을 느끼는 것 같습니다. 네 ㅎㅎ 학업적으로 가장 성취감을 느꼈던 경험으로는 1학년 때의 동아리에서 진행한 연구에 있었습니다. 유난히 녹이 슬어있는 시약장 경첩의 성분을 확인하는 연구였는데 처음 설정한 가설에서 예상과 다른 결과가 나와 가설을 수정하고, 다시 탐구해서 결론을 도출하는 과정이었습니다. 이 과정을 통해 ‘이것이 과학이다’ 라는 생각을 하게 되었습니다."},{"q":"수학 문제 풀이를 즐긴다고 나와있었는데, 수학 문제 푸는걸 좋아하시나요?","a":"중고등 학교 때는 수학 문제를 푸는 것을 좋아했습니다. 그러다 점점 과학 분야에 사용되는 다양한 수학적 개념에 흥미를 느꼈습니다. 교내 여러 탐구활동을 통해 좀 더 높은 수준의 수학 개념과 문제를 접하였습니다. 재미도 있었지만 제가 많이 부족한걸 느끼는 것 같습니다. 앞으로 대학교에서 제 부족한 부분을 더욱 보강하고 싶습니다."},{"q":"심화수학은 과목이 따로 있는거에요?","a":"네. 교육과정에 있는 과목이었습니다."},{"q":"앞으로 에너지를 어떻게 사용하고, 개발해 나아가야하는지에 대해서 말해줄수 있나요?","a":"화석 연료를 이용한 에너지 생산 방법에서 최대한 빨리 탈출하는 것을 최우선으로 생각해야 할것입니다. 신재생에너지와 핵융합 같은 에너지 생산방법에 집중해야 한다고 생각합니다. 우선 기존의 신재생 에너지의 효율을 향상시키며 시간을 벌어둔 후 핵융합 발전을 완성시키는 방향으로 진행해야 할 것 같습니다."},{"q":"핵융합에 대해서 말했는데, 핵융합은 언제쯤 사용이 가능할지..","a":"사실 지금 당장은 아니고, 세계적으로 진행되는 연구의 목표가 2040~50년 까지이므로, 그때쯤 상용화가 될 것 같습니다."},{"q":"다시 돌아가서 고등학교 생활을 한다면 가장 해보고 싶은일, 그리고 고등학교에 들어와서 가장 잘한일 하나씩 말해주세요","a":"우선 제가 고등학교에 입학할 때로 돌아간다면 가장 해보고 싶은 일은 코딩, 컴퓨터 이쪽 분야를 배워보고 싶습니다. 그리고 고등학교에 와서 가장 잘했다고 생각되는 일은 화학 동아리에 가입한 것 입니다."},{"q":"화학 동아리에서 어떤 활동을..?","a":"아까 말씀드린 연구인데, 자세히 설명해도 될까요? (대답 듣고 세부 과정 이야기 함)"},{"q":"그럼 물리학을 배울때, 가장 재미있었던 부분과 힘들었던 부분 있나요?","a":"네. 저는 물리학 1을 배울때 역학 부분이 그림상으로 무언가 표현되어있고, 이를 통해 값을 구하는 부분에서 가장 재미있었습니다. 가장 어려웠던 부분은 파동 부분을 배울때 어렵다고 생각한 것 같습니다."},{"q":"이제 곧 시간이 다 될것같은데, 마지막으로 하고 싶은 말 있나요?","a":"대답하려는 찰나 시간 다 됐다고 문 열려서 인사 후 나옴."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"역사교육과","jeonhyeong":"학생부종합(기회균형특별전형)","method":"면접 대기실 → 면접 실 옆 자리에서 대기 → 면접실 / 면접시간 10분 / 면접위원 2명","notes":"입실 마감 후에 수험표, 신분증, 물 제외 모든 물건을 가방에 넣으라고 하시고 그 가방을 다른 교실로 옮기기 때문에 대기하는 동안 아무것도 볼 수 없습니다.","qa":[{"q":"3학년 사회문제 탐구 시간에 ‘인문학 위기에 맞선 인문학 교육의 방향 모색’이라는 주제로 연구를 진행했는데 이 연구를 하게 된 계기와 배운 점 또는 느낀 점을 말해보세요.","a":"우선 활동을 한 계기부터 말씀드리겠습니다. 평소에 뉴스 기사를 보는 것을 좋아하는 저는 기사를 보던 도중 이과 편중 현상과 의대 쏠림 현상이라는 사회적 현상, 문제를 접하게 되었습니다. 저는 이와 같은 사회적 문제가 학생들의 인문학에 대한 관심도가 떨어져서라고 생각하여 인문학 교육 방향에 대해 연구하였습니다. 이 연구를 진행하면서 저는 학생들이 생각하는 인문학, 인문학 위기의 원인, 인문학 교육에 대해 알 수 있었습니다. 학생들은 인문학을 인간과 관련된 학문, 인간의 문화나 역사 등 삶의 모습을 담은 학문이라고 생각하였으며, 경제적인 가치가 뚜렷이 드러나지 않는다는 점에서 인문학에 관심이 가지 않는다고 말하였습니다. 예를 들어, 과학 기술 같은 분야는 그 발전이 사회에도 잘 드러나지만 인문학은 그렇지 않는다는 점에서 이 이유를 말하였습니다. 그리고 학생들은 인문학의 내용이 평소 많이 접해보고 대부분 알고 있는 내용이라 인문학 교육에 흥미를 느끼지 못한다고 하였습니다. 저는 이를 바탕으로 앞으로의 인문학 교육에 대해 생각해 보았습니다. 앞으로의 인문학 교육은 인문학 캠프와 같이 인문학을 재밌게 접할 수 있는 교육 기회가 마련되어야 하고, 학생 중심의 협동 수업이 이루어져야 한다고 생각하였습니다."},{"q":"학생 중심의 협동 수업이 프로젝트형 수업을 말하는 건가요?","a":"네"},{"q":"그러면 프로젝트형 수업이 인문학 위기를 해결할 수 있다고 생각해요?","a":"당장은 해결되긴 힘들지만 프로젝트형 수업이 계속 이루어진다면 인문학 위기를 해결하는 데에 도움을 줄 수 있다고 생각합니다. 그 이유는 저는 인문학 위기의 원인을 학생들의 인문학에 대한 낮은 관심도라고 생각했기 때문에 학생들이 중심이 되는 협동 수업, 프로젝트형 수업이 이루어진다면 학생들의 인문학에 대한 관심, 흥미를 끌 수 있어 인문학 위기 해결에 이바지할 수 있다고 생각합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"전기정보공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"진로 희망등의 일반적인 질문들, 생기부 세세한 내용들을 위주로 준비함. 그런데 실제 면접에선 열심히 탐구했던 주제 몇가지만 질문하셔서 크게 긴장하지 않고 답변할 수 있었음. 특히 프로그램을 만든 부분에 관심을 가지고 많이 물어보셨는데, 실제로 과정 하나하나 다 프로그래밍했던 내용이라 세세한 내용까지 잘 답변할 수 있었음. · 면접 분위기는 편하게 답할 수 있는 분위기였고 면접을 한다는 느낌보단 지원자가 했던 활동에 대해서 편하게 이야기를 나눈다는 느낌이였음.","qa":[{"q":"곡률에 대해서 왜 조사했나요?","a":"교과서에 곡률 식만 소개됨. 자세한 수학적 증명과정 궁금해서 탐구했습니다.Q1-1: 외적개념을 활용했다 했는데 좀 더 자세히 설명해 주세요.곡률의 기본 정의에서부터 식까지 유도과정중 벡터미적분학 사용. 이 과정을 간편하게 가기위해 외적 사용했던것으로 기억합니다.Q1-2: 그럼 3차원 상황에서 증명한것인가요?딱히 한정짓진 않았지만 외적사용했으면 3차원에 적용가능할 것 같습니다.Q-3: 조사는 어떤식으로 했나요?주로 인터넷을 찾아보고 모르는 부분은 선생님께 질문드렸습니다."},{"q":"3학년 물리학2 시간에 이중진자 프로그래밍 활동을 왜 했나요?","a":"과학과제연구 시간에 물리엔진을 구현했습니다. 더 다양한 상황을 프로그래밍해보고 싶어서 이중진자에 대해서도 탐구했습니다.Q2-1: 어디까지 구현했나요?(계산식 or 시각화)시각화까지 했습니다.Q2-2: 어떻게 탐구했나요?이것도 비슷하게 혼자 인터넷으로 조사하다 모르는 부분은 선생님께 여쭤 보았습니다.Q2-3: 어려운 점은 없었나요?장력을 구현할때 처음엔 용수철 상수를 높게 잡으면 실처럼 작동할줄 알았습니다. 하지만 제 프로그램은 프레임 단위로 했기 때문에 (Q: 중간질문 - 프레임 단위면 시간? A: 네) 물체의 이동에 약간씩 오차가 있어 떨림현상이 나타났습니다.Q2-4: 재밌었겠네요?네, 재밌었습니다.Q2-5: 이런게 수업 프로그램에 있었나요?딱히 없었지만 그냥 관심이 생기면 발표할 수 있는 환경은 있었습니다.Q2-6: 주제는 선생님이 잡아주신 건가요? 아니면, 직접 찾은 건가요?처음 제가 관심이 생겨 찾아보다가 모르는 게 있으면 선생님께 질문을 드렸고, 선생님께서 어떤 부분을 더 봐라 하면서 이끌어 주셨습니다.Q2-7: 공부하느라 시간도 없을 텐데 이런 건 왜 했나요?그냥 코딩으로 구현하는 과정이 재밌어서 고등학교 생활 동안 꾸준히 했습니다."},{"q":"3학년 진로 레이트레이싱 구현 활동(이 활동 질문하시기 시작할 쯤 노크소리가 들렸음)도 시각화까지 한 건가요?","a":"네.Q3-1: 하기 어려웠을 텐데 전반적으로 어땠는지 설명해 주세요.시간이 얼마 없으니 일반적인 구현법이랑 다른 부분만 말씀드리겠습니다. 첫 번째는 공간구현을 폴리곤(3d그래픽의 기본단위 삼각형)으로 하기엔 데이터 생성이 힘들었습니다. 그래서 수학적 정의로 공간을 구현했습니다. 이로 인해 이후 빛의 충돌판정을 할 때 폴리곤이였으면 간단하게 계산할 수 있는 것을 빛을 조금씩 전진시켜 츙돌을 판단하게 만들었습니다. 그런데, 이는 최적화 측면에서 불리했습니다.두 번째는 가상면에 대한 것입니다. 원래는 구면이여야 할 가상면을 평면으로 가정하고 프로그래밍했기에 시야 외곽으로 갈 수록 확대되며 왜곡되는 문제가 있었습니다.(Q: 중간 질문 - 그래서 어떻게 해결했나요?) A: 삼각함수를 활용하여 곡면으로 가상면을 바꾸면 좋았겠지만, 당시에 시간이 부족하여 시점과 가상면 사이의 거리를 늘리는 임시방편으로 해결했습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"정치외교학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"암기는 별로 도움이 되지 않은 것 같습니다. · 평소에 어떤 생각을 하고 있는지를 확인하는 질문들이 위주인 것 같아요. · 그리고 꼬리질문이 계속 이어져서 생기부 자체에 대한 질문은 적었습니다.","qa":[{"q":"국제정치와 관련하여 보편적 가치에 관심이 많은 것 같은데 왜 관심이 많죠?","a":"저는 인간의 존엄성이 가장 중요한 가치라고 생각하기 때문입니다. 인간은 인간이라는 자체로 존중받아야 마땅하며 이것에 대해 계속 추구해 나아가야한다고 생각합니다. 그래서 저는 보편적 가치를 다루는 것이 중요하다고 생각했습니다."},{"q":"학생에게 보편적 가치란 무엇인가요?","a":"저에게 보편적 가치란 생명권, 자유권, 재산권입니다. 그리고 추가적으로 참정권 또한 자신과 관련한 문제에 대해 직접 해결해나가는 권리라고 생각해서 이 권리 또한 보편적 가치를 지니고 있다고 생각합니다.(Q1,2번과 관련해서 꼬리질문이 계속 이어졌습니다. “어떻게 저 권리들을 보편적 가치라고 할 수 있는가,시대와 상황에 따라 다른 것이 아닌가”,“저 가치들을 실현하지 않은 나라들에게는 저 가치들을 실현하는 나라들이 더 이상한 것이고 보편적인 것이 아닌게 아닌가?”,“그럼 저 가치를 실현하지 않은 나라들을 어떻게 설득할 것인가?”,“북한과 같은 나라들도 나름의 논리를 가지고 있는데 그들에게는 그것이 보편적 가치를 실현하는 것이 아닌가?,”우리나라에서 특히 더 잘 실현된다고 생각하는 보편적 가치는 무엇인가?“"},{"q":"학생은 진로가 어떻게 되죠?","a":"저는 명확하게 아직 어떤 진로, 직업을 정하지는 않았습니다. 하지만 제가 고민하고 생각하는 문제에 대해서 답을 찾아 나아가고 싶습니다. 그 고민으로는 평화를 실현하는 과정에서의 폭력이 어디까지 정당화될 수 있느냐와 관련한 문제입니다. 평화 상태에서는 당연히 폭력이 없어야하지만 평화를 실현하는 과정에서는 공격에 대한 방어,구조적 폭력에 대항하여 민주정을 설립하려는 혁명 등 예외적인 예시를 생각하니 고민이 들었습니다. 그래서 이 문제에 대해 계속 생각하고 저의 답을 찾아나가기 위해 노력하고 싶습니다.(꼬리 질문:“과거부터 많은 학자들이 평화를 추구하려고 노력해왔음에도 불구하고 매우 어려운 일이다. 그리고 인간의 역사에서 폭력과 전쟁을 빼놓을 수는 없다. 이에 대해 어떻게 생각하는가?”)"},{"q":"고등학교 생활 중 가장 자신에게 큰 영향을 끼친 도서는?","a":"저는 <두 도시 이야기>가 가장 기억에 남습니다. 이 책은 프랑스 혁명 당시의 영국 런던과 프랑스 파리에서 있던 일을 다루고 있는 장편 소설입니다. 이 책이 저에게 끼친 영향은 평화를 실현하는 과정에서의 폭력에 대해 생각해보게 하였기 때문입니다. 프랑스 혁명은 구조적 폭력을 깨고자 하는 목적에서 실현이 되었습니다. 하지만 이 폭력이 정당한 목적을 위해 이루어졌다고 하더라도 이 과정에서 관련이 없는 민간인의 희생 등 폭력의 비참함 또한 다루어졌습니다. 그래서 저는 평화를 위해 폭력이 어디까지 정당화될 수 있을지 고민이 이 책으로부터 시작되어 <두 도시 이야기>가장 영향을 많이 끼친 도서입니다.(꼬리질문:“그럼 학생은 폭력이 사용될 수 없다고 생각하나요?”"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"철학과","jeonhyeong":"학생부종합(일반전형)","method":"신분 확인 → 대기실 입장 → 다시 신분 확인 → 대기 → 면접실 복도 앞에서 대기 후 준비 / 면접시간 구상 30분, 답변 15분","notes":"수험생에게 믿기지 않을 수준의 자율성을 제공함. 전자기기를 따로 수거하지 않고, 본인 가방에 넣어 보관하라고 하는 등 정말 시험이 아닌 면접의 느낌이 강했음. · 추가 질문에 교수님의 의도가 전부 숨겨져 있었는데 현장에서의 긴장감 등으로 의도를 파악하기 어려웠음.","qa":[{"q":"‘역사학의 허구성’이 (나)와 (다)에서 각각 어떻게 나타나는가?","a":"기본적으로 합리적 사고를 통해 역사적 사실을 재구성하는 데에 초점을 맞춘 역사학은, 사료에 기반한 합리적인 추론을 거칠 수 있는 내용만 ‘역사적 사실’로 간주합니다. 그러나, 사료가 부족하여 알 수 없는 내용이나 질적인 맥락 등의 경우 연구자가 과거로 돌아가서 알아볼 수 없으므로 사실적 검증을 거칠 수 없습니다. 따라서 역사학자의 생각이나 상상 등 사료에 기초하지 않은 내용을 추가하여 전체적인 맥락을 파악합니다. 저는 역사적 허구성이 이처럼 사료로만 알 수 없는 것들을 알게 해주는 도구라고 생각합니다. (나)에서 역사적 허구성은 ‘사람들이 권위에 순응하였다’라는 진술입니다. 실제로 그들에게 그러한 압력이 작용했는지, 혹은 그들이 그렇게 느꼈는지를 알 수 있는 별다른 근거가 제시되지 않았습니다. 따라서 이는 역사학자가 추측한 내용으로, 허구성에 해당합니다. (다)에서 역사적 허구성은 ‘유대인 혐오 감정’입니다. 이 역시 사람들이 실제로 말한 내용, 즉 사료에서는 드러나지 않는 내용으로, 허구성에 해당합니다. 이들은 공통적으로 감정적인 맥락 등 질적인 측면의 역사적 분석을 위해 역사학자의 주관에 일정부분 의존합니다."},{"q":"역사학처럼 사실성과 허구성이 나타나는 다른 학문의 예시를 들어보시오.","a":"인류학에서 민족지 연구를 할 때, 연구자의 주관이나 편견이 최대한 배제되어야 합니다. 여기에서 사실성은 기술된 인류학적 특성으로 볼 수 있습니다. 그러나 단순한 사실의 나열은 학술적 의미가 없기 때문에, 연구자의 해석이 가미될 수밖에 없으며 이는 역사학의 허구성에 대응될 수 있을 것입니다."},{"q":"그러면 역사학자는 자기 마음대로 이야기를 지어낼 수 있는가?","a":"그런 것은 아닙니다. 일정한 수준의 근거를 제시하고 자신의 이야기를 하여야 하지, 단순히 본인의 주관이라 하여 사실인 것처럼 말해서는 안 됩니다."},{"q":"근거라고 하였는데, 그 근거에는 무엇이 있을지?","a":"만약 자연과학이라면, 자연과학은 세계를 정밀하게 기술하는 것을 목표로 하기에 타당성 등을 검증할 객관적 수치/지표들이 있습니다. 그러나 역사학은 인문학으로서 이러한 것들이 존재하지 않기 때문에, 학계에서 합의를 통하여 도출된 일정한 이론이나 주장에 기반하여야 합니다."},{"q":"그렇다면 철학의 경우와, 자연과학의 경우는 어떨까요?","a":"잠시 생각할 시간을 주시겠습니까? (시간을 조금 많이 씀) 이어서 답변하겠습니다. 철학의 경우 사실성의 영역은 논리적 논증과 그 결과들, 허구성은 직관이라고 생각합니다. 아무리 철학적으로 명료하고 정치한 논증구조, 예를 들면 공리계 등을 설계하더라도, 그 전제를 파고들어가다 보거나 모순되는 지점을 찾다 보면 심리적인 직관이 요구되는 경우가 있습니다. 이때 우리는 우리의 심리적 직관의 작동 규준이나 존재 근거 등을 제대로 파악하지 못하기 때문에, 논리 구조에 포함될 수 없는 외부적 요소라는 점에서 역사학의 허구성에 대응합니다. 다음으로 자연과학에 관하여 말씀드리겠습니다. 자연과학의 경우, 앞서 말했듯 허구성이 끼어들 자리가 점차 줄어들고 있습니다. 과학적 방법론이 발전하고 연구가 이뤄지면서, 세계를 신뢰할 수 있는 정도를 측정할 표준들이 지속적으로 개발되고, 개선되고 있습니다. 따라서 사실성에 해당하는 검증된 과학적 연구들이 점차 늘어나고 있습니다. 반대로 허구성에 해당하는 것으로는, 현대에는 거의 찾아보기 어렵지만, 일부 최신분야가 잉태되고 초창기의 연구가 진행되는 과정에서는 ‘과학적 상상력’ 등으로 표현되는 과학자들의 주관이나 상상이 반영되고 있습니다. 이를 허구성에 해당하는 부분으로 볼 수 있고, 자연과학에서 허구성은 분야의 발전에 따라 점차 줄어들 것임을 다시 요약하며 답변 마칩니다.<사회과학>가) ‘아이가 타고 있어요’ 스티커를 붙이면 타 차량 운전자들에게 경각심을 주어 사고를 예방할 것이라 생각하고 스티커 여부에 따른 사고율을 조사했다. 스티커가 있는 차량은 사고율이 낮아졌지만, 이것이 부모에게 경각심을 준 결과는 아닐까?나) 생존자 편향 (인터넷에 검색하면 있는 그 전투기 사례 그대로)"},{"q":"(가)와 (나)에 나타난 문제점의 공통점과 차이점을 분석하시오.","a":"이 두 문제는 모두 문제를 해결하기 위해 데이터를 사용하였지만, 의도와 다른 결과를 가지게 되었습니다. 공통점으로 데이터의 활용에서 오류를 범하고 있다는 점이 있습니다. (가)의 경우 변인통제가 제대로 되지 않아, 다른 요인이 개입하기 쉽고 실제로 개입하였습니다. 반면 (나)의 경우 표본 추출 과정에서 오류가 있었습니다. 표본의 크기가 충분히 크지 않고 표본추출이 편파적으로 이뤄져 대표성을 충분히 확보하지 못했습니다."},{"q":"(가) 또는 (나) 사례와 유사한 사례를 들고, 이유를 설명하시오.","a":"심리학에서의 ‘학부생 문제’가 있습니다. 대학생이 주변에 많기 때문에, 심리학 연구에서 표본으로 대학생들이 집계되기 더욱 쉬운 경향이 있어 표본의 대표성이 떨어질 수 있습니다."},{"q":"2번 질문 다시 답변해주세요. 누구를 대상으로 한 심리학 실험이기에 왜 문제가 되는지를 설명해야 더 나을 것 같아요.","a":"일반적인 대중, 즉 전 세계 사람이나 전국민에게 일어나는 심리적 현상을 연구하는 실험이라고 해본다면, 대학생들이 표본으로 추출되는 비율이 크다면 문제가 발생합니다. 이들은 비교적 소득수준이나 연령, 교육수준이 일정하기 때문에 과대대표되는 문제가 생길 수 있습니다."},{"q":"그러면 2번 질문에서 (가)와 관련지은 사례는 없나요?","a":"한국사회에서는, ‘대학 졸업자들 중 부유층의 비율이 높다’라는 이유로 대학에 가면 돈을 벌기 쉬울 것이라는 말을 합니다. 그러나 이는 (가)처럼 상관관계와 인과관계를 혼동한 분석입니다."},{"q":"(나)도 인과-상관관계를 혼동한 것 같지 않나요?","a":"총알자국의 개수가 부품의 안정성에 주는 영향에 대한 따로 판단이 나와있지 않으므로 그런 것 같지는 않습니다."},{"q":"시간이 거의 끝났는데, 마지막으로 인문학 제시문 답변 중에, 철학적 사실성과 역사학적 사실성이 질적으로 다르다고 생각하지 않나요?","a":"다르다고 생각합니다. 철학적 사실성은 주로 연역적 논리에 기반한 반면, 역사적 사실성은 제시문에 ‘경험주의’라는 언급이 있듯 경험적 외부 자료에 기반했습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"철학과","jeonhyeong":"학생부종합(일반전형)","method":"30분 동안 제시문 숙지와 답변 구성(인문 제시문1, 사회 제시문1로 총 2개), 15분 동안 답변 / 면접시간 30분(준비시간), 15분(답변시간) / 면접위원 2명","notes":"서울대는 꼬리질문으로 유명함. 교수님이 한 질문에 답변해 나가는 상호작용 과정이 중요함.","qa":[{"q":"(가)지문의 역사학의 모순에 대한 내용을 말하고, (나), (다)에서 이와 관련지어 말하라?","a":"(가)지문에서 역사학의 모순이라고 말한 까닭은 주관적인 사례를 들어 보편적 진리를 찾으려고 하기 때문임. (나)에서는 ‘나치당 지지 세력의 말’이라는 주관적 내용을 들어, (다)에서는 ‘사람의 가치관’과 ‘사람의 행위’라는 주관적 내용을 들어서 나치당 지지 세력의 내적 동기의 보편적 진리를 찾으려고 하고 있음."},{"q":"위에서 말한 역사학의 모순과 유사한 특징을 지닌 예를 하나 제시하시오?","a":"철학과 유사함. 객관적 자료에 근거하여 탐구하는 과학과 달리, 철학은 인간의 사유라는 주관성이 반영될 수 있는 요소를 통해 객관적 진리를 찾고자 하기 때문임.Q2-1: 철학, 역사학과 같은 학문은 객관적인 과학과 같은 학문과 달리 객관적일 수 없다는 것임?...답변 제대로 못 해서 비슷한 질문만 2-3번 반복함..지문2: 사회지문(가)자동차 뒤에 ‘아이가 타고 있어요’라는 표지판이 붙어있을 때, 사고율이 줄어든다는 연구결과 제시. 이 결과에 기반하여 해당 표지판이 사고율을 낮춘다는 주장 제시. 그러나 진짜 해당 표지판이 사고율을 줄이는 것인지에 대한 의문 존재함을 첨언. 사고율 감소의 원인이 표지판에 있는 것이 아니라, 부모의 조심성에 있다는 새로운 가능성 전개. 표지판을 붙인 부모들이 애초 조심성이 많은 사람들이 다수이기 때문임. 결론은 표지판만으로는 사고율 감소의 결과를 확신할 수 있는지 모른다는 것임 (나)전투기를 보완해야 하는 상황 제시. 전투기의 일부분만을 보완할 수 있는데, 그 일부분을 어디로 해야 하는지에 대한 2가지 주장 전개. 1번째 주장은 전쟁에서 돌아온 전투기들을 보았을 때, 가장 총알을 많이 맞은 부분을 보완해야 하다는 주장임. 해당 부분이 총알을 맞기 쉬운 위치이기 때문. 2번째 주장은 전쟁에서 돌아온 전투기들을 보았을 때, 가장 총알을 안 맞은 부분을 보완해야 한다는 주장임. 표본이 전쟁에서 돌아온 전투기들 뿐이기 때문에, 전쟁에서 돌아오지 못한 전투기가 어느 부분을 총에 많이 맞아서 못 돌아왔는지 알 수 없음. 따라서, 전쟁에서 돌아온 전투기들이 총을 많이 맞은 부분은 애초 치명적이지 않기 때문에 돌아올 수 있었다는 가정을 한다면, 전쟁에서 돌아온 전투기가 총을 많이 맞지 않은 부분이 가장 치명적인 부분이라는 것임."},{"q":"(가), (나) 상황의 특징을 비교하시오.","a":"(가), (나)의 공통점은 둘 다 표본의 대표성 문제라는 점이다. (가)는 표지판을 붙인 부모를 표본으로 정함으로 인해 자연스럽게 조심성이 많은 사람이 표본이 되게 되었다. 이로 인해 조심성이 없는 사람은 표본으로 사용하지 못하게 되면서, 조심성이 많은 이와 적은 이가 공존할 수 있는 전체 모집단을 해당 표본이 대표하지 못하게 되었다.(나)는 전투에서 돌아온 전투기만을 표본으로 함으로 인해 전투에서 돌아오지 않은 비행기는 표본으로 사용하지 못하게 되면서, 전체 모집단을 표본이 대표하지 못하게 되었다.차이점은 (가)의 운전자의 조심성이라는 요소는 사고율과 직결된다고 말하기에는 다소 주관성이 반영될 수 있기에 조심성이 없다고 반드시 사고가 많이 나는 결과를 낳는다고 단언할 수 없다는 점..(나)는 이와 달리 총에 맞아서 전투기가 추락했다는 결과를 낳는다는 것은 단언할 수 있다는 점.."},{"q":"(가), (나) 상황과 유사한 예를 제시하시오.","a":"(가)는...(기억이 안 나요..)Q2-1: (가)에서 표본의 대표성 문제를 해결하려면 어떻게 해야 하는가?표지판을 붙인 부모뿐만 아니라, 그저 일반 운전자들을 표본으로 데려다가 표지판을 붙이게 한 후 일정 시간 동안 도로를 주행하게 한다. 이때 주변 자동차들의 동향, 표지판을 안 붙였을 때보다 공격적으로 주행하는 차들이 주변에 적은지, 많은지 등등을 확인하여 표본의 대표성 문제를 해결할 수 있다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"서울대학교","dept":"화학생물공학부","jeonhyeong":"학생부종합(지역균형전형)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"학교가 관악산에 있어서 아침에 매우 춥습니다. 옷 따뜻하게 입고 가세요. · 대기 시간에 가져간 자료를 볼 수 없습니다. 면접장 가서 생기부 공부할 생각하지 마세요.","qa":[{"q":"3학년 때 촉매 관련 실험을 진행하였는데 배경이 무엇인가요? 또 어떤 방식으로 실험을 진행하였나요?","a":"저는 화학 2를 공부하면서 교과서에 촉매의 표면적이 넓어질수록 촉매의 효율인 아진다는 것을 알게 되었고, 이를 실험으로 확인하기 위해 실험을 계획하였습니다. 결과 비교를 위해 두 가지 실험을 준비하였습니다. 첫 번째는 은거울 반응을 이용해 은박을 만들었고, 두 번째는 은 콜로이드를 합성하여 과산화 수소를 분해하는 실험을 진행하였습니다. 실험 결과, 정량적으로 측정할 정도는 아니지만, 은 콜로이드로 분해하였을 때 과산화수소가 더 빨리 분해되었습니다. Q1-1: 이 실험에서 아쉬운 점이 있었나요? 있었다면 어떻게 해결할 수 있릏까요?실험 결과를 정량적으로 분석하지 못한 점이 아쉬웠습니다. 은 콜로이드를 합성하는 양에 은의 몰수를 맞추면 은박이 너무 조금 만들어져서 이를 분석하기 힘들었던 것 같습니다. 이를 해결하기 위해서 많은 양의 콜로이드를 만들고, 이를 조금만 덜어서 실험을 진행하면, 큰 은박을 이용해실험을 진행할 수 있을 것이라 생각합니다."},{"q":"반장 활동 같은 리더 역할을 많이 했는데 자신의 리더쉽이 잘 드러난 사례를 이야기해 주세요","a":"저는 1학년 때 동아리 기장을 맡아 동아리 페스티벌에서 실험 체험을 준비한 적이 있었습니다. 1학년이다 보니 동아리 페스티벌에 대해 자세히 몰랐고 어떻게 준비해야 하는지도 잘 몰라서 동아리에서 정한 펜로켓 실험을 기간까지 다 준비하지 못할 것 같다는 생각이 들었습니다. 그래서 친구들의 의견을 물으니 대부분 그럴 것 같다는 생각을 하였습니다. 그래서 방안을 물으니 차선책으로 준비 시간이 적게 걸리는 다른 실험을 동시에 준비하자는 의견이 나왔습니다. 처음에는 반대하는 친구들도 몇 있었지만 동아리 페스티벌을 준비해야 하는 동아리의 상황을 설명하니 모두 납득하여 실행으로 옮겠습니다. 결국 첫 번째 싫험은 다 준비하지 못하였고, 두 번째 실험으로 정안 발열팩 만들기 실험으로 동아리 페스티벌을 진행하여 호응을 얻었습니다. 위기 상황에서 동아리의 상황을 잘 파악하고, 구성원의 의견을 수렴하여 해겳 방안을 모색하였다는 점에서 리더로서 잘 행동했다고 생각합니다."},{"q":"삶의 목표가 무엇인가요?","a":"저는 행복이 삶의 목표입니다. 저와 주변 사람들의 행복이 가장 중요하다고 생각합니다. 현대 사회에서 돈의 중요성이 강조되고 있지만, 이는 수단일 뿐 궁극적인 목표는 행복이 되어야 한다고 생각합니다. 이 생각은 저의 진로와도 연관되어 있다고 생각합니다. 저는 연구자가 되어 인류에 도움이 되는 연구를 진행하고 싶습니다. 이는 저와 주변 사람들뿐만 아니라 많은 사람들의 행복을 가져와 줄 것입니다."},{"q":"자신이 생각하는 사회 문제에는 무엇이 있나요?","a":"저는 의대 쏠림 문제가 심각하다고 생각합니다. 훌륭한 인재가 모두 의대로 (진학하는 것은 국가적인 문제라고 생각합니다.면접 시간 종료)"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"}],"official":[{"category":"","jeonhyeong":"","q":"3학년 자율활동에서 자연이자율 하락의 해결책으로 평균인플레이션 목표제를 제시했는데 평균인플레이션 목표제의 개념을 설명해보세요. 한국 경제의 적용 가능성은 어느정도인가요? 물가안정목표제와 평균인플레이션목표제 장단점 비교해보세요. 한국 경제에 어느 것이 더 적합하다고 생각하나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"학업역량","jeonhyeong":"","q":"3학년 동아리활동에서 ‘국민을 위한 국민연금은 없다’와 정부의 재정계산 자료를 탐독하여 국민연금의 현재 상황과 연금개혁안 간의 충돌을 문제 삼았는데 국민연금의 현재 상황은 어떠한가요? ‘연금개혁안’의 충돌 문제는 무엇인가요? 국민연금의 지속 가능성을 확보하기 위한 과제에 대해 생각해본 적 있나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"}]};
